(window.GIM_TS=window.GIM_TS||{})["Menachot.3"]={"from":72,"a":[["\u0003בלאו\u0004 של \u0003\"לא תסור\u0004 מן הדבר אשר יגידו לך\" (דברים יז, יא), כלומר, רק דבר שחכמים אסרוהו נדחה מפני כבוד הבריות, אבל לא איסור של תורה, וצריך הייתי להוריד את טליתי מעלי.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0005סוגיה זו באופן אחר:\u0006 \u0003מהתם\u0004 \u0005[משם]\u0006 במקום שבו נפסקה הקרן של הטלית של מר בר רב אשי \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא שנפסקה, \u0003ואמר ליה\u0004 \u0005[לו]\u0006 מר בר רב אשי: \u0003מאי דעתיך, למישדייה\u0004 \u0005[מה דעתך, שאזרוק אותה,\u0006 את הטלית מעלי\u0005]?\u0006 \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003גדול כבוד הבריות שדוחה את לא תעשה שבתורה!\u0004 ומקשים: \u0003והא תרגומה\u0004 \u0005[והרי תרגם אותה]\u0006 \u0003רב בר שבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב כהנא\u0004 שמדובר שם \u0003בלאו\u0004 של \u0003\"לא תסור\"\u0004 ולא באיסור טלטול ברשות הרבים, שהוא מן התורה! ומתרצים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אינו אסור מן התורה, כי המקום שהיו בו לא היה רשות הרבים ממש, אלא \u0003כרמלית דרבנן\u0004 \u0005[ש\u0006אסורה \u0005מדברי סופרים]\u0006 \u0003היא.\u0004","","\u0003התכלת\u0004 שבציצית \u0003אינה מעכבת את הלבן,\u0004 שגם אם אין לו תכלת נותן חוטי לבן, \u0003ו\u0004כן \u0003הלבן\u0004 \u0003אינו מעכב את התכלת. תפלה של יד אינה מעכבת את של ראש,\u0004 ואם אין לו של יד מניח של ראש, \u0003ושל ראש אינה מעכבת את של יד.\u0004 ומציעים: \u0003לימא מתניתין\u0004 \u0005[האם נאמר שמשנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003רבי\u0004 היא, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר \u0003\"וראיתם אתו\"\u0004 (במדבר טו, לט) — \u0003מלמד ש\u0004התכלת והלבן \u0003מעכבין זה את זה,\u0004 אלו \u0003דברי רבי, וחכמים אומרים: אין מעכבין.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רבי?\u0004 כיצד הוא למד מכאן? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ונתנו על ציצית הכנף פתיל תכלת\", \"ציצית\" היא חוטי הלבן, וכמו שדרשו חכמים \"ציצית \u0003הכנף\"\u0004 — הציצית מ\u0003מין כנף,\u0004 כלומר, כצבע הבגד, שהוא לבן בדרך כלל, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \"ונתנו על ציצית הכנף \u0003פתיל תכלת\", ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 על שניהם יחד: \u0003\"וראיתם אותו\"\u0004 בלשון יחיד, ללמד שאינו יוצא ידי חובתו \u0003עד דאיכא תרוייהו בחד\u0004 \u0005[שישנם שניהם כאחד].\u0006","","","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים שאינם מעכבים זה את זה, מה הם אומרים? \u0003\"וראיתם אותו\"\u0004 — \u0003כל חד לחודיה\u0004 \u0005[אחד לעצמו]\u0006 \u0003משמע,\u0004 שמצוה בכל אחד ואחד מהם לעצמו.","ואם כן, האם \u0003לימא\u0004 \u0005[נאמר]\u0006 שמשנתנו האומרת שהתכלת אינה מעכבת את הלבן והלבן אינו מעכב את התכלת, היא ש\u0003לא כ\u0004שיטת \u0003רבי? אמר רב יהודה אמר רב: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003רבי, לא נצרכא\u0004 המשנה \u0003אלא\u0004 לענין \u0003לקדם,\u0004 לומר, שאף שצריך להקדים את הלבן לתכלת — אין זה מעכב.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מצוה להקדים לבן לתכלת, ואם הקדים תכלת ללבן\u0004 — \u0003יצא, אלא שחיסר מצוה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חיסר מצוה?\u0004"],["\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003חיסר\u0004 רק \u0003מצוה\u0004 של \u0003לבן, וקיים\u0004 רק \u0003מצוה\u0004 של \u0003תכלת,\u0004 כיצד יצא ידי חובתו? הלוא \u0003ל\u0004דעת \u0003רבי עכובי מעכב אהדדי\u0004 \u0005[מעכבים הם זה את זה]!\u0006","\u0003אמר רב יהודה אמר רב:\u0004 הכוונה היא \u0003שחיסר מצוה ו\u0004מכל מקום \u0003עשה מצוה, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003חיסר מצוה? דלא עבד\u0004 \u0005[שלא עשה]\u0006 \u0003מצוה מן המובחר,\u0004 שלא הקדים לבן לתכלת. ועשה מצוה — שקיים מצות ציצית, שהרי יש בה לבן ותכלת.","ושואלים: לפירוש זה למשנה, \u0003התינח\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 מה ששנינו ש\u0003לבן אינו מעכב את התכלת,\u0004 שגם אם לא הקדים את הלבן לתכלת — יצא, אלא מה ששנינו על \u0003תכלת\u0004 ש\u0003אינה מעכבת את הלבן מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 כיצד נפרש דבר זה? הלוא הלבן קודם לתכלת!","\u0003אמר רמי בר חמא: לא נצרכא אלא לטלית שכולה תכלת,\u0004 שבה צריך להקדים את התכלת ללבן.","ומעירים: ענין זה \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 באופן אחר, ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לוי לשמואל: אריוך\u0004 (אריה, מלך)! שכך כינה אותו על שם גדולתו! \u0003לא תיתיב אכרעך עד\u0004 \u0003דמפרשת לי להא מילתא\u0004 \u0005[אל תשב על רגליך עד שתפרש לי דבר זה]:\u0006 מה ששנינו, \u0003התכלת אינה מעכבת את הלבן, והלבן אינו מעכב את התכלת, מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 על מה נאמר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא נצרכא\u0004 משנה זו \u0003אלא ל\u0004ענין \u0003סדין בציצית,\u0004 ש\u0003מצוה לאקדומי\u0004 \u0005[להקדים]\u0006 את ה\u0003לבן ברישא\u0004 \u0005[בראש],\u0006","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שנאמר \u0003\"ציצית\u0004 \u0003הכנף\"\u0004 (במדבר טו, לח) לומר שהציצית צריכה להיות מ\u0003מין\u0004 ה\u0003כנף, ואי אקדים\u0004 \u0005[ואם הקדים]\u0006 \u0003תכלת ללבן לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש, כשרה היא.","ושואלים: \u0003תינח\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 לגבי מה ששנינו על ה\u0003לבן\u0004 ש\u0003אינו מעכב את התכלת,\u0004 אבל מה ששנינו על ה\u0003תכלת\u0004 ש\u0003אינה מעכבת את הלבן מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 כיצד יתפרש? והרי הלבן קודם לתכלת!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רמי בר חמא: לא נצרכא אלא לטלית שכולה תכלת,\u0004 שבמקרה \u0003זה\u0004 \u0003מצוה לאקדומי\u0004 \u0005[להקדים]\u0006 את ה\u0003תכלת ברישא\u0004 \u0005[בראש],\u0006 שהרי \u0003\"הכנף\"\u0004 — \u0003מין כנף, ו\u0004על כך נאמר ש\u0003אי אקדים לבן ברישא לית לן בה\u0004 \u0005[אם הקדים את הלבן בתחילה אין לנו בה],\u0006 כלומר, כשר הדבר.","\u0003אמר רבא: מידי ציבעא קא גרים\u0004 \u0005[כלום הצבע גורם],\u0006 שאם הטלית עשויה תכלת צריך להקדים ולתת תכלת לפני הלבן? \u0003אלא אמר רבא: לא נצרכא\u0004 משנתנו ששנינו בה שהתכלת אינה מעכבת את הלבן ולהיפך, \u0003אלא ל\u0004ענין \u0003גרדומין\u0004 (גדמים), שנחתכו חוטי הציצית לאחר שהטילם בבגד, \u0003דאי איגרדם\u0004 \u0005[שאם נגדם]\u0006 ה\u0003תכלת וקאי\u0004 \u0005[וקיים]\u0006 ה\u0003לבן, ואי איגרדם\u0004 \u0005[ו\u0006כן \u0005אם נגדם]\u0006 ה\u0003לבן וקאי\u0004 \u0005[וקיים]\u0006 ה\u0003תכלת\u0004 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה,\u0004 כפי","\u0003דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003בני ר' חייא: גרדומי תכלת כשרין,\u0004 שגם אם נחתכו חוטי הציצית (שכולה קרויה \"תכלת\" בלשון חכמים) — כשרה, \u0003ו\u0004כן \u0003גרדומי אזוב\u0004 שמשתמשים בו להזאה של מי פרה אדומה — \u0003כשרין.\u0004 ושואלים: \u0003וכמה שיעור\u0004 יישאר ב\u0003גרדומין\u0004 ותהיה הציצית כשרה? \u0003אמר בר המדורי אמר שמואל:\u0004 שיהיו ארוכים \u0003כדי לענבן,\u0004 לעשות בהם עניבה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: האם \u0003כדי לענבן,\u0004 פירושו \u0003לענבן כולהו בהדדי\u0004 \u0005[את כולם יחד],\u0006 \u0003או דלמא כל חד וחד לחודיה\u0004 \u0005[שמא כל אחד ואחד לחוד,\u0006 לעצמו\u0005],\u0006 שהוא שיעור קטן יותר? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: אלימי דלא מיענבי\u0004 \u0005[\u0006חוטים \u0005עבים שאי אפשר לעשות בהם עניבה]\u0006 \u0003ואי הוו קטיני מיענבי\u0004 \u0005[ואם היו דקים היו יכולים לעשות בהם עניבה],\u0006 \u0003מאי\u0004 \u0005[מהו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: כל שכן\u0004 שהם כשרים אם הם עבים וגדולים, \u0003דמינכר מצותייהו\u0004 \u0005[שניכרת מצוותם],\u0006 אף שאינם נענבים. ושבים לעיקר הדיון על דין המשנה.","ואומרים: \u0003ומאן תנא דפליג עליה\u0004 \u0005[ומיהו התנא שחולק עליו]\u0006 על \u0003רבי,\u0004 וסבור שהתכלת והלבן אינם מעכבים זה את זה? \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 \u0003הוא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יצחק אומר משום ר' נתן, שאמר משום ר' יוסי הגלילי שאמר משום ר' יוחנן בן נורי:\u0004 מי ש\u0003אין לו תכלת\u0004 — \u0003מטיל\u0004 רק \u0003לבן.\u0004","ובענין דברי בני ר' חייא שהובאו לעיל, \u0003אמר רבא, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003צריך לקשור\u0004 לעשות קשר \u0003על כל חוליא וחוליא\u0004 של גדיל הציצית, לאחר כל מספר כריכות, ואין להסתפק בקשר האחרון שאחריו מתחיל ה\"ענף\" של החוטים הפרודים, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 ש\u0003לא צריך,\u0004 ודי בקשר האחרון, \u0003הא דאמרי\u0004 \u0005[זה שאומרים]\u0006 \u0003בני ר' חייא: גרדומי תכלת כשרין וגרדומי אזוב כשרין,\u0004 הרי אם ייפסקו חוטי הציצית במקום הקשר, \u0003כיון דאישתרי ליה עילאי אישתרי ליה כולה\u0004 \u0005[כיון שהותר לו\u0006 הקשר \u0005העליון,\u0006 האחרון — \u0005תותר לו\u0006 הציצית \u0005כולה],\u0006 שלא יהיה לה גדיל."],["ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 אמרו בני ר' חייא שגרדומי תכלת כשרים במקרה \u0003דאיקטר\u0004 \u0005[שנעשה קשר]\u0006 בין חוליא לחוליא, אבל אין להוכיח מכאן שצריך לעשות קשר.","\u0003ו\u0004עוד \u0003אמר רבה: שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003קשר עליון\u0004 כלומר, הקשר הראשון בציצית הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003דאי סלקא דעתך דרבנן\u0004 \u0005[שאם עולה על דעתך\u0006 שהוא \u0005מדברי סופרים],\u0006 ומן התורה די שיכניס את הציציות בנקב שבבגד, \u0003מאי איצטריך למישרי\u0004 \u0005[מדוע הוצרך\u0006 הכתוב \u0005להתיר]\u0006 \u0003סדין\u0004 של פשתן \u0003בציצית\u0004 של צמר? \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שמותר, הלא \u0003התוכף תכיפה אחת\u0004 כלומר, המחבר שני דברים בחיבור אחד, כגון שמעביר חוט של צמר פעם אחת בבגד פשתים — \u0003אינו\u0004 נחשב ל\u0003חיבור,\u0004 ואם אין קשר בציצית, אלא רק תוחב אותה בבגד, אין זה שעטנז! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהקשר העליון \u0005הוא\u0006 \u0003דאורייתא\u0004 \u0005[מן התורה].\u0006","\u0003אמר רבה בר רב אדא אמר רב אדא אמר רב: אם נפסק החוט\u0004 אחד מחוטי הציצית \u0003מעיקרו\u0004 (מתחילתו), במקום החיבור לבגד, לפני הגדיל — \u0003פסולה\u0004 הציצית. \u0003יתיב\u0004 \u0005[יושב]\u0006 היה \u0003רב נחמן וקא אמר להא שמעתא\u0004 \u0005[ואומר את ההלכה הזו].\u0006 \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו בברייתא: \u0003במה דברים אמורים\u0004 שצריך שיעור לאורך הציציות — \u0003בתחילתו,\u0004 כשמטילים את הציצית בבגד, \u0003אבל\u0004 ב\u0003סופו\u0004 — \u0003שיריו וגרדומיו כל שהוא.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003שיריו ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003גרדומיו?\u0004 הרי גם גרדומים הם שיריים! \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003\"שיריו\"\u0004 — \u0003דאיפסיק מינייהו ואישתייר מינייהו\u0004 \u0005[שנחתך\u0006 חלק \u0005מהם\u0006 מן החוטים ו\u0005נשתייר\u0006 חלק \u0005מהם],\u0006 \u0003\"גרדומיו\"\u0004 — \u0003דאיגרדום איגרדומי\u0004 \u0005[שנכרתו\u0006 חוטי הציצית\u0005]\u0006 לגמרי, והוא כשר!","ומשיבים: \u0003לא, חדא קתני\u0004 \u0005[\u0006דבר \u0005אחד הוא שונה],\u0006 ולא שתי הלכות נפרדות, וכך יש להבין: \u0003שיורי גרדומיו כל שהוא.\u0004 ושואלים: אם כן, \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 רק: \u0003גרדומיו\u0004 כל שהוא, \u0003שיריו למה לי?\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[דבר זה משמיע לנו],\u0006 \u0003דבעינן שיורא\u0004 \u0005[שצריכים אנו שיור]\u0006 כל שהוא \u0003לגרדומיו,\u0004 והוא \u0003כדי\u0004 שיכול \u0003לענבן.\u0004","\u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רבה וקאמר משמיה\u0004 \u0005[ואמר משמו]\u0006 של \u0003רב: חוט של כרך,\u0004 החוט שכורכים בו את הציציות, \u0003עולה מן המנין\u0004 של שמונה החוטים שיש בציצית, ואינו צריך חוט נוסף לשם כך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: שמואל אמרה ולא רב. איתמר נמי\u0004 \u0005[נאמר גם כן]:\u0006 \u0003אמר רבה בר בר חנה, סח לי ר' יאשיה\u0004 ש\u0003מן אושא: חוט של כרך עולה לה מן המנין.\u0004","מסופר, \u0003יתיב\u0004 \u0005[יושב היה]\u0006 \u0003רבא וקא אמר משמיה\u0004 \u0005[ואומר משמו]\u0006 של \u0003שמואל: תכלת\u0004 כלומר, ציצית \u0003שכרך רובה\u0004 שעשה את רוב אורכה גדיל — \u0003כשרה,\u0004 אף שלכתחילה צריך שיהא רובה ענף. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: רב אמרה\u0004 להלכה זו \u0003ולא שמואל.\u0004 ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כדברי רב יוסף, \u0003אמר רב הונא בר יהודה אמר רב ששת אמר רב ירמיה בר אבא אמר רב: תכלת שכרך רובה\u0004 — \u0003כשרה.\u0004","\u0003רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן מתני הכי\u0004 \u0005[היה שונה\u0006 את הדברים \u0005כך],\u0006 \u0003אמר רב הונא אמר רב ששת אמר רב ירמיה בר אבא אמר רב: תכלת שכרך רובה\u0004 — \u0003כשרה, ואפילו לא כרך בה אלא חוליא אחת\u0004 — גם היא \u0003כשרה. ונויי תכלת,\u0004 אם רוצים לעשות את הציצית בצורה נאה — עושים שיהיה \u0003שליש גדיל ושני שלישי ענף\u0004 חוטים נפרדים.","\u0003וכמה שיעור חוליא? תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: כדי שיכרוך וישנה וישלש\u0004 — שלוש כריכות. \u0003תאנא\u0004 \u0005[שנה]\u0006 החכם: \u0003הפוחת\u0004 בחוליות \u0003לא יפחות משבע, והמוסיף לא יוסיף על שלש עשרה.\u0004","ומסבירים את הטעם: \u0003הפוחת לא יפחות משבע\u0004 — \u0003כנגד שבעה רקיעים, והמוסיף לא יוסיף על שלש עשרה\u0004 — \u0003כנגד שבעה רקיעין וששה אוירין\u0004 (חללים) \u0003שביניהם.\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003כשהוא מתחיל\u0004 לכרוך — \u0003מתחיל\u0004 לכרוך \u0003ב\u0004חוט \u0003לבן,\u0004 כדי לקיים \"ציצית \u0003הכנף\"\u0004 (במדבר טו, לה) — מ\u0003מין כנף, ו\u0004גם \u0003כשהוא מסיים\u0004 — \u0003מסיים בלבן,\u0004 משום \u0003מעלין בקודש ולא מורידין.\u0004","מסופר \u0003רב ורבה בר בר חנה הוו יתבי\u0004 \u0005[היו יושבים\u0006 יחד\u0005],\u0006 \u0003הוה קא חליף ואזיל ההוא גברא דמיכסי גלימא דכולה תכלתא\u0004 \u0005[היה חולף והולך\u0006 לפניהם \u0005אדם אחד שהיה לבוש בגלימה שכולה תכלת],\u0006 \u0003ורמי ליה תכלתא\u0004 \u0005[והיו מוטלות לו ציציות],\u0006"],["\u0003וגדילא מיגדיל\u0004 \u0005[ו\u0006כל הציצית \u0005היתה גדיל,\u0006 חוטים כרוכים יחד\u0005]\u0006 בלי \"ענף\" של חוטים פרודים היוצא ממנו. \u0003אמר רב: יאי גלימא ולא יאי תכלתא\u0004 \u0005[יפה הגלימה ולא יפה התכלת,\u0006 הציצית\u0005],\u0006 \u0003רבה בר בר חנא אמר: יאי גלימא ויאי תכלתא\u0004 \u0005[יפה הגלימה ויפה התכלת].\u0006","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 \u0003רבה בר בר חנה סבר\u0004 \u0005[סבור]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפרשה אחת \u0003\"גדיל\"\u0004 (\"גדילים תעשה לך\". דברים כב, יב) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפרשה אחרת \u0003\"פתיל\"\u0004 (\"ונתנו על ציצית הכנף פתיל תכלת\". במדבר טו, לח), לומר: יכול לעשות \u0003או\u0004 הכל \u0003גדיל, או\u0004 הכל \u0003פתיל\u0004 כל חוט נפרד לעצמו.","\u0003ורב סבר\u0004 \u0005[סבור]:\u0006 \u0003לעולם פתיל\u0004 גם כן \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 מלבד הגדיל, \u0003וההיא\u0004 \u0005[ואותו]\u0006 \u0003\"גדילים\"\u0004 שנאמר \u0003למניינא הוא דאתא\u0004 \u0005[למנין\u0006 הפתילים \u0005הוא שבא],\u0006 שאילו היה נאמר \u0003\"גדיל\"\u0004 — הרי אלה \u0003שנים,\u0004 כי גדיל משמעו חוטים שמחוברים לאחד, ומה שנאמר \u0003\"גדילים\"\u0004 כוונתו איפוא \u0003ארבעה,\u0004 ובא הכתוב לומר: \u0003עשה גדיל\u0004 מארבעה חוטים — \u0003ופותליהו מתוכו\u0004 שיהיו פתילים יוצאים ממנו.","\u0003אמר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003לוי: חוטי צמר פוטרין\u0004 כלומר, מקיימים בהם מצות ציצית, \u0003ב\u0004בגד \u0003של פשתן.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: חוטים \u0003של פשתן מהו שיפטרו ב\u0004בגד \u0003של צמר?\u0004 וצדדי השאלה: האם נאמר כי \u0003צמר בשל פשתים הוא דפטר\u0004 \u0005[שפוטר],\u0006 ש\u0003כיון\u0004 שה\u0003תכלת פטרה\u0004 \u0005[פוטרת]\u0006 בגד פשתים, שפתיל התכלת הוא לעולם עשוי צמר — צמר \u0003לבן נמי פטר\u0004 \u0005[גם כן פוטר]\u0006 בגד פשתים, \u0003אבל\u0004 חוט \u0003פשתים בצמר לא\u0004 יפטור.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תלבש שעטנז צמר ופשתים יחדו. גדלים תעשה לך\"\u0004 (דברים כב, יא— יב) להתיר שעטנז בציצית, אם כן \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003צמר בפשתים ולא שנא\u0004 \u0005[לא שונה]\u0006 \u0003פשתים בצמר?\u0004","ומציעים, \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 תשובה לדבר ממה ש\u0003אמר רחבה אמר רב יהודה\u0004 בפירוש: \u0003חוטי צמר פוטרין בשל פשתן ושל פשתן פוטרין בשל צמר.\u0004 אגב כך מביאים את המשך דבריו: \u0003חוטי צמר ופשתים פוטרין בכל מקום\u0004 כלומר, בכל מין של בגד, \u0003ואפילו בשיראין\u0004 (של משי).","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוק]\u0006 הדבר על דברי \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן: השיראין פטורין מן הציצית\u0004 בכלל. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו בברייתא: \u0003השיראין, והכלך, והסריקין\u0004 שכולם מיני משי — \u0003כולן חייבין בציצית!\u0004 אמר לו: חייבים הם רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 ולא מדין תורה.","הקשה לו: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של אותה ברייתא: \u0003וכולן,\u0004 השיראין והכלך וסריקין — \u0003צמר ופשתים\u0004 יחדיו \u0003פוטרין בהן,\u0004 צמר לתכלת, ופשתן לחוטי הלבן. ומעתה, \u0003אי אמרת בשלמא דאורייתא\u0004 \u0005[נניח אם אומר אתה\u0006 שחיובם הוא \u0005מן התורה]\u0006 — \u0003היינו דמישתרו בהו\u0004 \u0005[זהו\u0006 הטעם שמותרים בהם] \u0003כלאים,\u0004 שנותן בהם יחד צמר לתכלת ופשתים ללבן, \u0003אלא אי אמרת דרבנן\u0004 \u0005[אם אומר אתה\u0006 שחיובם הוא \u0005מדברי סופרים],\u0006 \u0003היכי מישתרי בהו\u0004 \u0005[איך מותרים בהם]\u0006 \u0003כלאים?\u0004 ומשיבים, \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003או\u0004 חוטי \u0003צמר או\u0004 חוטי \u0003פשתים\u0004 נותנים בהם, ולא שניהם יחד.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 \u0003דקתני סיפא\u0004 \u0005[\u0006ממה \u0005שהוא שונה בסוף]:\u0006 \u0003הן,\u0004 המינים הללו של משי \u0003—\u0004 \u0003במינן פוטרין\u0004 אפשר לעשות מהם ציציות ממין אותו בגד, אבל \u0003שלא במינן\u0004 לבגדים ממין אחר — \u0003אין פוטרין.\u0004 ומעתה, \u0003אי אמרת בשלמא דרבנן\u0004 \u0005[נניח אם אומר אתה\u0006 שחיובם בציצית הוא \u0005מדברי סופרים]\u0006 — \u0003היינו דמיפטרו\u0004 \u0005[זהו הטעם שהם נפטרים]\u0006 \u0003ב\u0004ציציות שמ \u0003מינן, אלא אי אמרת דאורייתא\u0004 \u0005[אם אומר אתה\u0006 שחיובם \u0005מן התורה],\u0006 הרי מן התורה רק \u0003צמר ופשתים הוא דפטר\u0004 \u0005[שפוטר],\u0006 ולא מינים אחרים!","ודוחים: \u0003אי משום הא לא איריא\u0004 \u0005[אם משום זה אין להוכיח],\u0006 שיש לומר שמן התורה שאר מינים פוטרים במינם, \u0003כ\u0004דברי \u0003רבא.\u0004 ש\u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \"ציצית \u0003הכנף\"\u0004 (במדבר טו, לא) לומר שתהא מ\u0003מין\u0004 ה\u0003כנף,\u0004 ומשמע — מכל מין של אריג. \u0003וכתיב\u0004 \u0005[ו\u0006מצד אחר \u0005נאמר]:\u0006 \u0003\"צמר ופשתים...\u0004 גדילים תעשה לך\" (דברים כב, יא— יב), ומשמע שעושים גדילים רק מצמר ופשתים!","\u0003הא\u0004 \u0003כיצד?\u0004 חוטי \u0003צמר ופשתים\u0004 — \u0003פוטרין בין במינן בין שלא במינן, שאר מינין\u0004 — \u0003במינן\u0004 הם \u0003פוטרין, שלא במינן אין פוטרין.\u0004","ומעירים: \u0003ורב נחמן,\u0004 הסבור שבגד משי פטור מן התורה מן הציצית, מהיכן הוא למד? \u0003כדתנא דבי\u0004 \u0005[כמו התנא מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004","\u0003דתנא דבי\u0004 \u0005[ששנה\u0006 התנא \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: הואיל ונאמרו בגדים בתורה\u0004 כמה פעמים ב\u0003סתם,\u0004 כגון במצות ציצית \"על כנפי בגדיהם\" (במדבר טו, לח), \u0003ופרט לך הכתוב באחד מהן\u0004 שהכוונה ל\u0003צמר ופשתים,\u0004 שנאמר בצרעת הבגד: \"בבגד צמר או בבגד פשתים\" (ויקרא יד, מז), יש ללמוד ש\u0003אף כל\u0004 בגדים האמורים בתורה הם \u0003צמר ופשתים,\u0004 וכל העשוי מאריג אחר אינו קרוי \"בגד\" מן התורה.","\u0003אמר אביי: והאי תנא דבי\u0004 \u0005[ותנא זה מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל מפקא מאידך תנא דבי\u0004 \u0005[מוציא מ\u0006דבריו של \u0005תנא אחר של בית]\u0006 \u0003ר' ישמעאל,\u0004 הסבור שכל מיני האריגים בכלל \"בגד\". \u0003דתנא דבי\u0004 \u0005[ששנה בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"בגד\"\u0004 (שם), \u0003אין לי אלא בגד צמר, מנין לרבות צמר גמלים וצמר ארנבים ונוצה\u0004 כלומר, צמר \u0003של עזים, ו\u0004כן \u0003הכלך והסריקין והשיראין,\u0004 שהם מיני משי, \u0003מנין\u0004 שגם בהם נוהג דין זה? \u0003תלמוד לומר: \"או בגד\",\u0004 לרבות, שגם אלה בכלל."],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003סדין\u0004 של פשתן \u0003בציצית\u0004 — \u0003בית שמאי פוטרין\u0004 אותו מן הציצית, ואף אסור הדבר משום כלאיים, שהתכלת עשויה צמר, \u0003ובית הלל מחייבין, והלכה כדברי בית הלל.\u0004","\u0003אמר ר' אליעזר בן ר' צדוק:\u0004 כיצד אומרים כן בית הלל? \u0003והלא כל המטיל תכלת\u0004 בסדינו \u0003בירושלים אינו\u0004 נחשב \u0003אלא מן המתמיהין!\u0004","\u0003אמר רבי: אם כן,\u0004 שסדין פשתן חייב מן התורה בציצית, וכדברי בית הלל, \u0003למה אסרוה\u0004 את הציצית בסדין? והוא מסביר: \u0003לפי שאין\u0004 אנשים \u0003בקיאין\u0004 בפרטי ההלכה, ויבואו להתיר כלאיים גם שלא במקום מצות ציצית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנא לרבא: ולרמו בי עשרה ונפקו לשוקא ומפרסמא למילתא\u0004 \u0005[ושיטילו עשרה\u0006 אנשים ציציות בסדיניהם \u0005ויצאו לשוק וכך נפרסם את הדבר]!\u0006 השיב לו: אם יעשו כן — \u0003כל שכן דמתמהו עילון\u0004 \u0005[שיתמהו עלינו],\u0006 כיצד נוהגים אנשים אלו בניגוד למקובל.","ושואלים: \u0003ולידרשא בפירקא\u0004 \u0005[ושידרשו\u0006 את \u0005ההלכה הזו\u0006 \u0005בציבור]\u0006 שכך צריך לעשות! ומשיבים: \u0003גזירה משום קלא אילן,\u0004 שהוא צבע הדומה מאד לצבע המופק מחלזון התכלת (להלן מנחות מד,א), אבל אין יוצאים בו ידי מצות תכלת בציצית. ושמא יטעו ויעשו ממנו חוטי תכלת ויטילו בסדין, ויעברו על איסור כלאיים.","ומקשים: ומה בכך? \u0003ולא יהא\u0004 החוט הזה הצבוע בקלא אילן \u0003אלא\u0004 כמו חוט צמר \u0003לבן,\u0004 הרי מטילים חוטי לבן של צמר בסדין של פשתן! ומשיבים: \u0003כיון\u0004 ש\u0003אפשר במינן\u0004 בציציות של פשתן — \u0003לא,\u0004 אין עושים בציציות של צמר שאינן תכלת.","\u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש: כל מקום שאתה מוצא\u0004 מצות \u0003עשה ו\u0004מצות \u0003לא תעשה,\u0004 וכגון מצות ציצית ואיסור כלאיים, \u0003אם אתה יכול לקיים את שניהם\u0004 וכגון להטיל ציציות של פשתן בסדין של פשתן, ולא לעבור על איסור כלאיים — \u0003מוטב, ו\u0004רק \u0003אם לאו\u0004 — \u0003יבוא עשה וידחה את לא תעשה.\u0004 ומקשים: ומדוע לגזור משום קלא אילן?","\u0003וליבדקוה\u0004 \u0005[ושיבדקו]\u0006 את הציצית אם היא צבועה תכלת או קלא אילן, כמבואר להלן (מנחות מב,ב), שניתן לעמוד על הדבר! \u0003אלא\u0004 טעם הדבר שאוסרים להטיל תכלת בסדין אינו משום קלא אילן, אלא הוא \u0003גזירה משום טעימה\u0004 (נסיון), שמא צבעו את חוטי הצמר בצבע תכלת שהשתמשו בו לצורך בדיקה, והוא פסול, ונמצא שעוברים על איסור כלאיים שלא במקום מצוה.","ושואלים: \u0003וליכתבה אדיסקי\u0004 \u0005ושיכתבו את\u0006 הדבר \u0005באיגרות],\u0006 ויודיעו בכל מקום שתכלת ששימשה לטעימה פסולה! ומשיבים: \u0003אדיסקי ליקום וליסמוך\u0004 \u0005[\u0006וכי \u0005על איגרות נבוא ונסמוך]\u0006 שאנשים אכן נוהגים על פיהן? על תשובה זו \u0003אמר רבא\u0004 בתמיהה: \u0003השתא\u0004 \u0005[עכשיו, הרי]\u0006"],["\u0003חמץ בפסח ויום הכפורים,\u0004 שיש בשניהם איסור \u0003כרת\u0004 — \u0003סמכינן אדיסקי\u0004 \u0005[סומכים אנו על האגרות],\u0006 ששולחים מארץ ישראל ומודיעים שנתעברה השנה או החודש, \u0003הכא\u0004 \u0005[כאן]\u0006 בתכלת, שהוא רק \u0003עשה בעלמא\u0004 \u0005[בלבד],\u0006 \u0003לא כל שכן\u0004 שאפשר לסמוך על כך?!","\u0003אלא אמר רבא: הא מילתא אמרי\u0004 \u0005[דבר זה אמרתי],\u0006 \u0003ואיתמר במערבא משום\u0004 \u0005[ונאמר בארץ ישראל בשמו]\u0006 של \u0003ר' זירא כוותי\u0004 \u0005[כמותי]:\u0006 טעם הדבר שאסרו סדין בציצית הוא \u0003שמא\u0004 מתחילה \u0003יקרע סדינו בתוך שלש\u0004 אצבעות לקצה הכנף, שהוא מקום הציצית, \u0003ויתפרנו\u0004 בחוטי פשתן, ופעמים משתייר מחוט התפירה בבגד, ויעשנו ציצית, ובכגון זה הוא פסול, מפני ש","\u0003התורה אמרה\u0004 \"גדילים תעשה לך על ארבע כנפות כסותך\" (דברים כב, יב), \u0003תעשה\u0004 על הבגד — \u0003ולא מן העשוי\u0004 כבר בבגד, וכשמטיל שם חוטי תכלת נמצא עובר על איסור כלאיים שלא במקום מצוה.","ומחשש זה \u0003שרא\u0004 \u0005[התיר]\u0006 \u0003ר' זירא לסדיניה\u0004 \u0005[את סדינו]\u0006 כלומר, התיר את הציציות מסדינו שהיה עשוי פשתן. \u0003רב זירא אמר:\u0004 הטעם לאסור סדין פשתן בציצית הוא \u0003גזירה נמי\u0004 \u0005[גם כן]\u0006 \u0003משום כסות לילה,\u0004 שפעמים מתכסה בסדין זה בלילה, שאינו זמן ציצית, ונמצא שעובר על איסור כלאיים.","\u0003ו\u0004עוד \u0003אמר רבא: הא מילתא אמרי\u0004 \u0005[דבר זה אמרתי],\u0006 \u0003ואיתמר במערבא משמיה\u0004 \u0005[ונאמר בארץ ישראל משמו]\u0006 של \u0003ר' זירא כוותי\u0004 \u0005[כמותי]:\u0006 היתה \u0003היא\u0004 הטלית \u0003של בגד, וכנפיה\u0004 כנפות הטלית \u0003של עור\u0004 — הרי היא \u0003חייבת\u0004 בציצית. היתה \u0003היא של עור וכנפיה של בגד\u0004 — \u0003פטורה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003עיקר בגד בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה בר חיוב, ובגד מעור אינו חייב בציצית.","ומעירים: \u0003רב אחאי אזיל בתר\u0004 \u0005[\u0006היה \u0005הולך אחר]\u0006 \u0003כנף,\u0004 שנאמר \"על כנפי בגדיהם\" (במדבר טו, לח), ולפי זה היה קובע אם הבגד חייב בציצית או לא.","\u0003אמר רבא אמר רב סחורה אמר רב הונא: הטיל\u0004 שלוש ציציות \u0003ל\u0004טלית \u0003בעלת שלש\u0004 קרנות, \u0003והשלימה\u0004 את הטלית אחר כך \u0003לארבע\u0004 כנפות, על ידי גזירה או תפירה, והטיל ציצית בכנף הנוספת — הרי זו \u0003פסולה\u0004 משום \u0003\"תעשה ולא מן העשוי\",\u0004 שמתחילה הטיל את הציציות בבגד שאינו חייב בציצית, וכשנתחייב כבר היו עשויות בו.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003חסידים הראשונים, כיון שארגו בה\u0004 בטלית \u0003שלש\u0004 אצבעות בלבד, כבר \u0003היו מטילין לה תכלת\u0004 לאותן שתי קרנות, למרות שעדיין לא נתחייבו בציצית, שהרי לא היה בבגד שיעור! ומשיבים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003כיון שפצעו בה שלש\u0004 כלומר, כיון שהגיעו עד לשלוש האצבעות האחרונות של הבגד, שהוא מקום הטלת הציציות, \u0003היו מטילין לה תכלת\u0004 בשתי הקרנות הראשונות.","ושואלים: \u0003ומי אמרינן\u0004 \u0005[והאם אומרים אנו]\u0006 \u0003\"תעשה ולא מן העשוי\"\u0004 כשהטיל ציצית בבגד בשעה שלא היה צריך לציצית? \u0003(איני) והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זירא:\u0004 אם \u0003הטיל\u0004 ציציות \u0003ל\u0004טלית \u0003מוטלת\u0004 (שיש בה כבר ארבע ציציות) וחתך את הראשונות — \u0003כשרה,\u0004 למרות שכשהטיל את האחרונות לא היה צורך בהן!","\u0003אמר רבא:\u0004 אין להקשות מכאן, שכן \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ב\u0004איסור \u0003\"בל תוסיף\" קאי\u0004 \u0005[עומד הוא]\u0006 כשהוסיף את הציציות לטלית המוטלת, וכי \u0003מעשה לא הוי\u0004 \u0005[אינו נחשב]?\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא\u0004 על עצם הקשר בין הדברים: \u0003ממאי דגברא לאוסופי קא מיכוין\u0004 \u0005[מנין\u0006 יודעים אנו \u0005שהאיש להוסיף\u0006 ציציות לציציות הישנות \u0005הוא מתכוון]?\u0006 \u0003דלמא לבטולי קא מיכוין\u0004 \u0005[שמא לבטל\u0006 את הציציות הישנות \u0005הוא מתכוון],\u0006 \u0003ו\u0004אם כן למרות ש\u0003\"בל תוסיף\" ליכא\u0004 \u0005[אין כאן],\u0006 מכל מקום \u0003מעשה איכא\u0004 \u0005[יש כאן]!\u0006","ועוד בענין הטיל למוטלת, מביאים מה ש\u0003אמר ר' זירא אמר רב מתנא אמר שמואל: תכלת\u0004 (ציצית) \u0003אין בה משום כלאים\u0004 (שעטנז), \u0003ואפילו\u0004 אם הטילה \u0003בטלית\u0004 שהיא \u0003פטורה\u0004 מציצית.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003טלית פטורה? אילימא דלית בה שיעורא\u0004 \u0005[אם תאמר שאין בה שיעור]\u0006 בטלית? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003טלית,\u0004 שהיא גדולה כך \u0003שהקטן מתכסה בו ראשו ורובו,\u0004"],["\u0003והגדול,\u0004 אדם מבוגר, \u0003יוצא בה דרך עראי\u0004 לשוק, ואינו מתבייש בבגד קטן כל כך — הרי היא \u0003חייבת בציצית,\u0004 אבל טלית ש\u0003אין הקטן מתכסה בו ראשו ורובו, אף על פי שהגדול יוצא בה עראי\u0004 — \u0003פטורה\u0004 מציצית, ומוסיפים: \u0003וכן לענין כלאים.\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003וכן לענין כלאים? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003וכן לענין איסורא\u0004 \u0005[איסור]\u0006 של \u0003כלאים,\u0004 שאם אין הקטן מתכסה בה ראשו ורובו, אף על פי שגדול יוצא בה עראי אין חייבים עליה משום כלאיים — \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]:\u0006 \u0003אין עראי בכלאים! ו\u0004בתשובה לכך","\u0003אמר רב נחמן בר יצחק:\u0004 מהו \"וכן לענין כלאים\" — \u0003וכן לענין סדין\u0004 פשתן \u0003בציצית,\u0004 שאם הקטן מתכסה בו ראשו ורובו — מותר להטיל בו ציצית, ואין בכך משום איסור כלאים. אבל אם אין הקטן מתכסה בו ראשו ורובו והוא פטור — אסור להטיל בו ציצית, משום כלאיים. ואם כן, לא ניתן לפרש את דברי שמואל, שטלית פטורה אין בה משום כלאיים בטלית שאין בה שיעור!","\u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 טלית \u0003פטורה\u0004 אין בה משום כלאיים — ש\u0003הטיל\u0004 תכלת \u0003למוטלת,\u0004 לטלית שכבר יש בה ציציות, לומר שלמרות שאין צורך בציציות אלו — אין בכך משום איסור כלאיים, אם היתה הטלית (או חוטי הלבן) עשויה פשתן.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 כבר \u0003אמרה ר' זירא חדא זימנא\u0004 \u0005[פעם אחת],\u0006 שאם הטיל למוטלת — כשרה! ומשיבים: שתי ההלכות הללו לא נאמרו לחוד, אלא \u0003חדא מכלל דחבירתה איתמר\u0004 \u0005[אחת מכלל חבירתה נאמרה]\u0006 כלומר, ר' זירא אמר הלכה אחת, ומכאן הסיקו בשמו את האחרת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003טלית כפולה,\u0004 וכגון שהיתה ארוכה במיוחד וקיפלוה לשתים, \u0003חייבת בציצית\u0004 במקום הכפל, \u0003ור' שמעון פוטר,\u0004 שאין זו כנף הבגד. \u0003ושוין\u0004 החכמים ור' שמעון, \u0003שאם כפלה ותפרה\u0004 — \u0003שחייבת.\u0004","ותוהים: \u0003תפרה, פשיטא\u0004 \u0005[פשוט]\u0006 שחייבת! ומשיבים: \u0003לא צריכא דנקטה בסיכי\u0004 \u0005[לא\u0006 \u0003נצרכה\u0004 אלא במקרה \u0003שחיבר אותה בסיכות]\u0004 ולא בתפירה ממש, שבכל זאת היא נחשבת כתפורה לענין זה.","מסופר, \u0003רבה בר הונא איקלע לבי\u0004 \u0005[נזדמן לביתו]\u0006 של \u0003רבא בר רב נחמן, חזייה דהוה מיכסי\u0004 \u0005[ראה אותו שהיה מכוסה]\u0006 ב\u0003טלית כפולה ורמי ליה חוטי עילוי כפילא\u0004 \u0005[והיו מוטלות ציציות על מקום הכפל],\u0006 \u0003איפשיטא\u0004 \u0005[נפתחה]\u0006 הטלית \u0003ואתא חוטא וקם להדי רישיה\u0004 \u0005[ו\u0006כך \u0005בא החוט,\u0006 מקום הציציות, \u0005ועמד כנגד ראשו],\u0006 שהטלית היתה מונחת חציה לפניו וחציה לאחוריו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר הונא: \u0003לאו היינו\u0004 \u0005[אין זו]\u0006 \u0003כנף דכתב רחמנא באורייתא\u0004 \u0005[שכתב הקב\"ה בתורה]!\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 רבא בר רב נחמן \u0003שדייה איכסי גלימא אחריתי\u0004 \u0005[השליך אותה והתכסה בגלימה אחרת].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר הונא: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שהציצית \u0003חובת גברא\u0004 \u0005[האדם]\u0006 \u0003הוא?\u0004 לא, \u0003חובת\u0004 ה\u0003טלית הוא,\u0004 שמצוה לתת ציצית על כל בגד שיש לו לאדם, \u0003זיל רמי לה\u0004 \u0005[לך והטל בה]\u0006 ציציות כראוי.","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[האם נאמר\u0006 שאפשר \u0005לסייע לו]\u0006 ממה ששנינו: \u0003חסידים הראשונים, כיון שארגו בה שלש\u0004 אצבעות בלבד כבר \u0003היו מטילין בה תכלת,\u0004 עוד לפני שהיתה ראויה ללבישה, ומכאן שהיא חובת הבגד! ודוחים: מכאן אין ראיה, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003חסידים, דמחמרי אנפשייהו\u0004 \u0005[שמחמירים על עצמם],\u0006 אבל אין להוכיח מכאן על חובת הכלל.","ומעירים: \u0003ופליגא דמלאכא\u0004 \u0005[וחלוק\u0006 הדבר הזה על מה שאמר \u0005המלאך],\u0006 \u0003דמלאכא אשכחיה\u0004 \u0005[שהמלאך מצא]\u0006 את \u0003רב קטינא דמיכסי סדינא\u0004 \u0005[שהוא מכוסה בסדין\u0006 פשתן\u0005]\u0006 שפטור מציצית, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קטינא, קטינא!\u0004 אם תלבש \u0003סדינא בקייטא\u0004 \u0005[סדין בקיץ]\u0006 \u0003וסרבלא בסיתוא\u0004 \u0005[\u0006\u0003וסרבל בחורף],\u0004 מעין מעיל כמו שלנו, שיש לו רק שתי כנפיים, והוא פטור מציצית, \u0003ציצית של תכלת מה תהא עליה?\u0004 הרי בסוף נמצא שאינך לבוש בציצית כלל!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב קטינא: \u0003ענשיתו\u0004 \u0005[\u0006וכי \u0005עונשים אתם]\u0006 גם על ביטול מצות \u0003עשה? אמר ליה\u0004 \u0005[לו]\u0006 המלאך: \u0003בזמן דאיכא ריתחא ענשינן\u0004 \u0005[בזמן שיש כעס\u0006 ומידת הדין מתוחה \u0005עונשים אנו]\u0006 גם על דבר כזה.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שציצית \u0003חובת גברא\u0004 \u0005[האדם]\u0006 \u0003הוא\u0004 — \u0003היינו דמחייב דלא קא רמי\u0004 \u0005[משום כך הוא שמתחייב\u0006 בזמן ריתחה על \u0005שאינו מטיל\u0006 ציצית בבגדו\u0005],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003חובת טלית הוא\u0004 — במקרה של סדין \u0003הא לא מיחייבא\u0004 \u0005[הרי אינה מחוייבת]!\u0006","ומשיבים: \u0003אלא מאי\u0004 \u0005[מה]\u0006 אתה \u0005אומר, ש\u0006\u0003חובת גברא\u0004 \u0005[האדם]\u0006 \u0003הוא? נהי דחייביה רחמנא כי מיכסי\u0004 \u0005[גם אם אמנם חייבה אותו התורה\u0006 להטיל ציצית \u0005כאשר הוא מכוסה]\u0006 ב\u0003טלית\u0004 שהיא \u0003בת חיובא\u0004 \u0005[חיוב],\u0006 \u0003כי מיכסי טלית דלאו בת חיובא היא\u0004 \u0005[כאשר הוא מכוסה בטלית שאינה בת חיוב],\u0006 \u0003מי חייביה רחמנא\u0004 \u0005[האם חייבה אותו התורה]?\u0006","\u0003אלא הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 המלאך: \u0003טצדקי למיפטר נפשך\u0004 \u0005[תחבולות\u0006 מוצא אתה \u0005לפטור את עצמך]\u0006 \u0003מ\u0004ה\u0003ציצית?\u0004","\u0003אמר רב טובי בר קיסנא אמר שמואל: כלי קופסא,\u0004 בגדים שאינו לבוש בהם, אלא הם מונחים בקופסה לשימוש לשעת הצורך — \u0003חייבין בציצית,\u0004 מפני שהיא חובת הבגד. \u0003ומודה שמואל בזקן שעשאה לכבודו\u0004 כלומר, בטלית שהכין לו \u0003לתכריכים,\u0004 \u0003ש\u0004היא \u0003פטורה\u0004 מן הציצית, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \"על ארבע כנפות כסותך \u0003אשר תכסה בה\"\u0004 (דברים כב, יב) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003האי לאו לאיכסויי עבידא\u0004 \u0005[\u0006ו\u0005זו איננה עשויה להתכסות בה].\u0006","ומעירים: \u0003בההיא שעתא\u0004 \u0005[באותה שעה]\u0006 שקוברים אותו \u0003ודאי רמינן ליה\u0004 \u0005[מטילים בו]\u0006 ציציות בתכריכים, \u0003משום \"לעג לרש חרף עשהו\"\u0004 (משלי יז, ה), שאם לא נעשה כן ייראה הדבר כלעג למת, כאילו אומרים לו: עכשיו פטור אתה מן המצוות.","\u0003אמר רחבה אמר ר' יהודה: טלית שנקרעה\u0004 באחת מכנפיה, אם היה הקרע \u0003חוץ לשלש\u0004 אצבעות מקצה הבגד \u0003—\u0004 יחזור ו\u0003יתפור\u0004 ואין בכך חשש. אבל אם נקרעה ב\u0003תוך שלש\u0004 אצבעות — \u0003לא יתפור,\u0004 שיש לחשוש שמא ישתמש בחוטי התפירה לציצית, ויש בכך משום \"תעשה ולא מן העשוי\".","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003טלית שנקרעה, חוץ לשלש\u0004 — \u0003יתפור,\u0004 לדעת הכל. נקרעה \u0003תוך שלש\u0004 — \u0003ר' מאיר אומר: לא יתפור, וחכמים אומרים: יתפור.\u0004","\u0003ושוין\u0004 ר' מאיר וחכמים, \u0003שלא יביא אפילו\u0004 \u0003אמה על אמה\u0004 של בגד \u0003ממקום אחר ובה תכלת\u0004 (ציצית), \u0003ותולה בה\u0004 בטלית קיימת, שהרי צריך להטיל את הציצית על כנף הבגד. אבל \u0003שוין, שמביא תכלת ממקום אחר\u0004 כלומר, שמתיר ציצית מטלית \u0003אחרת\u0004 \u0003ותולה בה\u0004 בטלית זו,"],["\u0003ובלבד שלא תהא מופסקת\u0004 כלומר, שיהיו החוטים שלמים. ושואלים: \u0003שמעת מינה\u0004 \u0005[האם שומע אתה מכאן]\u0006 מברייתא זו ש\u0003מתירין\u0004 ציצית \u0003מבגד לבגד,\u0004 ושלא כדברי רב להלן? ודוחים: מכאן אין ראיה, \u0003דילמא דאי בלאי\u0004 \u0005[שמא\u0006 נאמר בברייתא \u0005שאם בלתה]\u0006 טלית — אפשר להתיר ממנה את הציציות ולתת בטלית אחרת, אבל אין מכאן ראיה שמותר לעשות כן לכתחילה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003טלית שכולה תכלת\u0004 — \u0003כל מיני צבעונין פוטרין בה\u0004 בתור חוטי לבן שבציצית, יחד עם חוטי התכלת, \u0003חוץ מקלא אילן,\u0004 חומר צביעה שצבעו כצבע התכלת, שאם נתנו יחד עם חוטי התכלת — אין הציצית כשרה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו: \u0003טלית אין פוטר בה\u0004 משום לבן \u0003אלא מינה. טלית שכולה תכלת\u0004 — \u0003מביא תכלת ודבר אחר ותולה בה; וקלא אילן לא יביא\u0004 לכתחילה עם התכלת, \u0003ואם הביא\u0004 ותלה בה — \u0003כשר!\u0004","\u0003אמר רב נחמן בר יצחק, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 שכשר — מדובר \u0003בטלית\u0004 שנתן בה ציצית \u0003בת ארבעה חוטין\u0004 בלבד, שנים של תכלת ושנים של קלא אילן. \u0003כאן\u0004 שפסול — מדובר \u0003בטלית\u0004 שנתן בה ציצית \u0003בת שמונה חוטין,\u0004 ארבעה חוטים של תכלת וארבעה של קלא אילן. וחכמים פסלוה, שמא ישתמשו בחוטי הקלא אילן לצורך טלית אחרת, מתוך הנחה שהם חוטי תכלת.","ושואלים: \u0003שמעת מינה\u0004 \u0005[האם שומע אתה מכאן]\u0006 ש\u0003מתירין\u0004 ציציות \u0003מבגד לבגד?\u0004 שהרי אנו חוששים שמא יקח מטלית זו ויתן בטלית אחרת! ודוחים: מכאן אין ראיה שעושים כן לכתחילה, \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר בחשש למקרה \u0003דאי עבד\u0004 \u0005[שאם\u0006 עבר ו\u0005עשה],\u0006 והעביר חוטי ציצית מבגד לבגד.","אגב כך מביאים, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר, \u0003רב אמר: אין מתירין\u0004 ציצית \u0003מבגד לבגד, ושמואל אמר: מתירין מבגד לבגד.\u0004 ומביאים עוד דברים שנחלקו בהם.","\u0003רב אמר: אין מדליקין\u0004 בנרות חנוכה \u0003מנר לנר, ושמואל אמר: מדליקין מנר לנר.\u0004","\u0003רב אמר: אין הלכה כר' שמעון בגרירה,\u0004 שמתיר לגרור כלי כבד בשבת למרות שהוא עושה חריץ ברצפה (ויש בדבר משום תולדת חורש או בונה), מפני שאינו מתכוון. \u0003ושמואל אמר: הלכה כר' שמעון בגרירה.\u0004","ובענין זה \u0003אמר אביי: כל מילי דמר\u0004 \u0005[כל הדברים של אדוני,\u0006 רבה\u0005]\u0006 \u0003עביד\u0004 \u0005[\u0006היה \u0005עושה\u0006 ונוהג\u0005]\u0006 \u0003כרב, לבר מהני תלת דעביד\u0004 \u0005[חוץ משלושה אלה שהיה עושה]\u0006 \u0003כשמואל: מתירין מבגד לבגד, ומדליקין מנר לנר, והלכה כר' שמעון בגרירה.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: גורר אדם מטה, כסא וספסל, ובלבד שלא יתכוין\u0004 לכתחילה \u0003לעשות חריץ.\u0004","מסופר כי \u0003רב יהודה מסר ליה לקצרא\u0004 \u0005[היה מוסר\u0006 את \u0005בגדו ובו הציצית\u0006 \u0005לכובס],\u0006 ולא היה חושש שיתיר אותה. \u0003רב חנינא עביד לה סיסא\u0004 \u0005[היה עושה\u0006 את הציצית כמעין \u0005פקעת],\u0006 כדי שלא יתירו אותה. \u0003רבינא חייט להו מיחט\u0004 \u0005[היה תופר אותם]\u0006 את שולי הבגד, כדי לטמון את הציצית בתוכם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כמה חוטין הוא נותן\u0004 בציצית? \u0003בית שמאי אומרים: ארבעה,\u0004 וכופל אותם, \u0003ובית הלל אומרים: שלשה\u0004 וכופלם.","\u0003וכמה תהא\u0004 הציצית \u0003משולשת\u0004 (משולשלת), תלויה? מה אורכה? \u0003בית שמאי אומרים: ארבע\u0004 אצבעות, \u0003ובית הלל אומרים: שלש. ושלש\u0004 אצבעות \u0003שבית הלל אומרים,\u0004 שיעור האצבע \u0003אחת מארבע בטפח של כל אדם.\u0004 ובענין זה מביאים כלל ש\u0003אמר רב פפא: טפח דאורייתא\u0004 \u0005[של התורה]\u0006 הוא שיעור \u0003ארבע\u0004 אצבעות אם מודדים \u0003בגודל, שית\u0004 \u0005[שש]\u0006 אצבעות אם מודדים \u0003ב\u0004אצבע ה\u0003קטנה, חמש בתילתא\u0004 \u0005[באצבע השלישית,\u0006 האמה\u0005].\u0006","ובפסק ההלכה בענין זה, \u0003אמר רב הונא:\u0004 יש לתת \u0003ארבעה\u0004 חוטים (כפולים) \u0003בתוך ארבע\u0004 אצבעות משפת הבגד, \u0003ומשולשת\u0004 באורך \u0003ארבע\u0004 אצבעות, \u0003ורב יהודה אמר: שלשה\u0004 חוטים כפולים \u0003בתוך שלש\u0004 אצבעות, \u0003משולשת שלש.\u0004","\u0003אמר רב פפא, הלכתא\u0004 \u0005[הלכה היא]:\u0006 \u0003ארבעה\u0004 חוטים, \u0003בתוך שלש\u0004 אצבעות משפת הבגד, \u0003משולשת ארבע\u0004 אצבעות.","ומעירים: \u0003למימרא דאית להו שיעורא\u0004 \u0005[\u0006יש \u0005לומר,\u0006 ללמוד מכאן \u0005שיש\u0006 לאורך החוטים \u0005שיעור],\u0006 ואין לפחות ממנו; \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים לכך סתירה\u0005]\u0006 ממה ששנינו: מה שנאמר בתורה \"ועשו להם \u0003ציצית\u0004 על כנפי בגדיהם\" (במדבר טו, לח) — \u0003אין ציצית אלא\u0004 דבר ש\u0003יוצא\u0004 מכנף הבגד, \u0003ואין ציצית אלא משהו,\u0004 מעט. \u0003וכבר עלו זקני בית שמאי וזקני בית הלל לעליית יוחנן בן בתירא\u0004 ודנו בדבר \u0003ואמרו\u0004 ש\u0003ציצית אין לה שיעור. כיוצא בו, לולב אין בו שיעור.\u0004","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ש\u0003אין לה שיעור כלל\u0004 לציצית? ומשיבים: \u0003לא,\u0004"],["\u0003אין לה שיעור למעלה,\u0004 שיכול לעשותה כמה ארוכה שירצה, \u0003אבל יש לה שיעור למטה,\u0004 שבפחות מזה אינו כשר. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 מה ששנינו: \u0003כיוצא בו לולב אין לו שיעור, הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003אין לו שיעור כלל?\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003לולב שיש בו שלשה טפחים כדי לנענע בו\u0004 — \u0003כשר,\u0004 משמע שבפחות מכן פסול! \u0003אלא\u0004 הכוונה היא, \u0003אין לו שיעור למעלה,\u0004 שיכול להיות ארוך כמה שירצה, \u0003אבל יש לו שיעור למטה; הכי נמי\u0004 \u0005[כך גם כן]\u0006 בציצית הכוונה היא \u0003ש\u0004\u0003אין לו שיעור למעלה, אבל יש לו שיעור למטה.\u0004","ובענין אחר, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"ציצת\"\u0004 (במדבר טו, לח) — \u0003אין ציצית אלא ענף\u0004 כלומר, חוטים פרודים זה מזה, \u0003וכן הוא אומר: \"ויקחני בציצת ראשי\"\u0004 (יחזקאל ח, ג) כלומר בשערות ראשו. \u0003ואמר אביי: וצריך לפרודה\u0004 \u0005[להפרידה]\u0006 את חוטי הציצית \u0003כי צוציתא דארמאי\u0004 \u0005[כמו בלורית של גויים],\u0006 שהשערות מחוברות למטה ופרודות מלמעלה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הטיל\u0004 ציצית \u0003על הקרן\u0004 על חודה של הקרן, \u0003או על הגדיל\u0004 חוט עבה שאורגים בשפת הבגד — \u0003כשירה, ר' אליעזר בן יעקב אומר פוסל בשתיהן.\u0004","ומעירים: \u0003כמאן אזלא הא דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו שאמר]\u0006 \u0003רב גידל אמר רב: ציצית צריכה שתהא נוטפת על הקרן\u0004 שתהא תלויה בנקב למעלה מן הקרן ויורדת משם על \u0003הקרן,\u0004 \u0003שנאמר:\u0004 \"ועשו להם ציצית \u0003על כנפי בגדיהם\"\u0004 (במדבר טו, לח), \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר בן יעקב.\u0004","\u0003אמר ר' יעקב אמר ר' יוחנן: וצריך שירחיק\u0004 את המקום שבו מטיל את הציצית \u0003מלא קשר גודל\u0004 (פרק האגודל) משפת הבגד.","ומעירים: \u0003ואיצטריך\u0004 \u0005[והוצרך]\u0006 מה שאמר \u0003רב פפא\u0004 לעיל, שצריך להטיל את הציצית בתוך שלוש אצבעות משפת הבגד, \u0003ואיצטריך\u0004 \u0005[והוצרך]\u0006 מה שאמר \u0003ר' יעקב\u0004 שירחיק מלא קשר גודל. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מ\u0004דברי \u0003רב פפא הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 מה שאמר \u0003תוך שלש\u0004 כוונתו \u0003דלא לירחיק טפי\u0004 \u0005[שלא ירחיק יותר],\u0006 \u0003ו\u0004אולם \u0003כמה\u0004 ש\u0003מקרב\u0004 את הציצית לשפת הבגד \u0003מעלי\u0004 \u0005[טוב\u0006 יותר\u0005],\u0006 לכן \u0003איצטריך\u0004 \u0005[הוצרך\u0006 הדבר\u0005]\u0006 שאמר \u0003ר' יעקב.\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003מ\u0004דברי \u0003ר' יעקב, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מלא קשר גודל\u0004 כוונתו \u0003דלא ליקרב טפי\u0004 \u0005[שלא יקרב יותר],\u0006 \u0003ו\u0004אולם \u0003כמה דרחיק מעלי\u0004 \u0005[שמרחיק יותר טוב],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","מסופר, \u0003רבינא ורב סמא הוו יתבי קמיה\u0004 \u0005[היו יושבים לפני]\u0006 \u0003רב אשי, חזייה\u0004 \u0005[ראה]\u0006 \u0003רב סמא לקרניה דגלימיה\u0004 \u0005[את קרן הגלימה]\u0006 של \u0003רבינא דסתר ובצר\u0004 \u0005[ש\u0006היתה \u0005סתורה וחסרה]\u0006 \u0003מ\u0004שיעור \u0003מלא קשר גודל\u0004 בין נקב הציצית לבין שפת הבגד, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא סבר לה מר להא\u0004 \u0005[האם אין אדוני סבור לזו]\u0006 שאמר \u0003ר' יעקב,\u0004 שצריך להרחיק מלוא קשר גודל? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003בשעת עשייה איתמר\u0004 \u0005[נאמר],\u0006 שצריך שיהא שם מרחק זה, ואם \u0005התמעט לאחר מכן אינו פוסל.\u0006","\u0003איכסיף\u0004 \u0005[התבייש]\u0006 רב סמא ששאל שלא כהלכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: לא תתקיף לך\u0004 \u0005[אל יחרה לך]\u0006 שהוא חכם ממך, \u0003חד מינייהו\u0004 \u0005[אחד מהם,\u0006 מבני ארץ ישראל\u0005],\u0006 \u0003הריהו\u0004 \u0003כתרי מינן\u0004 \u0005[כשנים מאיתנו\u0006 מבני בבל\u0005].\u0006","ועוד בענין הטלת חוטי הציצית בבגד מסופר, \u0003רב אחא בר יעקב רמי ארבע\u0004 \u0005[\u0006היה \u0005מטיל ארבעה\u0006 חוטים בטלית\u0005],\u0006 \u0003ועייף להו מיעף\u0004 \u0005[והיה כופל אותם]\u0006 תחילה, כדי שיהיו שמונה, \u0003ומעייל להו\u0004 \u0005[ומכניס אותם בגלימה]\u0006 \u0003בגלימא\u0004 בנקב, ונמצא שיש לולאה בצד אחד של הנקב ושמונה ראשי חוטים בצידו השני, \u0003ואביק להו\u0004 \u0003מיבק\u0004 \u0005[ו\u0006אז היה \u0005עונב אותם],\u0006 שהיה מכניס את שמונה ראשי החוטים בלולאה, ומושך. ומסבירים: \u0003קסבר\u0004 \u0005[סבור היה]:\u0006 \u0003בעינן תמניא בגלימא\u0004 \u0005[צריכים אנו\u0006 שיהיו \u0005שמונה\u0006 חוטים בשעה שנותן אותם \u0005בגלימה],\u0006 \u0003כי היכי דליהוי\u0004 \u0005[כשם\u0006 שצריך \u0005שיהיו]\u0006 \u0003\"גדיל\"\u0004 \u0003\"גדילים\"\u0004 (כלומר, ארבעה כפולים, שהם שמונה) \u0003במקום\u0004 ה\u0003פתיל,\u0004 כשעושה את הציצית עצמה.","\u0003רב ירמיה מדפתי רמי תמניא\u0004 \u0005[היה מטיל שמונה\u0006 חוטים בבגד\u0005],\u0006 \u0003דאינהו שיתסר\u0004 \u0005[שהם ששה עשר]\u0006 לאחר שהכניס אותם בנקב, ונמצאו שמונה ראשי חוטים בצד זה ושמונה בצד זה, \u0003ולא אביק להו\u0004 \u0005[ולא היה עונב אותם]\u0006 כרב אחא בר יעקב. \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא עביד כדידן\u0004 \u0005[היה עושה כמו\u0006 הציציות \u0005שלנו],\u0006 מכניס ארבעה חוטים בנקב, \u0005והם נעשים שמונה.\u0006","מסופר, \u0003רב נחמן אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003רב אדא בר אהבה רמי חוטי וקא\u0004 \u0005[שמטיל חוטים\u0006 של ציצית \u0005והיה]\u0006 \u0003מברך \"לעשות ציצית\", אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי \"ציצי\" שמענא\u0004 \u0005[מהו \"ציצית\" שאני שומע]?\u0006 והרי \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: ציצית אין צריכה ברכה\u0004 בשעת עשייתה!","ובענין זה מסופר, \u0003כי נח נפשיה\u0004 \u0005[כאשר נפטר]\u0006 \u0003רב הונא, על\u0004 \u0005[נכנס]\u0006 \u0003רב חסדא\u0004 לבית המדרש \u0003למירמא\u0004 \u0005[להשליך,\u0006 להראות סתירה\u0003]\u0004 מדברי \u0003רב\u0004 על \u0003רב,\u0004 וכך הקשה: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב: ציצית אין צריך ברכה\u0004 בעשייתה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר רב: מנין לציצית\u0004 שנעשית \u0003בגוי, שהיא פסולה? שנאמר: \"דבר אל בני ישראל... ועשו להם ציצת\"\u0004 (במדבר טו, לח) — \u0003בני ישראל יעשו ולא הגוים יעשו!\u0004","ותוהים: \u0003והא מאי רומיא\u0004 \u0005[וזו מה הסתירה]?\u0006 מה הקשר בין הדברים? \u0003אמר רב יוסף, קסבר\u0004 \u0005[סבור היה]\u0006 \u0003רב חסדא: כל מצוה ש\u0004עשייתה \u0003כשירה בגוי\u0004 — \u0003בישראל אין צריך לברך\u0004 על עשייתה, שאין לומר בזה \"אשר קדשנו... לעשות\", \u0003כל מצוה שפסולה\u0004 עשייתה \u0003בגוי\u0004 — \u0003בישראל צריך לברך\u0004 על עשייתה.","ותוהים: \u0003וכללא\u0004 \u0005[ו\u0006כי \u0005כלל\u0006 קבוע וברור\u0005]\u0006 \u0003הוא\u0004 זה? \u0003והרי מילה\u0004 ש\u0003כשירה בגוי, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003עיר שאין בה רופא ישראל\u0004 שיכול למול, \u0003ויש בה רופא ארמאי\u0004 (גוי) \u0003ורופא כותי\u0004 (שומרוני) — \u0003ימול ארמאי ואל ימול כותי,\u0004 שעושה לשם עבודה זרה של הר גריזים, אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 ימול \u0003כותי ולא ארמאי,\u0004 מפני שהוא חשוד על שפיכות דמים. ומכל מקום גם לשיטתו, אין מילתו של גוי פסולה.","\u0003ו\u0004אילו \u0003בישראל\u0004 כשעושה את המילה \u0003צריך לברך, דאמר מר\u0004 \u0005[שאמר החכם]:\u0006 \u0003המל\u0004 את התינוק \u0003אומר: \"ברוך אשר קדשנו במצו‍תיו וצונו על המילה\"!\u0004","ומשיבים: \u0003מידי הוא טעמא\u0004 \u0005[כלום\u0006 נאמר \u0005טעם\u0006 זה\u0005],\u0006 כלומר, הרי לא התקשה רב חסדא \u0003אלא ל\u0004שיטת \u0003רב,\u0004 ובאמת \u0003רב מיפסיל פסיל\u0004 \u0005[היה פוסל],\u0006 מילה בגוי. \u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 \u0003מנין למילה בגוי שפסולה? דרו בר פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמר:\u0004 נאמר לאברהם \u0003\"ואתה את בריתי תשמר\"\u0004 (בראשית יז, ט), כלומר, רק אתה, שנצטוית על המילה.","\u0003ר' יוחנן אמר:\u0004 נאמר \u0003\"המול ימול\"\u0004 (שם יג), והוא דורש: \u0003המל ימול,\u0004 ומי שאינו נימול — אינו רשאי למול אחרים.","ומעירים: \u0003סוכה מסייע ליה\u0004 \u0005[מסייעת לו]\u0006 לרב חסדא, שהוא סבור שכל מצוה שעשייתה כשרה בגוי — אין ישראל מברך על עשייתה, ו\u0003תפילין הוי תיובתיה\u0004 \u0005[הריהי קושיתו].\u0006","ומפרטים: \u0003הרי סוכה\u0004 ש\u0003כשירה בגוי, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003סוכת גוים, סוכת נשים, סוכת בהמה, סוכת כותיים, סוכה מכל מקום,\u0004 בכל אופן שתהיה — \u0003כשירה\u0004 למצות סוכה, \u0003ובלבד שתהא מסוככת כהילכתא. ו\u0004אילו","\u0003בישראל אין צריך לברך\u0004 על עשייתה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003העושה סוכה לעצמו, אומר: \"ברוך אתה ה' אלהינו מלך העולם שהחיינו וקימנו והגיענו לזמן הזה\"; בא לישב בה, אומר: \"ברוך אתה ה' אלהינו מלך העולם אשר קדשנו במצו‍תיו וצונו לישב בסוכה\"; ואילו \"לעשות סוכה\"\u0004 בשעת עשייתה \u0003לא מברך.\u0004","מצד שני, \u0003תפילין תיובתיה\u0004 \u0005[קושייתו]\u0006 של רב חסדא: \u0003והרי תפילין\u0004 ש\u0003פסולות בגוי\u0004 אם עשאן, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב חיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004"],["\u0003מפשרניא: ספר תורה, תפילין ומזוזות שכתבן מין\u0004 (כופר) או \u0003כותי\u0004 (שומרוני) או \u0003גוי\u0004 או \u0003עבד\u0004 או \u0003אשה\u0004 או \u0003קטן\u0004 או ישראל \u0003משומד\u0004 (מומר, שעובר עבירות באופן קבוע) — \u0003פסולין, שנאמר: \"וקשרתם\u0004 לאות על ידך... \u0003וכתבתם\"\u0004 (דברים ו, ח— ט), \u0003כל שישנו בקשירה\u0004 ששייך למצות תפילין, שמצווה בה ומאמין בה — \u0003ישנו\u0004 גם \u0003ב\u0004מצות \u0003כתיבה, כל שאינו בקשירה\u0004 — \u0003אינו בכתיבה. ו\u0004בכל זאת","\u0003בישראל אין צריך לברך\u0004 על עשייתם, ש\u0003שלח רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: על תפילין של יד, אומר: \"ברוך אשר קדשנו במצו‍תיו וצונו להניח תפילין\", על תפילין של ראש, אומר: \"ברוך אשר קדשנו במצו‍תיו וצונו על מצות תפילין\", ואילו\u0004 \u0003\"לעשות תפילין\"\u0004 בשעת עשייתן \u0003לא מברך!\u0004","\u0003אלא לאו היינו טעמא\u0004 \u0005[האם לא זה הטעם]:\u0006 \u0003כל מצוה\u0004 ש\u0003עשייתה\u0004 היא \u0003גמר\u0004 ה\u0003מצוה, כגון מילה, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003כשירה בגוי\u0004 — \u0003בישראל צריך לברך\u0004 על עשייתה, \u0003וכל מצוה\u0004 ש\u0003עשייתה לאו\u0004 \u0005[אינו]\u0006 \u0003גמר\u0004 ה\u0003מצוה, כגון תפילין,\u0004 שבמה שעושה תפילין לא נגמרת המצוה עד שיניח אותן, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003פסולות בגוי\u0004 לעשותן — \u0003בישראל אינו צריך לברך\u0004 על עשייתן.","\u0003וב\u0004ענין \u0003ציצית\u0004 האם מברכים על עשייתה, \u0003בהא קמיפלגי\u0004 \u0005[בזה חלוקים\u0006 חכמים\u0005],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב אדא בר אהבה, \u0005סבור]:\u0006 ציצית \u0003חובת טלית הוא,\u0004 וממילא כאשר הוא מטיל את הציציות בטלית נגמרת המצוה, ולכן בירך באותה שעה \"לעשות ציצית\", \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב נחמן בשם רב, \u0005סבור]:\u0006 \u0003חובת גברא\u0004 \u0005[האיש]\u0006 \u0003הוא,\u0004 ואין המצוה \u0003נגמרת אלא בזמן לבישת הטלית, ולכן לדעתו אינו מברך על העשייה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: אתון הכי מתניתו לה\u0004 \u0005[אתם כך אתם שונים אותה]\u0006 את דברי רב יהודה בשם רב, שציצית שעשאה גוי פסולה, ומשום כך הראה רב חסדא סתירה בדברי רב.","\u0003אנן הכי מתנינן לה\u0004 \u0005[אנו כך שונים אותה],\u0006 \u0003אמר רב יהודה אמר רב: מנין לציצית בגוי שכשירה? שנאמר: \"דבר אל בני ישראל... ועשו להם ציצית\"\u0004 (במדבר טו, לח), ויכול היה לומר רק \"ועשו ציצית\", אלא יש לדייק: \u0003יעשו להם\u0004 — אפילו \u0003אחרים\u0004 שאינם ישראל.","\u0003אמר רב יהודה אמר רב: עשאן\u0004 את הציציות \u0003מן הקוצים,\u0004 חוטים היוצאים מן האריג, \u0003ומן הנימין,\u0004 חוטים שתפרו בהם את הבגד ונשארו תלויים בו, \u0003ומן הגרדין,\u0004 מעין ציציות היוצאות מן האריג — \u0003פסולה,\u0004 שצריך לתלות את החוטים בבגד לשם ציצית. אבל אם עשאן \u0003מן הסיסין\u0004 פקעיות של צמר שלא נטווה לשם ציצית — \u0003כשירה.\u0004","\u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה לפני]\u0006 \u0003שמואל, אמר: אף\u0004 העשויה \u0003מן הסיסין פסולה,\u0004 כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה ה\u0003טוייה\u0004 של חוט הציצית \u0003לשמה,\u0004 לשם מצות ציצית.","ומעירים: מחלוקת זו היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 ששנינו בברייתא: תפילין ש\u0003ציפן זהב, או שטלה עליהן\u0004 כלומר, עשה את הבתים מ\u0003עור בהמה טמאה\u0004 — \u0003פסולות.\u0004 אבל אם עשה את הבתים מ\u0003עור בהמה טהורה\u0004 — \u0003כשירות, ואף על פי שלא עיבדן\u0004 את העורות הללו \u0003לשמן. רבן שמעון בן גמליאל אומר: אף עור בהמה טהורה פסולות עד שיעבדן לשמן.\u0004 הרי שכבר נחלקו תנאים היא אם עיבוד חומרי הגלם של המצוה \u0003צריך להיעשות לשמה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב שמואל בר רב יהודה: הא תכילתא היכי צבעיתו לה\u0004 \u0005[תכלת זו\u0006 המשמשת לציצית, \u0005איך אתם צובעים אותה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מייתינן\u0004 \u0005[מביאים אנו]\u0006 \u0003דם חלזון וסמנין\u0004 \u0005[וסממנים שונים],\u0006 \u0003ורמינן להו\u0004 \u0005[ומשליכים אותם]\u0006 \u0003ביורה\u0004 ומרתיחים אותה, \u0003ושקלינא פורתא בביעתא\u0004 \u0005[ולוקחים מעט\u0006 מזה \u0005ב\u0006קליפת \u0005ביצה]\u0006 \u0003וטעמינן להו באודרא\u0004 \u0005[ובודקים אותם ב\u0006חתיכת \u0005מוך],\u0006 לנסות האם התערובת הגיעה לגוון הראוי. \u0003ושדינן ליה לההוא ביעתא\u0004 \u0005[ו\u0006אחר כך \u0005משליכים אנו את\u0006 קליפת \u0005הביצה הזו]\u0006 ואת מה שבתוכה, \u0003וקלינן ליה לאודרא\u0004 \u0005[ושורפים את המוך\u0006 הצבוע\u0005].\u0006","ומעירים: \u0003שמע מינה תלת\u0004 \u0005[למד ממנה\u0006 מתיאור זה \u0005שלושה\u0006 דברים\u0005]:\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003טעימה פסולה,\u0004 שצמר שנצבע לשם בדיקה בלבד, ולא לשם ציצית — פסול לציצית, ולכן שורפים את המוך הצבוע, כדי שלא ישתמשו בו לציצית. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שתהא ה\u0003צביעה\u0004 של התכלת \u0003לשמה.\u0004 \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ש\u0003טעימה\u0004 מן התכלת שביורה \u0003פסלה\u0004 \u0005[פוסלת]\u0006 אותה כולה, ולכן אין עושים את הבדיקה ביורה עצמה.","ומתקשים: \u0003היינו\u0004 \u0005[זהו]\u0006 ש\u0003טעימה פסולה היינו\u0004 \u0005[זהו]\u0006 שצריך \u0003צביעה לשמה,\u0004 שהרי טעימה (צמר שנצבע לנסיון) פסולה מפני שצריך צביעה לשמה! \u0003אמר רב אשי:\u0004 לכך היתה הכוונה, ו\u0003מה טעם קאמר\u0004 \u0005[הוא אומר]:\u0006 \u0003מה טעם טעימה פסולה\u0004 — \u0003משום דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003צביעה לשמה.\u0004","ומעירים: מה שהיסקנו שתכלת ש\"טעמו\" ממנה לשם בדיקה נפסלה, הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 ששנינו בברייתא: תכלת ששימשה ל\u0003טעימה פסולה, משום שנאמר:\u0004 \"ועשית את מעיל האפוד \u0003כליל תכלת\"\u0004 (שמות כח, לא), תכלת ששימשה כולה למטרה זו בלבד, \u0003אלו\u0004 \u0003דברי ר' חנינא בן גמליאל.\u0004","ואילו \u0003ר' יוחנן בן דהבאי אומר: אפילו מראה שני שבה\u0004 כלומר, אפילו אם צבעו בה כבר פעם אחת, וזו הפעם השניה — \u0003כשר, משום שנאמר: \"ושני תולעת\"\u0004 (ויקרא יד, ד), וכאילו נאמר \"ושני\", ומשם למדים לתכלת המוזכרת יחד עמה בכל מקום.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003תכלת אין לה בדיקה,\u0004 אין דרך לבדוק אותה אם כשרה היא, \u0003ו\u0004לכן \u0003אין נקחית\u0004 (נקנית) \u0003אלא מן המומחה,\u0004 שיודעים בו שעושה אותה כראוי. \u0003תפילין יש להם בדיקה,\u0004 שהרי אפשר לבדוק אותן אם כשרות הן\u0003,\u0004 \u0003ו\u0004אולם \u0003אין ניקחין אלא מן המומחה.\u0004 ואילו \u0003ספרים\u0004 (ספרי תורה) \u0003ומזוזות יש להן בדיקה, וניקחין\u0004 (נקנים) \u0003מכל אדם.\u0004","ושואלים: \u0003ותכלת אין לה בדיקה?\u0004 אין דרך לבדוק אותה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה בדיק ליה\u0004 \u0005[בדק אותו]\u0006 באופן הבא, \u0003מייתי מגביא גילא ומיא דשבלילתא\u0004 \u0005[\u0006היה \u0005מביא צריף ומי תילתן]\u0006 \u0003ומימי רגלים\u0004"],["\u0003בן ארבעים יום, ותרי לה בגווייהו מאורתא ועד לצפרא\u0004 \u0005[ושורה אותה,\u0006 את הצמר הצבוע בתכלת, \u0005בתוכם,\u0006 בתוך הסממנים הללו, \u0003מהערב ועד הבוקר],\u0004 \u0003איפרד חזותיה\u0004 \u0005[\u0006אם \u0005התקלקלה מראיתו\u0006 ודהה\u0005]\u0006 — \u0003פסולה,\u0004 שאינה תכלת אמיתית מחלזון, \u0003לא איפרד חזותיה\u0004 \u0005[לא התקלקלה מראיתו]\u0006 — \u0003כשרה. \u0004","ורב אדא קמיה \u0005[לפני]\u0006 \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב עוירא אמר: מייתי חמירא ארכסא דשערי ואפיא לה בגוויה\u0004 \u0005[מביא שאור קשה של שעורים ואופה אותה,\u0006 את התכלת הזו, \u0005בתוך\u0006 השאור\u0003],\u0004 \u0003אישתנאי למעליותא\u0004 \u0005[\u0006אם \u0005נשתנתה לטובה]\u0006 כלומר, שנעשה צבעה חזק יותר — הרי זו \u0003כשרה,\u0004 מפני שהיא תכלת אמיתית, אם נשתנה הצבע \u0003לגריעותא\u0004 \u0005[לגריעות],\u0006 שדהה — הרי היא \u0003פסולה, וסימניך\u0004 לזכור את הדבר: \u0003שינוי שקר, שינוי אמת\u0004 כלומר, שינוי לרעה מגלה את השקר, ושינוי לטובה מגלה שתכלת אמיתית היא. על כל פנים מכאן עולה שיש בדיקה לתכלת, שלא כדברי הברייתא!","ומסבירים: אין הכוונה לבדיקה שמטרתה להבחין בין תכלת לדבר אחר, אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין לה בדיקה נמי דקאמר\u0004 \u0005[גם כן שהוא אומר]\u0006 — לענין \u0003טעימה,\u0004 שלא ניתן לבדוק אם צמר זה נצבע לשם ציצית או לשם נסיון, שהוא פסול.","\u0003מספרים, החכם\u0004 \u0003מר מ\u0004המקום \u0003משכי אייתי תכלתא בשני\u0004 \u0005[הביא תכלת בשנים]\u0006 שהיה \u0003רב אחאי\u0004 גדול הדור, \u0003בדקוה\u0004 \u0005[בדקו אותה]\u0006 \u0003ב\u0004אופן שהציע \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה ואיפרד חזותיה\u0004 \u0005[ונתקלקלה מראיתו],\u0006 ושוב בדקו אותו \u0003ב\u0004אופן שהציע \u0003רב אדא ואישתנאי למעליותא\u0004 \u0005[והשתנתה לטובה],\u0006","\u0003סבר למיפסלה\u0004 \u0005[סבורים היו לפסול אותה]\u0006 משום שלא עמדה בבדיקה הראשונה, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב אחאי\u0004 לתלמידים: \u0003אלא\u0004 נמצא לכאורה כי \u0003הא לא תכילתא\u0004 \u0005[זו לא תכלת]\u0006 \u0003היא, ולא קלא אילן היא,\u0004 שהרי היא עומדת בבדיקה אחת ולא באחרת, ולא שמענו על כך! \u0003אלא שמע מינה שמועתא אהדדי איתמר\u0004 \u0005[למד מכאן שהשמועות\u0006 הללו \u0005יחד\u0006 \u0003נאמרו],\u0004 כיצד?","\u0003היכא דבדקנא\u0004 \u0005[\u0006אם \u0005במקום שבדקנו]\u0006 \u0003ב\u0004דרך שהציע \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה לא איפרד חזותיה\u0004 \u0005[לא נתקלקלה מראיתו]\u0006 — הרי היא \u0003כשרה,\u0004 ואין צורך בבדיקה נוספת, אבל \u0003אם\u0004 \u0003איפרד חזותיה\u0004 \u0005[נתקלקלה מראיתו]\u0006 — \u0003בדקינן לה\u0004 \u0005[בודקים אותה]\u0006 \u0003ב\u0004דרך שהציע \u0003רב אדא בחמירא ארכסא\u0004 \u0005[בשאור ישן],\u0006 אם \u0003אישתני למעליותא\u0004 \u0005[השתנתה לטובה]\u0006 — \u0003כשרה,\u0004 אם השתנתה \u0003לגריעותא\u0004 \u0005[לגריעות]\u0006 — \u0003פסולה.\u0004 וכן \u0003שלחו מתם\u0004 \u0005[משם]\u0006 מארץ ישראל: \u0003שמועתא אהדדי איתמר\u0004 \u0005[השמועות הללו זו על זו נאמרו]\u0006 כמו שהסברנו.","\u0003ר' מני דייק וזבין כחומרי מתניתא\u0004 \u0005[היה מדקדק וקונה\u0006 תכלת לפי החומרות ששנינו בברייתות לעיל;], שטעימה פסולה, והיה קונה תכלת רק מן המומחה. \u0003אמר ליה ההוא סבא\u0004 \u0005[אמר לו זקן אחד]:\u0006 \u0003הכי עבוד קמאי דקמך ואצלח עיסקייהו\u0004 \u0005[כך עשו ראשוני הראשונים\u0006 שלפניך \u0005והצליח עיסקם\u0006 בתכלת].","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הלוקח טלית מצוייצת\u0004 (שיש בה ציציות ובהן תכלת) \u0003מן השוק,\u0004 אם קנה אותה \u0003מישראל\u0004 — \u0003הרי היא בחזקתה\u0004 שהיא כשרה. לקחה \u0003מן הגוי,\u0004 אם לקחה \u0003מן התגר\u0004 (סוחר) — הרי היא \u0003כשרה,\u0004 שמן הסתם אינו רוצה לעשות שם רע לעצמו, וקונה מאדם מוסמך. אם לקחה \u0003מן ההדיוט\u0004 — \u0003פסולה,\u0004 שיש להניח שהגוי עצמו צבעה.","\u0003ו\u0004התירו לקנות מתגר גוי \u0003אף על פי שאמרו: אין אדם רשאי למכור טלית מצוייצת לגוי עד שיתיר ציציותיה,\u0004 מפני שפעמים מזדמן שאדם עושה שלא כדין ומוכר טליתו לגוי כשהיא מצוייצת.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 אסרו למכור לגוי טלית עם ציצית? \u0003הכא תרגימו\u0004 \u0005[כאן תרגמו]\u0006 והסבירו: \u0003משום זונה,\u0004 שילך הגוי אצל זונה, ויחשבו שהיה זה ישראל. \u0003רב יהודה אמר: שמא\u0004 הישראל \u0003יתלוה עמו בדרך\u0004 ויחשוב שגם הוא ישראל, \u0003ויהרגנו\u0004 הגוי.","מסופר, \u0003רב יהודה רמי תכילתא לפרזומא דאינשי ביתיה\u0004 \u0005[היה מטיל תכלת,\u0006 ציצית \u0005לטלית של אנשי ביתו]\u0006 כלומר, של אשתו. \u0003ו\u0004כן היה \u0003מברך כל צפרא\u0004 \u0005[בוקר]\u0006 על טליתו את הברכה \u0003\"להתעטף בציצית\".\u0004","ושואלים: \u0003מדרמי\u0004 \u0005[מתוך שהיה מטיל]\u0006 ציצית בבגדי אשתו נראה כי \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מצות עשה שלא הזמן גרמא הוא\u0004 הציצית, ולכן גם הנשים חייבות בה, ואולם אם כן הוא, \u0003אמאי\u0004 \u0005[מדוע]\u0006 היה \u0003מברך\u0004 על טליתו \u0003כל צפרא וצפרא\u0004 \u0005[כל בוקר ובוקר]?\u0006 הרי לא היה פטור ממנה בלילה!","ומשיבים: רב יהודה עשה כן \u0003כ\u0004דעת \u0003רבי, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003תפילין כל זמן שמניחן מברך עליהן,\u0004 ואפילו כמה פעמים ביום. \u0003דברי רבי.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003כל שעתא נמי\u0004 \u0005[כל שעה\u0006 שפושט את הטלית ולובש \u0005גם כן]\u0006 יברך על הטלית, ולא רק בבוקר! ומשיבים: \u0003רב יהודה איניש צניעא הוה\u0004 \u0005[אדם צנוע היה],\u0006 \u0003ולא שרי ליה לגלימיה כוליה יומא\u0004 \u0005[ולא היה מתיר,\u0006 פושט, \u0005את גלימתו כל היום].\u0006 ושואלים: \u0003ומאי שנא מצפרא\u0004 \u0005[ובמה שונה,\u0006 שהיה מברך \u0005בבוקר]?\u0006 ומסבירים: היה עושה כן \u0003כי משני\u0004 \u0005[כאשר\u0006 היה \u0005משנה]\u0006 \u0003מכסות לילה לכסות יום.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הכל חייבין בציצית, כהנים, לוים וישראלים, גרים, נשים ועבדים. ר' שמעון פוטר בנשים, מפני ש\u0004הציצית \u0003מצות עשה שהזמן גרמא הוא, וכל מצות עשה שהזמן גרמא נשים פטורות.\u0004 ודנים בברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003הכל חייבין בציצית, כהנים, לוים וישראלים.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003כהנים לוים וישראלים פטירי\u0004 \u0005[פטורים],\u0006 \u0003מאן ליחייב\u0004 \u0005[מי יהיה חייב]\u0006 בציצית?","ומשיבים: הדין ש\u0003כהנים\u0004 חייבים בציצית \u0003איצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"לא תלבש שעטנז צמר ופשתים יחדו. גדילים תעשה לך\"\u0004 (דברים כב יא— יב), היינו אומרים: \u0003מאן דלא אישתרי\u0004 \u0005[מי שלא\u0006 \u0003הותרו]\u0004 \u0003כלאים\u0004 (שעטנז) \u0003לגביה\u0004 \u0005[אצלו]\u0006 \u0003בלבישה\u0004 — \u0003הוא דמיחייב\u0004 \u0005[שמחויב]\u0006 \u0003בציצית,\u0004 אבל \u0003הני\u0004 \u0005[אלה]\u0006 ה\u0003כהנים, הואיל ואישתרי\u0004 \u0005[והותרו]\u0006 \u0003כלאים לגבייהו\u0004 \u0005[אצלם],\u0006 שיש בבגדי הכהונה אבנט שהוא עשוי כלאיים, אם כן \u0003לא ליחייבו\u0004 \u0005[לא יהיו חייבים]\u0006 כלל בציצית, על כן","\u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003נהי דאישתרי בעידן\u0004 \u0005[גם אם אמנם הותרו\u0006 ללבוש כלאיים \u0005בשעת]\u0006 \u0003עבודה\u0004 במקדש, \u0003בלא עידן\u0004 \u0005[שלא\u0006 ב\u0005זמן]\u0006 \u0003עבודה לא אישתרי\u0004 \u0005[לא הותרו],\u0006 ולכן הם חייבים.","שנינו ש\u0003ר' שמעון פוטר בנשים,\u0004 מפני שהציצית מצות עשה שהזמן גרמא. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון\u0004 שהוא סבור כן? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"וראיתם אותו\"\u0004 (במדבר טו, לט) — \u0003פרט לכסות לילה,\u0004 שלא ניתן לראות בלילה.","ויש לשאול, \u0003אתה אומר: פרט לכסות לילה, או אינו אלא פרט לכסות סומא,\u0004 שאינו יכול לראות את הציציות שלו? \u0003כשהוא אומר: \"אשר תכסה בה\"\u0004 (דברים כב, יב), והוא ביטוי מיותר לכאורה, שכבר נאמר לפני כן \"כסותך\" — \u0003הרי כסות סומא אמור,\u0004 ולפיכך \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה\u0004 כיצד \u0003אני מקיים\u0004 את הפסוק \u0003\"וראיתם אותו\"? פרט לכסות לילה.\u0004","ושואלים: \u0003ומה ראית לרבות כסות סומא\u0004 מ\"אשר תכסה בה\", \u0003ולהוציא כסות לילה\u0004 מ\"וראיתם אותו\"? ושמא נאמר להיפך, שהרי אין לכך הכרע ממשמעות הכתוב! ומשיבים: \u0003מרבה אני כסות סומא שישנה בראיה אצל אחרים,\u0004 ואף שהוא עצמו אינו רואה, \u0003ומוציא אני כסות לילה שאינה בראיה\u0004 גם \u0003אצל אחרים.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' שמעון,"],["\u0003האי\u0004 \u0005[\u0006הפסוק \u0005הזה]\u0006 \u0003\"אשר תכסה בה\"\u0004 (דברים כב, יב) \u0003מאי עבדי ליה\u0004 \u0005[מה עושים הם לו]?\u0006 מה הם לומדים ממנו? ומשיבים: \u0003מיבעי להו לכדתניא\u0004 \u0005[נצרך\u0006 הוא \u0005להם לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 נאמר \u0003\"על ארבע כנפות כסותך\"\u0004 (שם), ומכאן נלמד: \u0003ארבע ולא שלש,\u0004 שכסות בעלת שלוש כנפות פטורה מציצית.","ויש לשאול: \u0003אתה אומר ארבע ולא שלש, או אינו אלא ארבע ולא חמש? כשהוא אומר: \"אשר תכסה בה\"\u0004 לרבות — \u0003הרי בעלת חמש אמור, ומה אני מקיים \"על ארבע\"?\u0004 לומר: \u0003ארבע ולא שלש.\u0004","ושואלים: \u0003ומה ראית לרבות בעלת חמש ולהוציא בעלת שלש?\u0004 מדוע לא תלמד להיפך? ומשיבים: \u0003מרבה אני בעלת חמש\u0004 — מפני \u0003שיש בכלל חמש ארבע, ומוציא אני בעלת שלש\u0004 — מפני \u0003שאין בכלל שלש ארבע.\u0004","ושואלים: \u0003ור' שמעון,\u0004 כיצד לומד הוא הלכה זו לחייב בעלת חמש? ומשיבים: \u0003מ\u0004המילה הנוספת \u0003\"אשר\u0004 תכסה\" \u0003נפקא\u0004 \u0005[יוצא]\u0006 הדבר. \u0003ורבנן\u0004 \u0005[וחכמים]?\u0006 ללמוד מן המלה \u0003\"אשר\" לא משמע להו\u0004 \u0005[להם].\u0006","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003האי\u0004 \u0005[אותו]\u0006 הכתוב \u0003\"וראיתם אתו\"\u0004 (במדבר טו, לט), שר' שמעון למד ממנו לפטור כסות לילה, \u0003מאי עבדי ליה\u0004 \u0005[מה\u0006 הם \u0005עושים בו]?\u0006 כיצד מפרשים הם אותו? ומשיבים: \u0003מיבעי להו לכדתניא\u0004 \u0005[נצרך להם לכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"וראיתם אתו וזכרתם\"\u0004 (שם) לומר: \u0003ראה מצוה זו וזכור מצוה אחרת התלויה בו, ואיזו זו? זו\u0004 מצות \u0003קרית שמע, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מאימתי קורין את שמע בשחרית? משיכיר בין תכלת ללבן\u0004 שבציצית.","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"וראיתם אותו וזכרתם\"\u0004 — \u0003ראה מצוה זו וזכור מצוה אחרת הסמוכה לה\u0004 בכתוב, \u0003ואיזו זו? זו מצות כלאים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תלבש שעטנז צמר ופשתים יחדו. גדילים תעשה לך\"\u0004 (דברים כב, יא—יב).","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"וראיתם אתו וזכרתם את כל מצו‍ת ה' \"\u0004(במדבר טו, לט), \u0003כיון שנתחייב אדם במצוה זו\u0004 של ציצית — \u0003נתחייב בכל מצו‍ת כולן.\u0004 ומעירים: \u0003ו\u0004דעת \u0003ר' שמעון היא,\u0004 ש\u0003אמר:\u0004 ציצית \u0003מצות עשה שהזמן גרמא היא,\u0004 שרק אנשים חייבים בה ולא נשים, ולכן רק מי שחייב בציצית חייב גם בכל המצוות, להוציא נשים שאינן חייבות בכל המצוות.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"וראיתם אתו וזכרתם את כל מצו‍ת ה' \",\u0004 לומר: \u0003שקולה מצוה זו כנגד כל המצו‍ת כולן.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"וראיתם אתו וזכרתם... ועשיתם\"\u0004 — \u0003ראיה מביאה לידי זכירה, זכירה מביאה לידי עשיה. ור' שמעון בר יוחאי אומר: כל הזריז במצוה זו\u0004 של ציצית, ששוקד לקיימה כראוי — \u0003זוכה ומקבל פני שכינה, כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"וראיתם אתו\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"את ה' אלהיך תירא ואתו תעבד\"\u0004 (דברים ו, יד), מה \"אותו\" האמור שם מתייחס לשכינה, אף \"וראיתם אותו\" מתייחס לשכינה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חביבין ישראל שסיבבן הקדוש ברוך הוא במצו‍ת\u0004 מכל צד, \u0003שיש\u0004 \u0003תפילין בראשיהן ותפילין בזרועותיהן וציצית בבגדיהן ומזוזה לפתחיהן, ועליהן\u0004 על מצוות אלה \u0003אמר דוד: \"שבע ביום הללתיך על משפטי צדקך\"\u0004 (תהלים קיט, קסט), שתי תפילין, ארבע ציציות ומזוזה — הרי שבע.","ומוסיפים: \u0003ובשעה שנכנס דוד לבית המרחץ וראה עצמו עומד ערום, אמר: אוי לי שאעמוד ערום בלא מצוה! וכיון שנזכר ב\u0004מצות ה\u0003מילה שבבשרו נתיישבה דעתו\u0004 עליו, שהרי בכל זאת יש בו מצוה. \u0003לאחר שיצא\u0004 מבית המרחץ, \u0003אמר עליה\u0004 על מצות מילה \u0003שירה\u0004 מיוחדת, \u0003שנאמר: \"למנצח על השמינית מזמור לדוד\"\u0004 (תהלים יב, א) — \u0003על מילה שניתנה ב\u0004יום ה\u0003שמיני\u0004 להולדת הבן.","\u0003ר' אליעזר בן יעקב אומר: כל שיש לו תפילין בראשו ותפילין בזרועו וציצית בבגדו ומזוזה בפתחו\u0004 — \u0003הכל בחיזוק\u0004 כלומר, מחוזק הוא מכל צד \u0003שלא יחטא, שנאמר: \"והחוט המשלש לא במהרה ינתק\"\u0004 (קהלת ד, יב), והן שלוש המצוות המוזכרות כאן, \u0003ואומר: \"חנה מלאך ה' סביב ליראיו ויחלצם\"\u0004 (תהלים לד, ח), שמלאך ה' מסבב את יראי ה' המקיימים מצוותיו ומחלצם מן החטא.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר:\u0004 מפני \u0003מה נשתנה תכלת מכל מיני צבעונין\u0004 שאותו בחר ה' לציצית? \u0003מפני שהתכלת דומה\u0004 בצבעה \u0003לים, וים דומה לרקיע, ורקיע\u0004 דומה \u0003לכסא הכבוד, שנאמר: \"ותחת רגליו כמעשה לבנת הספיר וכעצם השמים לטהר\"\u0004 (שמות כד, י), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כמראה אבן ספיר דמות כסא\"\u0004 (יחזקאל א, כו).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: גדול עונשו של\u0004 המבטל \u0003לבן\u0004 שבציצית \u0003יותר מעונשו של\u0004 המבטל \u0003תכלת,\u0004 למרות שהתכלת חשובה יותר, \u0003משל למה הדבר דומה? למלך בשר ודם שאמר לשני עבדיו\u0004 ציוה עליהם, \u0003לאחד אמר: הבא לי חותם של טיט, ולאחד אמר: הבא לי חותם של זהב, ופשעו\u0004 (התרשלו) \u0003שניהם ולא הביאו, איזה מהן עונשו מרובה? הוי אומר: זה שאמר לו הבא לי חותם של טיט ולא הביא,\u0004 שהרי הוא זול ומצוי לכל.","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בשם ר' מאיר, \u0003היה ר' מאיר אומר: חייב אדם לברך מאה ברכות בכל יום, שנאמר: \"ועתה ישראל מה ה' אלקיך שאל מעמך\"\u0004 (דברים י, יב), \"מה\", כמו \"מאה\".","מסופר, \u0003רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא בשבתא וביומי טבי\u0004 \u0005[בשבת ובימים טובים],\u0006 שהתפילות קצרות יותר, ואין שמונה עשרה ברכות בתפילה, \u0003טרח וממלי להו באיספרמקי ומגדי\u0004 \u0005[היה טורח וממלא אותן,\u0006 את מאה הברכות, \u0005בבשמים ומגדים]\u0006 שהיה מברך עליהם.","עוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: חייב אדם לברך שלש ברכות בכל יום\u0004 לשבח את הקב\"ה על חסדיו, ו\u0003אלו הן: \"שלא עשאני גוי\", \"שלא עשאני אשה\", \"שלא עשאני בור\".\u0004","מסופר, \u0003רב אחא בר יעקב שמעיה לבריה דהוה קא\u0004 \u0005[שמע את בנו שהיה]\u0006 \u0003מברך \"שלא עשאני בור\"\u0004 כדברי הברייתא, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כולי האי נמי\u0004 \u0005[כל כך גם כן]\u0006 אתה מברך? כלומר, אין זה מן הראוי לזלזל בכבוד ישראל אף כשהם בורים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואלא מאי\u0004 \u0005[מה]\u0006 \u0003מברך\u0004 כדי להשלים את מנין הברכות? אמר לו: \u0003\"שלא עשאני עבד\".\u0004 שאל אותו: \u0003היינו\u0004 \u0005[הרי זה]\u0006 בדיוק כמו הברכה \"שלא עשאני \u0003אשה\",\u0004 שעל שניהם מוטל שיעבוד! השיב לו: \u0003עבד\u0004"],["\u0003זיל טפי\u0004 \u0005[מזולזל יותר]\u0006 מאשה, ולכן תיקנו על כך ברכה מיוחדת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חלזון זהו\u0004 שממנו עושים את התכלת, \u0003גופו דומה לים, וברייתו דומה לדג, ועולה\u0004 ליבשה \u0003אחד לשבעים שנה, ובדמו צובעין תכלת\u0004 (ציצית), \u0003לפיכך\u0004 מפני שהוא נדיר \u0003דמיו יקרים.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' נתן: אין לך כל מצוה,\u0004 ואפילו מצוה \u0003קלה שכתובה בתורה, שאין\u0004 לה \u0003מתן שכרה בעולם הזה, ולעולם הבא איני יודע כמה\u0004 שכרה. \u0003צא ולמד ממצות ציצית\u0004 שהיא מצוה קלה, שכך מסופר בעניינה:","\u0003מעשה באדם אחד שהיה זהיר במצות ציצית, שמע שיש זונה בכרכי הים שנוטלת ארבע מאות זהובים בשכרה, שיגר\u0004 (שלח) \u0003לה ארבע מאות זהובים וקבע לה זמן. כשהגיע זמנו, בא וישב\u0004 (המתין) \u0003על הפתח.\u0004","\u0003נכנסה שפחתה\u0004 של אותה זונ \u0003ה\u0004\u0003ואמרה לה: אותו אדם ששיגר ליך ארבע מאות זהובים בא וישב על הפתח. אמרה היא: יכנס, נכנס. הציעה לו שבע מטות, שש של כסף ואחת של זהב, ובין כל אחת ואחת סולם של כסף, ועליונה\u0004 היתה מיטה \u0003של זהב,\u0004","\u0003עלתה וישבה על גבי עליונה כשהיא ערומה, ואף הוא עלה\u0004 כדי \u0003לישב ערום כנגדה,\u0004 בתוך כך \u0003באו ארבע ציציותיו וטפחו לו על פניו, נשמט\u0004 (הפיל עצמו) מלמעלה \u0003וישב לו על גבי קרקע, ואף היא נשמטה וישבה על גבי קרקע. אמרה לו\u0004 בלשון שבועה: \u0003גפה\u0004 (אהבתה) \u0003של רומי, שאיני מניחתך\u0004 ללכת \u0003עד שתאמר לי מה מום ראית בי.\u0004","\u0003אמר לה\u0004 בלשון שבועה: \u0003העבודה\u0004 (עבודת המקדש), \u0003שלא ראיתי אשה יפה כמותך, אלא מצוה אחת ציונו ה' אלהינו וציצית שמה, וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003בה\u0004 בפרשת ציצית: \u0003\"אני ה' אלהיכם\" שתי פעמים,\u0004 \"אני ה' אלהיכם אשר הוצאתי אתכם מארץ מצרים להיות לכם לאלהים, אני ה' אלהיכם\" (במדבר טו, מא), כלומר, \u0003אני הוא שעתיד ליפרע\u0004 מן העובר על מצוותי, \u0003ואני הוא שעתיד לשלם שכר\u0004 למקיימה, \u0003עכשיו נדמו עלי\u0004 ארבע הציציות \u0003כארבעה עדים\u0004 שיעידו עלי.","\u0003אמרה לו: איני מניחך עד שתאמר לי מה שמך ומה שם עירך ומה שם רבך ומה שם מדרשך שאתה למד בו תורה. כתב ונתן בידה.\u0004","\u0003עמדה\u0004 אותה אישה \u0003וחילקה כל נכסיה, שליש\u0004 נתנה \u0003למלכות\u0004 כשוחד, \u0003ושליש\u0004 חילקה \u0003לעניים, ושליש נטלה בידה חוץ מאותן מצעות,\u0004 אותן מטות של כסף וזהב שהציעה לו,","\u0003ובאת לבית מדרשו של ר' חייא. אמרה לו: רבי, צוה עלי ויעשוני גיורת. אמר לה: בתי, שמא עיניך נתת באחד מן התלמידים\u0004 ובגלל זה את רוצה להתגייר? \u0003הוציאה\u0004 אותו \u0003כתב\u0004 שנתן לה אותו תלמיד \u0003מידה ונתנה לו. אמר לה: לכי זכי במקחך.\u0004","ומספרים: \u0003אותן מצעות שהציעה לו באיסור הציעה לו\u0004 מעתה \u0003בהיתר.\u0004 וחוזרים לעיקר הדברים, אותם מצעות \u0003זה מתן שכרו בעולם הזה\u0004 הם, \u0003ולעולם הבא איני יודע כמה.\u0004","\u0003אמר רב יהודה: טלית שאולה\u0004 — \u0003כל שלשים יום\u0004 הראשונים \u0003פטורה מן הציצית, מיכן ואילך חייבת.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 מעין זה: \u0003הדר בפונדקי\u0004 (מלון) \u0003בארץ ישראל, והשוכר בית בחוץ לארץ\u0004 — \u0003כל שלשים יום\u0004 ראשונים ששוהה שם \u0003פטור מן המזוזה, מיכן ואילך חייב. אבל השוכר בית בארץ ישראל\u0004 — \u0003עושה\u0004 לו \u0003מזוזה לאלתר, משום יישוב\u0004 של \u0003ארץ ישראל.\u0004","ושבים למה ששנינו בראש הפרק ש\u0003תפלה\u0004 (תפילין) \u0003של יד אינה מעכבת\u0004 של ראש, ושל ראש אינה מעכבת של יד. \u0003אמר רב חסדא: לא שנו\u0004 שאינה מעכבת \u0003אלא שיש לו\u0004 תפלה אחרת ועכשיו אינה לפניו, או שאינו יכול להניחה, \u0003אבל\u0004 אם \u0003אין לו\u0004 בכלל — \u0003מעכבת.\u0004","\u0003אמרו לו\u0004 לאחר זמן: \u0003אמרת\u0004 דבר זה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא, אלא\u0004 היפך הדברים: \u0003מאן דלית ליה תרי\u0004 \u0005[\u0006וכי \u0005מי שאין לו שתי]\u0006 \u0003מצו‍ת, חד מצוה נמי לא ליעביד\u0004 \u0005[מצוה אחת גם כן לא יעשה]?!\u0006 ושואלים: \u0003ומעיקרא מאי סבר\u0004 \u0005[ומתחילה מה סבור היה]\u0006 שאמר שמי שאין לו אלא אחת לא יניח כלל? ומשיבים: \u0003גזירה שמא יפשע,\u0004 ולא ידאג להשיג את התפילה החסרה לו.","\u0003אמר רב ששת: כל שאינו מניח תפילין עובר בשמונה\u0004 מצוות \u0003עשה,\u0004 הכתובות בארבע פרשיות התפילין (שמות יג, ט. שם טז. דברים ו, ח. שם יא, יח), בכל אחת מהן מצות עשה לתפילין של יד, ומצות עשה לתפילין של ראש.","\u0003וכל שאין לו ציצית בבגדו עובר בחמשה עשה,\u0004 ארבע בפרשת הציצית שבספר במדבר: \"ועשו להם ציצית\", \"ונתנו על ציצית הכנף פתיל תכלת\", \"והיה לכם לציצית\", \"וראיתם אותו\" (במדבר טו, לח— לט).","\u0003וכל כהן שאינו עולה לדוכן עובר בשלשה עשה:\u0004 \"כה תברכו את בני ישראל\" (שם ו, כג), \"אמור להם\" (שם), \"ושמו את שמי על בני ישראל\" (שם כז),","\u0003כל שאין לו מזוזה בפתחו עובר בשני עשה,\u0004 שנאמר: \u0003\"וכתבתם\u0004 על מזוזות ביתך\" (דברים ו, ט) ונאמר שוב בפרשה האחרת: \u0003\"וכתבתם\u0004 על מזוזות ביתך\" (שם יא, כ).","\u0003ואמר ריש לקיש: כל המניח תפילין מאריך ימים, שנאמר:\u0004"],["\u0003\"ה' עליהם יחיו ולכל בהן חיי רוחי ותחלימני והחיני\u0004 (ישעיהו לח, טז), לומר שהמניח תפילין (שבהם כתוב שם ה') על ראשו (\"ה' עליהם\") זוכה לחיים (\"יחיו\"), ומבריא ממחלותיו וזוכה לעוד שנות חיים (\"ותחלימני והחייני\").","במשנה זו שבים לדון בהלכות השייכות למסכת, מנחות. \u0003הסולת והשמן\u0004 של מנחת הנסכים \u0003אין מעכבין את היין\u0004 הבא עם המנחה. שאם הובא יין בלא הסולת והשמן למנחה — מנסכים את היין על המזבח, אף שלא הוקרבה המנחה. וכך הוא הדין לענין הסולת והשמן של המנחה, שהובאו בלא יין לניסוך, הריהם קרבים, \u0003ולא היין מעכבן.\u0004 דין אחר הוא ש\u0003המתנות\u0004 (נתינות מדם הקרבן) \u0003ש\u0004ניתנות \u0003על\u0004 \u0003המזבח החיצון\u0004 (העומד בעזרה) — \u0003אין\u0004 \u0003מעכבות זו את זו,\u0004 שאף אם ניתנה רק מתנת דם אחת בלבד, כיפר הקרבן בדיעבד לבעליו.","שנינו במשנתנו דינה של מנחת הנסכים, ומביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 מה שנאמר בקרבנות הבאים בשבעת ימי חג הסוכות ובשמיני עצרת \u0003\"ומנחתם ונסכיהם\"\u0004 (במדבר כט, יח— לז), בא להורות כי כך הוא סדר הבאתם: לאחר הקרבת הקרבן \u0003הבא\u0004 את ה\u0003מנחה, ואחר כך הבא\u0004 את ה\u0003נסכים.\u0004 אלו דברי חכמים. \u0003רבי אומר:\u0004 מה שנאמר \"...להקריב אשה לה' עולה ומנחה \u0003זבח ונסכים...\"\u0004(ויקרא כג, לז) בא לומר כי כך סדר ההבאה, שבתחילה \u0003הבא זבח\u0004 (הקרבן עצמו), \u0003ואחר כך הבא נסכים,\u0004 ורק לאחר הבאת הנסכים הבא את מנחת הנסכים.","\u0003ו\u0004דנים בשיטות הללו: לשיטת \u0003רבי\u0004 הלמד מהפסוק \"זבח ונסכים\", ואולם \u0003נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 \u0003\"ומנחתם ונסכיהם\"\u0004 שהמנחה קודמת לנסכים! ומשיבים: הפסוק \u0003ההוא מיבעי\u0004 \u0005[נצרך]\u0006 \u0003ל\u0004ענין אחר, ללמד ש\u0003מנחתם ונסכיהם\u0004 הבאים בפני עצמם, לאחר שהובא הזבח, ביום, בלא נסכים, ניתן להקריבם אף \u0003בלילה,\u0004 \u0003ו\u0004כן ש\u0003מנחתם ונסכיהם\u0004 הבאים בפני עצמם לאחר שכבר הוקרב הקרבן עצמו היום, \u0003אפשר להקריבם\u0004 \u0003אפילו ל\u0004יום \u0003מחר.\u0004","ושואלים לצד האחר: \u0003ו\u0004לשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים כי המנחה קודמת לנסכים ולמדו כן מהפסוק \"ומנחתם ונסכיהם\", \u0003נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 \u0003\"זבח ונסכים\"\u0004 להורות שהנסכים קודמים למנחה! ומשיבים: הפסוק \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004ענין אחר, וכדרך שאמר החכם \u0003זעירי,\u0004 שכן \u0003אמר זעירי: אין\u0004 ה\u0003נסכים\u0004 הבאים עם הזבח \u0003מתקדשין\u0004 (מתקבעת קדושתם על זבח זה, שאינם באים אלא עמו ולא עם זבח אחר) \u0003אלא בשחיטת הזבח\u0004 הזה. שמשעה שנשחט הקרבן (\"זבח\") זה — שוב אין הבעלים יכולים לשנותם לזבח אחר אלא הם כ\"שייכים\" אליו (\"זבח ונסכים\"). ואם עדיין לא נשחט הקרבן, יכולים הבעלים לתיתם לקרבן אחר, אף שהפרישם בתחילה לשמו של זבח זה.","\u0003וחוזרים ושואלים לשני הצדדים:\u0004 \u0003ו\u0004לשיטת \u0003רבי\u0004 הסבור שפסוק זה מלמדנו שהנסכים קודמים למנחה, והרי \u0003נמי מיבעי ליה\u0004 \u0005[גם כן צריך אותו]\u0006 את הפסוק הזה \u0003ל\u0004כמו שדרש \u0003זעירי! ו\u0004מן הצד האחר, יש לשאול אף לשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שהפסוק \"מנחתם ונסכיהם\" מלמדנו כי המנחה קודמת לנסכים, ואולם \u0003נמי מיבעי להו\u0004 \u0005[גם כן צריך אותו]\u0006 את הפסוק הזה \u0003ל\u0004למדנו כי \u0003מנחתם ונסכיהם\u0004 קרבים אף \u0003בלילה, ו\u0004כן כי \u0003מנחתם ונסכיהם\u0004 קרבים \u0003אפילו למחר!\u0004","\u0003אלא\u0004 יש לחזור מההסבר הקודם למחלוקת חכמים ורבי, ומציעים הסבר אחר: \u0003היינו טעמייהו דרבנן\u0004 \u0005[זהו טעמם של חכמים],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בפרשת המועדות \"...להקריב אשה לה' עולה ומנחה וזבח ונסכים דבר יום ביומו\" (ויקרא כג, לז), ומן הנאמר \u0003\"עלה ומנחה\"\u0004 יש ללמוד כי מיד אחר הקרבת הקרבן (\"עולה\") יש להביא תחילה את מנחתו, ולאחר מכן יביאו את נסכיו. ושואלים: \u0003ו\u0004לשיטת \u0003רבי\u0004 הסבור שהנסכים קודמים למנחה, והרי \u0003נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 \u0003\"עלה ומנחה\"!\u0004","\u0003אלא\u0004 יש להסביר באופן אחר את מחלוקת חכמים ורבי: \u0003ב\u0004מנחות ונסכים ש\u0003באים עם הזבח\u0004 — \u0003דכולי עלמא\u0004 \u0005[ל\u0006דעת \u0005הכל,\u0006 ואף רבי\u0005]\u0006 \u0003לא פליגי\u0004 \u0005[חולקים]\u0006 שתחילה \u0003מנחה ואחר כך נסכים, דהכתיב\u0004 \u0005[שהרי\u0006 \u0003נאמר]\u0004 \u0003\"עלה ומנחה\". כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 חכמים ורבי הרי זה רק \u0003ב\u0004מנחות ונסכים ה\u0003באין בפני עצמן.\u0004 ש\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי \u0003מ\u0004כיון שבדינם של מנחות ונסכים ה\u0003באין עם הזבח\u0004 הסדר הוא שמקריבים בתחילה \u0003מנחה ואחר כך\u0004 מקריבים את ה\u0003נסכים,\u0004 במנחות ונסכים הבאים \u0003בפני עצמן נמי\u0004 \u0005[גם כן]\u0006 כך הוא הסדר, שבתחילה מקריבים את ה\u0003מנחה ואחר כך\u0004 מקריבים את ה\u0003נסכים. ו\u0004אילו","\u0003רבי\u0004 סבור כי דווקא \u0003התם\u0004 \u0005[שם,\u0006 במנחות ונסכים הבאים עם הזבח\u0005]\u0006 כך \u0003הוא\u0004 הדין — \u0003דאיידי דאתחיל\u0004 \u0005[שמתוך שהתחיל]\u0006 המזבח כבר \u0003באכילה\u0004 (בהקרבת בשר הקרבן עליו), לכך ראוי כי בתחילה \u0003גמר לה לכולא מילתא\u0004 \u0005[יגמור אותה, את כל הדבר]\u0006 של \u0003אכילה,\u0004 על ידי שיאכל אף את המנחה, ולאחר מכן יקריבו את הנסכים על המזבח (שאין זו אכילה, אלא שתיה). \u0003אבל\u0004 כאשר מביאים מנחה ונסכים \u0003בפני עצמן\u0004 — ה\u0003נסכים עדיפי\u0004 \u0005[עדיפים]\u0006 וקודמים בהקרבה, וטעם \u0003הדבר:\u0004 \u0003הואיל דמיתאמרא\u0004 \u0005[שנאמרת]\u0006 \u0003שירה עלייהו\u0004 \u0005[עליהם].\u0006","עוד שנינו במשנה ש\u0003המתנות\u0004 של דם הקרבנות \u0003ש\u0004ניתנות \u0003על\u0004 ה\u0003מזבח החיצון אין מעכבות זו את זו.\u0004 שאם נתן על המזבח נתינת דם אחת בלבד — כיפר בכך.","ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מנין לכל הניתנין על מזבח החיצון שנתנן\u0004 שלא כדינם, בארבע נתינות או בשתי נתינות שהן כארבע, אלא \u0003במתנה אחת שכיפר\u0004 בכך, ויצא ידי חובה? \u0003ש\u0004כן \u0003נאמר \"ודם זבחיך ישפך על מזבח ה' אלהיך\"\u0004 (דברים יב, כז), לומר שאפילו בנתינת דם (\"ישפך\") אחת יצא ידי חובה.","\u0003הפרים והאילים והכבשים\u0004 הקרבים בימים מסויימים בשנה לקרבן אחד, וכגון עולה, ואולם לכמה מטרות נפרדות, וכגון קרבנות מוסף ועוד אחרים הבאים לקרבן אחר מקרבנות היום. \u0003ו\u0004כן קרבנות \u0003השעירים\u0004 — \u0003אינן מעכבין זה את זה.\u0004 שהרי יכולים להקריב את העולות הללו, אף בלא שיוקרבו העולות האחרות. \u0003ר' שמעון אומר: אם היו להם\u0004 לגזברי המקדש מעות שיש בהן כדי לקנות \u0003פרים מרובים\u0004 (כמספר הנדרש), \u0003ו\u0004אולם \u0003לא היו להם\u0004 מעות נוספים כדי לקנות בהן אף את ה\u0003נסכים\u0004 הבאים עם הקרבנות הללו \u0003יביא\u0004 אפילו \u0003פר אחד ונסכים\u0004 הראויים לו, \u0003ולא יקריבו כולם בלא נסכים.\u0004","שנינו במשנתנו כי אין הפרים והאילים והכבשים מעכבים זה את זה, ושואלים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003פרים\u0004 ואילים \u0003וכבשים\u0004 הנזכרים במשנתנו, \u0003דהיכא\u0004 \u0005[של היכן]\u0006 של איזה מועד הם? ומסבירים את השאלה: \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שאלה קרבנות ה\u0003חג\u0004 (חג הסוכות) \u0003\"כמשפט\"\u0004 וכן בקרבנות היום השביעי בסוכות (שם לג) הלשון \u0003\"כמשפטם\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 להורות שאין לשנות מן האמור!","\u0003אלא\u0004 צריך לומר שהכוונה היא לקרבנות מוסף הבאים ב\u0003ראש חדש,\u0004 שיש בהם שני פרים, איל אחד, ושבעה כבשים. או לקרבנות מוסף של \u0003עצרת\u0004 (חג השבועות), שאף בהם יש שני פרים, איל אחד ושבעה כבשים. המנויים ב\u0003חומש הפקודים\u0004 (ספר במדבר: של ראש חודש שם כח, יא."],["אף זה אין לומר, שהרי אמרה משנתנו \u0003\"אילים\"\u0004 בלשון רבים. ומעתה יש לברר: \u0003דהיכא\u0004 \u0005[של איזה]\u0006 מועד הם האילים הללו? \u0003אי דהנהו\u0004 \u0005[אם של אלה\u0006 שהוזכרו למעלה\u0005],\u0006 של ראש חודש או של עצרת הנזכרים בחומש במדבר, הן העולות הבאות כקרבנות המוסף של חג השבועות (במדבר כח, כז) — הרי לקרבן זה רק \u0003איל\u0004 אחד \u0003הוא\u0004 שצריך להביא ולא שנים! ו\u0003אי\u0004 \u0005[אם]\u0006 הכוונה לאילים הבאים ב\u0003עצרת\u0004 (חג השבועות) הבאים עם שתי הלחם ונזכרים בספר \u0003תורת כהנים\u0004 (חומש ויקרא), ובאלה אכן יש שני אילים — אף זה אין לומר, שהרי לשון \u0003\"הויה\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 (\"יהיו עולה לה'...\". ויקרא כג, יח), ולשון זו (\"יהיו\") מורה שכך יהיו ולא אחרת, ולעכב, ושלא כדברי משנתנו!","ומשיבים: \u0003לעולם\u0004 מדובר באילים הבאים בחג ה\u0003עצרת\u0004 הנזכרים בספר \u0003תורת כהנים,\u0004 שהם שני אילים, \u0003והכי קאמר\u0004 \u0005[וכך הוא,\u0006 התנא במשנתנו \u0005אומר,\u0006 זו כוונת דבריו\u0005]:\u0006 אמנם אותם שני אילים הבאים עם שתי הלחם (הנזכרים בתורת כהנים) מעכבים זה את זה (שכן נאמר בהם לשון \"יהיו\"), ואולם \u0003לא\u0004 ה\u0003אילים\u0004 הנאמרים ב\u0003תורת כהנים\u0004 (אלו הבאים עם שתי הלחם) \u0003מעכבי ליה\u0004 \u0005[מעכבים אותו]\u0006 את הבאתו של ה\u0003איל\u0004 הנאמר ב\u0003חומש הפקודים, ו\u0004כמו כן, \u0003לא\u0004 ה\u0003איל\u0004 המוקרב לעולה ומוזכר ב\u0003חומש הפקודים מעכב להו\u0004 \u0005[אותם]\u0006 את הבאתם של שני ה\u0003אילים\u0004 הנזכרים ב\u0003תורת כהנים.\u0004","ותוהים על הסבר זה: \u0003אלא\u0004 מעתה נמצא כי ה\u0003פרים\u0004 (וכן הכבשים) של מוסף חג השבועות (הנזכרים בספר במדבר), לא רק שאין הם מעכבים את הבאת הפר של שתי הלחם (הנזכר בספר ויקרא), אלא \u0003אפילו אהדדי\u0004 \u0005[זה את זה],\u0006 אף שהם כקרבן אחד — הם \u0003לא מעכבי\u0004 \u0005[לא מעכבים],\u0006 שאם אין לו אלא פר אחד — מקריב אותו לעצמו. \u0003ו\u0004אילו דינם של \u0003אילים\u0004 הוא שרק \u0003דהכא ודהכא\u0004 \u0005[של כאן,\u0006 של ספר ויקרא, \u0005ושל כאן,\u0006 של ספר במדבר\u0005],\u0006 \u0003הוא דלא מעכבי\u0004 \u0005[שלא מעכבים]\u0006 זה את זה, אבל \u0003אינהו\u0004 \u0005[הם עצמם]\u0006 — \u0003מעכבי\u0004 \u0005[מעכבים]\u0006 זה את זה. שאם אין לו אלא איל אחד — אין הוא מקריב אותו לעצמו. ואם כן אין דינם שווה, ואילו במשנתנו נשנו כאחד!","ומשיבים: אין זו שאלה, שכן ה\u0003תנא\u0004 של משנתנו \u0003מילי מילי קתני\u0004 \u0005[דברים דברים שנה],\u0006 שכל אחד מהקרבנות יש לו את הלכותיו שלו.","למדנו למעלה כי האילים המובאים עם שתי הלחם בעצרת מעכבים זה את זה, ובענין זה מביאים עוד מן הברייתא על הנאמר בקרבנות המובאים בראש חודש: \u0003\"וביום החדש פר בן בקר תמים וששה\u0004 (ראה \"גרסות\") \u0003כבשים ואיל תמימים יהיו.\u0004 ואיפה לפר ואיפה לאיל יעשה מנחה ולכבשים כאשר תשיג ידו ושמן הין לאיפה\" (יחזקאל מו, ו—ז). ויש לשאול מדוע נאמר בו \u0003\"פר\u0004 בן בקר\" בלשון יחיד, והרי בראש חודש באים שני פרים (כנאמר \"ובראשי חדשיכם תקריבו עולה לה' פרים בני בקר שנים ואיל אחד כבשים בני שנה שבעה תמימים\", במדבר כח, יא)! אלא \u0003מה תלמוד לומר\u0004 (מה מלמדנו הנאמר)?","ומסבירים: \u0003לפי שנאמר בתורה\u0004 בקרבנות ראש חודש \u0003\"פרים\u0004 בני בקר שנים\" בלשון רבים, היה איפוא מקום לומר שאין מביאים בראש חודש אלא שני פרים, ולא פחות מכך. \u0003ומנין\u0004 לנו \u0003שאם לא מצא שנים\u0004 שהריהו \u0003מביא\u0004 פר \u0003אחד?\u0004 לכך \u0003תלמוד לומר\u0004 בפסוק זה \u0003\"פר\"\u0004 בלשון יחיד.","ועוד דנים בכתוב זה, שכן נאמר בו \u0003\"ששה כבשים\"\u0004 (\"וששת כבשים\"), ואולם הרי בראש חודש קרבים שבעה כבשים, ו\u0003מה\u0004 אם כן \u0003תלמוד לומר?\u0004 ומסבירים: \u0003לפי שכתב בתורה\u0004 שיש להביא בראש חודש \u0003שבעה\u0004 כבשים, היה איפוא מקום לומר שאין מביאים אלא שבעה כבשים, ולא פחות מכך. \u0003ומנין\u0004 לנו \u0003שאם לא מצא שבעה\u0004 כבשים, ש\u0003יביא\u0004 על כל פנים \u0003ששה\u0004 כבשים? לכך \u0003תלמוד לומר \"\u0004\u0003ששה\u0004","\u0003ומנין\u0004 לנו \u0003שאם לא מצא ששה\u0004 כבשים, ש\u0003יביא חמשה\u0004 כבשים, ואם לא מצא \u0003חמשה,\u0004 ש\u0003יביא ארבעה,\u0004 ואם לא מצא \u0003ארבעה,\u0004 ש\u0003יביא שלשה,\u0004 ואף אם לא מצא \u0003שלשה,\u0004 ש\u0003יביא שנים,\u0004 \u0003ואפילו\u0004 כבש \u0003אחד\u0004 הריהו מביא? לכך \u0003תלמוד לומר\u0004 בהמשך הדברים \u0003\"ולכבשים כאשר תשיג ידו\"\u0004 — שמביא כבשים, ככל שהשיגה ידו.","ותוהים: \u0003ומאחר דכתיב הכי\u0004 \u0005[שנאמר כך,\u0006 הכתוב \"כאשר תשיג ידו\"\u0005],\u0006 הכתוב \u0003\"ששה כבשים\"\u0004 (ממנו למדנו כי אם לא מצא שבעה כבשים, הריהו מביא ששה כבשים) \u0003למה לי\u0004 עוד לכותבו? ומשיבים: כתוב זה בא ללמדנו שאף שאכן יוצאים בכבש אחד הבא בראש חודש, ואולם כל \u0003כמה\u0004 ש\u0003אפשר להדורי\u0004 \u0005[לחזר,\u0006 לחפש\u0005]\u0006 אחר מספר גבוה יותר של כבשים \u0003מהדרינן\u0004 \u0005[מחזרים].\u0006","ומסבירים עוד את הדרשות הנלמדות מכתוב זה: \u0003ומנין\u0004 לנו \u0003(לאילים שבתורת כהנים)\u0004 שאם היו לפניהם פרים וכבשים כמספרם הראוי (שני פרים ושבעה כבשים), והביאו פרים וכבשים במספר הפחות מכך, \u0003שמעכבין זה את זה?\u0004 לכך \u0003תלמוד לומר\u0004 בכתוב זה בלשון \u0003\"יהיו\",\u0004 להורות שכך יהיו, ולא באופן אחר, ולעכב.","מתוך שהוסברו פסוקים מוקשים בספר יחזקאל, דנים גם בפסוקים סמוכים. נאמר \u0003\"כה אמר ה' אלהים בראשון באחד לחודש תקח פר בן בקר תמים וחטאת את המקדש\"\u0004 (שם מה, יח), ותוהים: כיון שמדובר בקרבנות הבאים בראש חודש (\"באחד לחודש\") ניסן (\"בראשון\"), שאין חל בתאריך זה בשנה כל מועד מיוחד מלבד ראש חודש, מה טעם אמר הכתוב \"ו \u0003חטאת\",\u0004 שמובנו הבאת קרבן חטאת, והלא הפרים הקרבים בראש חודש \u0003עולה היא! אמר ר' יוחנן:\u0004 אכן מוקשה הוא פסוק זה, ו\u0003פרשה זו אליהו\u0004 הנביא \u0003עתיד לדורשה.\u0004","\u0003רב אשי אמר:\u0004 יש מקום לפרש פסוק זה, שלא אמר יחזקאל הנביא את דבריו בקרבנות הבאים בראש חודש ניסן, אלא בקרבן ה\u0003מילואים\u0004 ש\u0003הקריבו\u0004 לאחר שנים, \u0003בימי עזרא.\u0004 שנהגו בחנוכת בית שני שבעת ימי מילואים (ימי כניסתם לעבודה של הכהנים במקדש), למן יום כ\"ג באדר ועד לראש חודש ניסן. ובכל אותם ימים, ובכלל זה בראש חודש ניסן הקריבו פרט לקרבנות מילואים גם קרבן חטאת, ו\u0003כדרך שהקריבו\u0004 בחנוכת המשכן במדבר סיני, \u0003בימי משה\u0004 (ויקרא ט, ב).","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך],\u0006 שנחלקו תנאים בפירושו של פסוק זה שביחזקאל, ש\u0003ר' יהודה אומר\u0004 כי \u0003פרשה זו\u0004 אין בידינו לפרשה, ו\u0003אליהו\u0004 הנביא הוא ש\u0003עתיד לדורשה. אמר לו ר' יוסי: מלואים הקריבו בימי עזרא, בדרך שהקריבו בימי משה. אמר לו\u0004 ר' יהודה בלשון תודה: \u0003תנוח דעתך, שהנחת דעתי\u0004 בהסבר זה.","ומביאים עוד מפסוקים מוקשים שבספר יחזקאל. נאמר \u0003\"וכל נבלה וטרפה מן העוף ומן הבהמה לא יאכלו הכהנים\"\u0004 (שם מד, לא). ותמוה הוא, שכן מפסוק זה יש מקום לדייק כי דווקא ה\u0003כהנים הוא\u0004 ש\u0003לא יאכלו\u0004 מן הנבילה ומן הטריפה, \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נסיק כי \u0003ישראל אכלי\u0004 \u0005[אוכלים]?!\u0006 והרי הנבילה והטריפה אסורות לכל! \u0003אמר ר' יוחנן:\u0004 אכן מוקשה הוא פסוק זה, ו\u0003פרשה זו אליהו\u0004 הנביא \u0003עתיד לדורשה.\u0004","\u0003רבינא אמר:\u0004 ודאי ישראל אסורים באכילתן של אלה, ואולם שאסורות הן ל\u0003כהנים איצטריך ליה\u0004 \u0005[הוצרך לו]\u0006 לומר במיוחד. וטעם הדבר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הואיל ואשתרי\u0004 \u0005[והותרה]\u0006 \u0003מליקה לגבייהו\u0004 \u0005[אצלם]\u0006 אצל הכהנים, שהריהם אוכלים מבשרה של חטאת העוף (שדינה במליקה), ובכל מקרה אחר דבר כזה נחשב לנבילה, אם כן \u0003תשתרי נמי\u0004 \u0005[תותר\u0006 לכהנים \u0005גם כן]\u0006 \u0003נבילה וטרפה\u0004 בכלל. לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \u0005משמיע לנו]\u0006 שאף לכהנים אסור לאכול בשר נבילה וטריפה.","ועוד נאמר בספר יחזקאל: \u0003\"וכן תעשה בשבעה בחדש מאיש שגה ומפתי וכפרתם את הבית\"\u0004 (שם מה, כ). ושואלים: מה עניינם של קרבנות הבאים ב\u0003\"שבעה\u0004 בחודש\", שהרי אין כל מועד שחל ביום השביעי בחודש בכל השנה?!","\u0003אמר ר' יוחנן:\u0004 הכוונה לקרבן פר העלם דבר של ציבור, המובא כקרבן חטאת, אם עברו רוב שבטי ישראל איסור בהוראת בית דין. שכך אמר הכתוב: \"בשבעה\" — \u0003אלו שבעה שבטים שחטאו\u0004 בהוראת בית דין, שמביא הקהל פר העלם דבר של ציבור, \u0003ואף על פי שאין\u0004 הנפשות בשבעה שבטים אלה \u0003רובה של קהל,\u0004 והיה איפוא מקום לומר שייחשב הדבר כחטאם של יחידים (וכל אחד ואחד צריך להביא כשבה או שעירה).","\"ב \u0003חדש\"\u0004 — כוונתו: \u0003אם חדשו\u0004 בית דין הלכה מוטעית \u0003ו\u0004כגון ש\u0003אמרו\u0004 כי ה\u0003חלב מותר.\u0004 \u0003\"מאיש שגה ומפתי\"\u0004 — \u0003מלמד שאין חייבין\u0004 קרבן פר העלם דבר של ציבור \u0003אלא על העלם דבר\u0004 (הוראה מוטעית של בית הדין, שנתעלמה מהם הלכה בזה) הבאה \u0003עם שגגת מעשה\u0004 שעשו רוב שבטי ישראל כהוראתם, ועברו על איסור זה.","אגב הזכרת פסוקים מוקשים אלה שבספר יחזקאל ודרשותיהם, מביאים מה ש\u0003אמר רב יהודה, אמר רב\u0004 בעניינו של ספר יחזקאל: \u0003זכור אותו האיש לטוב, וחנינא בן חזקיה שמו, שאלמלא הוא\u0004 היה \u0003נגנז ספר יחזקאל,\u0004 ולא היה נכלל בכתבי הקודש, מפני \u0003שהיו דבריו\u0004 של ספר יחזקאל נראים כמי ש\u0003סותרין דברי תורה. מה עשה\u0004 חנינא בן חזקיה? \u0003העלה\u0004 לעליית ביתו \u0003שלש מאות גרבי\u0004 (כדי) \u0003שמן\u0004 למאור ולמזון, כדי שיוכל לשבת לעיין בדבר ולדרוש, \u0003וישב ב\u0004אותה \u0003עלייה ודרשו\u0004 לספר יחזקאל, עד שיישב את כל המקומות המוקשים בו, והסבירם באופן שאין בהם סתירה לדברי התורה.","ושבים לבירור דברי משנתנו. שנינו בה ש\u0003אמר ר' שמעון\u0004 ש\u0003אם היו להם פרים מרובין\u0004 ונסכים מעטים — לא יביא פרים אלא כאשר יש אתם נסכים.","ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: על הנאמר בספר יחזקאל \u0003\"ואיפה לפר ואיפה לאיל יעשה מנחה ולכבשים כאשר תשיג ידו ושמן הין לאיפה\"\u0004 (שם מו, ז), \u0003אמר ר' שמעון\u0004 בתמיהה: \u0003וכי מדת פרים ואילים אחת היא\u0004 (\"ואיפה לפר ואיפה לאיל יעשה מנחה\")? והרי למנחת הפר מביאים שלשה עשרונים סולת, בעוד שלמנחת האיל מביאים שני עשרונים סולת בלבד!","\u0003אלא\u0004 בא כתוב זה ללמדנו כיצד יש לנהוג במקרה מסויים, \u0003שאם היו להם\u0004 מעות כדי הבאת \u0003פרים מרובין\u0004 כמספרם הראוי להקרבה במועד זה, \u0003ו\u0004אולם \u0003לא היו\u0004 המעות דיים כדי הבאתם של ה\u0003נסכים\u0004 לכל הפרים הללו — מוטב ש\u0003יביאו פר אחד ונסכיו\u0004 אתו, \u0003ואל יקרבו\u0004 הפרים \u0003כולן בלא נסכים. ו\u0004כן \u0003אם היו להם\u0004 די מעות"],["כדי הבאתם של \u0003אילים מרובין\u0004 כמספרם הראוי, \u0003ו\u0004אולם \u0003לא היה להן\u0004 מעות כדי הבאת \u0003איפתן\u0004 (איפת המנחה) של כל האילים — \u0003יביאו איל אחד ואיפתו, ולא יקרבו כולם בלא איפות\u0004 של מנחה.","בחג השבועות מקריבים קרבנות עולה חטאת ושלמים. לעולה — פר, שני אילים ושבעה כבשים. לחטאת — שעיר. ולשלמים — שני כבשים המונפים עם שני הלחם. והקרבנות הקרבים לעולה, \u0003הפר והאילים והכבשים, והשעיר\u0004 הקרב לחטאת — \u0003אין מעכבין את\u0004 הקרבת שתי \u0003הלחם\u0004 של חג השבועות. שאף אם לא הובאו הקרבנות הללו — מביאים את שתי הלחם. \u0003ו\u0004כמו כן אף \u0003לא\u0004 שתי \u0003הלחם מעכבן\u0004 לקרבנות הללו, שאף אם לא הובאו שתי הלחם — מביאים את הקרבנות הללו.","ואולם \u0003הלחם מעכב את\u0004 שני \u0003הכבשים\u0004 הבאים לשלמים. ולכך אם לא הובאו שתי הלחם — אין מביאים את הכבשים. \u0003ואין הכבשים\u0004 לשלמים \u0003מעכבין את הלחם,\u0004 ולכך אם לא היו בידיהם כבשים לשלמים — מביאים את שתי הלחם. אלו \u0003דברי ר' עקיבא.\u0004","\u0003אמר ר' שמעון בן ננס: לא כי\u0004 (אינו כן) כדברי ר' עקיבא, \u0003אלא\u0004 היפוכם של דברים, שני \u0003הכבשים\u0004 הבאים לשלמים — \u0003מעכבין את הלחם, ו\u0004אילו שתי \u0003הלחם —\u0004 \u0003אינו מעכב\u0004 את \u0003הכבשים.\u0004 וראיה לדבריו: \u0003שכן מצינו\u0004 (מצאנו) \u0003כשהיו\u0004 בני \u0003ישראל במדבר\u0004 סיני, בצאתם ממצרים, כל אותן \u0003ארבעים שנה קרבו\u0004 שני ה\u0003כבשים\u0004 של חג השבועות \u0003בלא\u0004 שקרבו אתם שני ה\u0003לחם,\u0004 שהרי אין שתי הלחם באים אלא מתבואת ארץ ישראל, ולאחר שנכנסו אליה בני ישראל. ולכך, \u0003אף כאן\u0004 בשעת הדחק, כאשר לא נמצאו להם שתי הלחם — \u0003יקרבו\u0004 שני ה\u0003כבשים בלא לחם.\u0004 ואולם שתי הלחם אינם קרבים אלא אם כן קרבים אתם שני הכבשים.","\u0003אמר ר' שמעון:\u0004 אכן \u0003הלכה\u0004 היא \u0003כדברי בן ננס\u0004 במחלוקתו עם ר' עקיבא, ששני הכבשים מעכבים את שתי הלחם ואין שתי הלחם מעכב את שני הכבשים, \u0003אבל אין הטעם\u0004 להלכה זו \u0003כדבריו\u0004 (כנימוק שהביא).","מפני \u0003שכל\u0004 הקרבנות בחג השבועות \u0003האמור בחומש הפקודים\u0004 (ספר במדבר), בפרשת פנחס (שם כח, כז), פר אחד ואיל אחד ושבעה כבשים לקרבנות המוספים — \u0003קרב\u0004 בהיות בני ישראל \u0003במדבר, ו\u0004אולם \u0003כל\u0004 סדר הבאת הקרבנות בחג השבועות \u0003האמור בתורת כהנים\u0004 (ספר ויקרא), הם קרבנות הבאים עם שתי הלחם — \u0003אין קרב ב\u0004זמן שהיו ישראל \u0003במדבר,\u0004 ולא רק שתי הלחם לא קרבו אז, אלא אף שני כבשי העצרת שאתם לא קרבו. שכן רק \u0003משבאו\u0004 בני ישראל \u0003לארץ\u0004 ישראל \u0003קרבו אלו ואלו,\u0004 הן קרבנות המוספים של חג השבועות, והן שתי הלחם וקרבנותיהם ושלא כדברי בן ננס בדברי הסברו.","אלא \u0003מפני מה\u0004 בכל זאת \u0003אני אומר\u0004 שהלכה כדברי בן ננס, ו\u0003יקרבו\u0004 שני ה\u0003כבשים\u0004 אף \u0003בלא\u0004 שקרבו שתי ה\u0003לחם? מפני שהכבשים מתירין את עצמן\u0004 (את בשרם לאכילת כהנים) על ידי הקטרת אימוריהם על המזבח, ואף שלא הוקרב הלחם. \u0003ו\u0004מדוע \u0003לא\u0004 יקרב \u0003הלחם בלא\u0004 שקרבים עמו שני ה\u0003כבשים?\u0004 מפני \u0003שאין לו\u0004 ללחם \u0003מי\u0004 ש\u0003יתירנו,\u0004 שלא הותר לאכילת כהנים אלא אחר הקרבת שני הכבשים.","שנינו במשנתנו דין הקרבת הקרבנות הבאים בחג השבועות עם שתי הלחם כאשר לא נמצאו להם שתי הלחם. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר בדין קרבנות אלה \"והקרבתם על הלחם שבעת כבשים תמימים בני שנה ופר בן בקר אחד ואילים שנים יהיו עולה לה'...\" (ויקרא כג, יח). ודנים בכתוב זה: מה שנאמר \u0003\"והקרבתם על הלחם\"\u0004 — הרי זה מורה כי \u0003חובה\u0004 היא שיהיו הקרבנות הללו באים דווקא \u0003על הלחם,\u0004 וכאשר אין להם שתי הלחם אין הקרבנות הללו קרבים. ואולם מה שנאמר לאחר מכן \u0003\"שבעת כבשים תמימים\"\u0004 מורה שהריהם קרבים \u0003אף על פי שאין לחם,\u0004 ו","\u0003אם כן\u0004 מעתה יש לשאול: \u0003מה תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"על הלחם\"?\u0004 הרי זה \u0003מלמד שלא נתחייבו בכבשים קודם שנתחייבו בלחם.\u0004 אלו \u0003דברי ר' טרפון.\u0004","\u0003ר' עקיבא אומר: יכול\u0004 אתה לומר כי \u0003הן הן\u0004 ה\u0003כבשים האמורים כאן\u0004 (בפרשת \"אמור\" שבספר ויקרא, בקרבנות הבאים עם שתי הלחם), \u0003הן הן\u0004 ה\u0003כבשים האמורים בחומש הפקודים\u0004 (בפרשת \"פינחס\" שבספר במדבר, בקרבנות המוספים), שבשני המקומות מדובר באותו קרבן עצמו. ואולם כנגד זה \u0003אמרת\u0004 (עליך לומר), כי \u0003כשאתה מגיע אצל\u0004 קרבנות ה\u0003פרים ו\u0004ה\u0003אילים\u0004 הנמנים בשני המקראות הללו, ששונים הם זה מזה במספרם (בפרשת \"אמור\": פר אחד ושני אילים, ובפרשת \"פינחס\": שני פרים ואיל אחד) ומכאן ש\u0003אינן הן\u0004 קרבן אחד, \u0003אלא\u0004 שני קרבנות אחרים, ו\u0003הללו\u0004 שנאמרו בספר ויקרא \u0003באין בגלל עצמן, והללו\u0004 שבספר במדבר \u0003באין בגלל לחם.\u0004","\u0003נמצא\u0004 מעתה, כי \u0003מה שאמור בחומש הפקודים\u0004 (ספר במדבר) — היה \u0003קרב\u0004 אף בהיות בני ישראל \u0003במדבר\u0004 סיני, שהרי אלה קרבנות הבאים לעצמם. \u0003ו\u0004אילו \u0003מה שאמור בתורת כהנים\u0004 (ספר ויקרא) — \u0003לא\u0004 היה \u0003קרב במדבר,\u0004 שהרי הקרבנות הללו באים משום הלחם, שלא קרב במדבר.","ושואלים על דברי ר' עקיבא: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 נאמר כי אמנם קרבנות ה\u0003פרים ו\u0004ה\u0003אילים\u0004 הנזכרים בספר ויקרא \u0003לאו אינהו\u0004 \u0005[אין הם]\u0006 הקרבנות הנזכרים בספר במדבר, \u0003הא\u0004 \u0005[הרי]\u0006 מניינם של קרבנות ה\u0003כבשים\u0004 שווה בזה ובזה, ומעתה יש מקום לומר כי \u0003אינהו נינהו\u0004 \u0005[אותם\u0006 הקרבנות \u0005הם]!\u0006 ומשיבים: \u0003מדהני אישתנו\u0004 \u0005[מתוך שאלה,\u0006 הפרים והאילים, \u0005השתנו,\u0006 שקרבנות נבדלים הם\u0005],\u0006 \u0003הני נמי דאחריני\u0004 \u0005[אלה,\u0006 הכבשים, \u0005גם כן אחרים].\u0006","ושואלים: \u0003ופרים ואילים\u0004 עצמם \u0003ממאי דאישתנו\u0004 \u0005[ממה,\u0006 מנין לנו, \u0005שהשתנו],\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 קרבן אחד הם, ו\u0003הכי קאמר רחמנא\u0004 \u0005[כך אמרה התורה]:\u0006 \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 אתה להקריבו ב\u0003פר ושני אילים\u0004 — יכול הוא \u0003ליקרב\u0004 \u0005[שיקרב]\u0006 כך, ו\u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 אתה להקריבו ב\u0003שני פרים ואיל אחד\u0004 — יכול הוא \u0003ליקרב\u0004 \u0005[שיקרב]\u0006 כך! ומשיבים: \u0003מדאישתני\u0004 \u0005[מתוך שהשתנה]\u0006 לא רק מספרם של הקרבנות המנויים בספר ויקרא ואלה שבספר במדבר, אלא אף \u0003סדרן\u0004 (שכן סדר הקרבנות שבספר ויקרא הוא כבשים, פר, ואילים. ואילו זה שבספר במדבר הוא פרים, איל וכבשים) — \u0003שמע מינה אחריני נינהו\u0004 \u0005[למד מכאן\u0006 כי קרבנות \u0005אחרים הם].\u0006","שנינו במשנתנו שלדעת ר' עקיבא \u0003הלחם מעכב את\u0004 הבאתם של שני \u0003הכבשים\u0004 ואין הכבשים מעכבים את הלחם. ודנים בשיטה זו: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור שיטתו\u0005]\u0006 של \u0003ר' עקיבא?\u0004","— \u0003גמר\u0004 \u0005[למד]\u0006 את שיטתו זו מהיקש מקראות. שכן נאמר בפרשת \"אמור\" \"והניף הכהן אותם על לחם הבכורים תנופה לפני ה' על שני כבשים קדש יהיו לה' לכהן\" (ויקרא כג, כ), והדגשת הכתוב \"יהיו\" מלמדת שרק באופן זה צריך לנהוג. ואולם מן הכתוב אין זה ברור אם עיכוב זה מתייחס ללחם או לכבשים. לכך למדים אנו בגזירה שווה את פירוש המלה \u0003\"יהיו\"\u0004 שבפסוק זה \u0003מ\u0004המלה \u0003\"תהיינה\",\u0004 שבדין שתי הלחם (\"ממושבותיכם תביאו לחם תנופה שתים שני עשרונים סולת תהיינה...\". שם יז).","\u0003מה להלן\u0004 מתייחסים הדברים לשתי ה\u0003לחם\u0004 ולא לכבשים, \u0003אף כאן\u0004 מתייחסים הדברים לשתי ה\u0003לחם,\u0004 ולא לכבשים. ומכאן, שהלחם מעכב את הכבשים, ואולם הכבשים אינם מעכבים את הלחם.","ושואלים לצד השני: \u0003ובן ננס,\u0004 הסבור שהלחם אינו מעכב את הכבשים, ואילו הכבשים מעכבים את הלחם, מה מקור שיטתו? \u0003גמר\u0004 \u0005[למד]\u0006 את שיטתו זו מגזירה שווה של המלה \u0003\"יהיו\"\u0004 שבפסוקנו והמלה \u0003\"יהיו\"\u0004 הנאמרת בעניינם של שבעת הכבשים. \u0003מה להלן\u0004 (שם) מתייחסת המלה \"יהיו\" ל\u0003כבשים, אף כאן\u0004 היא מתייחסת ל\u0003כבשים,\u0004 ולא ללחם. ולכך סבור הוא כי הכבשים מעכבים את הלחם, ואילו הלחם אין מעכב את הכבשים.","ושואלים: \u0003ובן ננס נמי נילף\u0004 \u0005[גם כן שילמד]\u0006 כמו ר' עקיבא \u0003מ\u0004היקש המלים \"יהיו\" ו\u0003\"תהיינה\", מה להלן לחם, אף כאן לחם!\u0004 ומשיבים: לדעתו כאשר \u0003דנין\u0004 גזירה שווה צריך שיהיו המלים זהות, ולכן למדים \u0003\"יהיו\" מ\"יהיו\", ואין דנין \"יהיו\" מ\"תהיינה\",\u0004 שאין המילים שוות לגמרי.","ומקשים על כך: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה,\u0006 מה משנה הדבר\u0005]?\u0006 \u0003התנא דבי\u0004 \u0005[\u0006ו\u0005הרי\u0006 כבר \u0005שנה\u0006 החכם \u0005של בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל\u0004 גזירה שווה לענין נגעי בתים, שעיקרה הוא השוואת הכתוב \u0003\"ושב הכהן\u0004 ביום השביעי וראה והנה פשה הנגע בקירות הבית\" (שם יד, לט), והכתוב הדומה לו \u0003\"ובא הכהן\u0004 וראה והנה פשה הנגע בבית\" (שם מד), ודרש: \u0003זהו שיבה, זהו ביאה,\u0004 כלומר, אף שאין שוויון בין מילים אלו יש ללמוד מהן גזירה שווה, וכל שנאמר בענין אחד שייך גם לשני. ומתוך כך ניתן להסיק שאפילו כשקיים הבדל בין המילים, כיון שתוכנן זהה — דנים גזירה שווה, וכל שכן כאן שהמילים נבדלות רק בצורה הדקדוקית!","ומשיבים: אכן לפעמים למדים גזירה שווה ממילים שאינן זהות, ואולם \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 הם דווקא \u0003היכא דליכא דדמי ליה\u0004 \u0005[היכן שאין\u0006 מקרא אחר \u0005שדומה לו\u0006 בדיוק\u0005],\u0006 \u0003אבל היכא דאיכא דדמי ליה\u0004 \u0005[היכן שיש\u0006 מקרא אחר \u0005שדומה לו]\u0006 — \u0003מדדמי ליה ילפינן\u0004 \u0005[מ\u0006המקרא \u0005שדומה לו אנו לומדים].\u0006 ולכך יש ללמוד \"יהיו\" מ\"יהיו\", ולא \"יהיו\" מ\"תהיינה\".","ושואלים לצד השני: \u0003ור' עקיבא נמי לילף\u0004 \u0005[גם כן שילמד],\u0006 כדרך שלמד בן ננס את משמע המלה \u0003\"יהיו\" מ\u0004היקש למלה \u0003\"יהיו\"!\u0004 ומשיבים: ר' עקיבא סבור ש\u0003דנין\u0004 דינו של \u0003דבר ש\u0004הינו \u0003מתנה\u0004 (נתינה) \u0003לכהן\u0004 (כשתי הלחם הנאכלות לכהנים) \u0003מ\u0004דינו של \u0003דבר\u0004 אחר \u0003ש\u0004אף הוא \u0003מתנה לכהן\u0004 (כלחם וכבשי העצרת). \u0003לאפוקי הני\u0004 \u0005[להוציא\u0006 את \u0005אלה,\u0006 שבעת הכבשים\u0005]\u0006 ש\u0003עולות\u0004 הניתנות כולן למזבח \u0003נינהו\u0004 \u0005[הן],\u0006 ואינם מתנה לכהן.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר למקור שיטותיהם השונות של ר' עקיבא ובן ננס. שכן \u0003בקרא גופיה קא מיפלגי\u0004 \u0005[ב\u0006פירוש ה\u0005פסוק עצמו הם חלוקים,\u0006 מהו עניינו\u0005],\u0006 שאת הנאמר \u0003\"קדש יהיו לה' לכהן\" ר' עקיבא סבר\u0004 שיש לפרש: \u0003אי זהו דבר שכולו\u0004 ניתן \u0003לכהן? הוי אומר: זה לחם,\u0004 ומכאן שהכתוב \"יהיו\" מוסב על הלחם, שהוא המעכב את הכבשים.","\u0003ו\u0004אילו \u0003בן ננס\u0004 משיב: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"קדש יהיו לכהן\"?!\u0004 שאפשר היה אז לומר כהסברו של ר' עקיבא, והרי \u0003\"קדש יהיו לה' לכהן\" כתיב\u0004 \u0005[נאמר],\u0006 ומשמעות הכתוב ליתן חלק לה' וחלק לכהן, ו\u0003איזהו דבר שמקצתו לה' ומקצתו לכהן? הוי אומר: אלו כבשים\u0004 הקרבים לשלמים, שחלק מהם עולה על המזבח, וחלק אחר ניתן לכהנים לאכילה. ולכך הכתוב \"יהיו\" מתייחס לכבשים, ללמדנו שהם מעכבים את הלחם.","ושואלים: \u0003ור' עקיבא\u0004 מה הוא משיב על טענה זו? ומסבירים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"קדש יהיו לה' ולכהן\"?!\u0004 שאפשר היה לומר שכוונתו חלק לה' וחלק לכהנים, והרי \"קדש יהיו \u0003לה' לכהן\" כתיב\u0004 \u0005[נאמר],\u0006 אלא הכוונה היא שבתחילה ניתנים הם לה', ומאת ה' הם ניתנים לכהן. \u0003וכ\u0004דברי \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: קנאו השם\u0004 בתחילה, וחזר \u0003ונתנו לכהן.\u0004","במשנה נזכרה מחלוקת אם שני הלחם מעכבים את הכבשים או להיפך. ומוסיפים, שעל כך \u0003אמר ר' יוחנן: הכל מודים\u0004"],["\u0003שאם\u0004 כבר \u0003הוזקקו\u0004 (נוצרה זיקה) בין \u0003זה לזה\u0004 שהובאו שניהם יחד, ואחר כך אבד אחד מהם, הלחם או הכבשים — \u0003שמעכבין\u0004 הם \u0003זה את זה,\u0004 ושוב אי אפשר להקריב את זה שנותר, שנדחה מהקרבה אחר שאבד חבירו. \u0003ו\u0004מסביר ר' יוחנן: \u0003איזה\u0004 מעבודות הקרבן \u0003הוא\u0004 הקובע את ה\u0003זיקה שלהן?\u0004 ה\u0003שחיטה,\u0004 שאם היה לחם בשעת השחיטה — התקדשו בכך שניהם כאחד. ומעתה אם אבד אחד מהם — אף חבירו הריהו כאבוד, וילך לבית השריפה.","ועוד בענין זה של זיקת הלחם והכבשים מביאים מה ש\u0003אמר עולא\u0004 כי \u0003בעו\u0004 \u0005[שאלו,\u0006 עוררו בעיה\u0005]\u0006 חכמים \u0003במערבא\u0004 \u0005[בארץ ישראל]:\u0006 האם ה\u0003תנופה\u0004 הנעשית בכבשים קודם שחיטתם ובלחם \u0003עושה זיקה\u0004 בין הלחם והכבשים, ואם אבד אחד מהם נפסל חבירו בכך, \u0003או\u0004 מעשה התנופה עצמו עדיין \u0003אינו עושה זיקה\u0004 ביניהם?","ומקשים: מה בעיה היא זו, \u0003פשוט ליה\u0004 \u0005[פתור אותה]\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן,\u0004 שכן \u0003אמר ר' יוחנן\u0004 כי ה\u0003שחיטה עושה זיקה\u0004 בין הלחם והכבשים, ו\u0003מכלל\u0004 הדברים אתה למד כי מעשה ה\u0003תנופה\u0004 הקודם לשחיטה \u0003אינו עושה זיקה!\u0004","ודוחים: מדברי ר' יוחנן אי אפשר לפתור את הבעיה, שכן בדבריו אלה של \u0003ר' יוחנן גופא קא מיבעיא ליה\u0004 \u0005[עצמו נשאלה להם],\u0006 שבכך הסתפקו: האם \u0003מיפשט פשיטא ליה\u0004 \u0005[היה פשוט לו]\u0006 \u0003לר' יוחנן\u0004 שרק מעשה ה\u0003שחיטה\u0004 הוא ה\u0003עושה\u0004 את ה\u0003זיקה\u0004 שבין הלחם והכבשים, \u0003ו\u0004אילו מעשה ה\u0003תנופה\u0004 הקודם לו \u0003אינו עושה זיקה.\u0004 ומשום כך הזכיר ר' יוחנן בדבריו דווקא את מעשה השחיטה כמי שעושה זיקה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 במעשה ה\u0003שחיטה פשיטא ליה\u0004 \u0005[היה פשוט לו]\u0006 שעושה זיקה, \u0003ו\u0004אילו בענין מעשה ה\u0003תנופה מספקא ליה\u0004 \u0005[היה מסופק לו],\u0006 ולכך הזכיר בדבריו דווקא את השחיטה, שרק בה יש ודאות לענין הזיקה. ומסכמים כי לא נפתרה בעיה זו, ולכך \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהודה בר חנינא לרב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 \u0003והא כי כתיב\u0004 \u0005[והרי כאשר נאמר]\u0006 הכתוב בכבשים ובלחם \u0003\"קדש יהיו לה' לכהן\"\u0004 — \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003תנופה כתיב\u0004 \u0005[נאמר]\u0006 הדבר, \u0003ו\u0004בכל זאת \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בן ננס ור' עקיבא\u0004 מי הוא זה המעכב את חבירו, הרי שאין התנופה יוצרת זיקה בין שניהם!","השיב לו רב הונא בנו של רב יהושע לר' יהודה בר חנינא: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שמתוך שהפסוק מדבר אחר התנופה ראיה לכך שאין התנופה יוצרת זיקה בין שניהם, אלא השחיטה היא היוצרת זיקה זו, האם הפסוק הזה מדבר דווקא \u0003בתר\u0004 \u0005[אחר]\u0006 \u0003תנופה ולא בתר\u0004 \u0005[אחר]\u0006 \u0003שחיטה?!\u0004 והרי נאמר בו שניתנים הם לכהן, ואין נתינה זו אלא לאחר שחיטה, וכיצד אם כן נחלקו בן ננס ור' עקיבא בכתוב זה?","\u0003אלא\u0004 על כרחך \u0003מאי אית לך למימרא\u0004 \u0005[מה יש לך לומר]\u0006 בפירוש הכתוב \"יהיו לה' לכהן\", כי \u0003מעיקרא קאי\u0004 \u0005[מתחילה,\u0006 לראשיתו של הדבר הוא \u0005עומד],\u0006 ובשלב הקודם לשחיטה, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"קדש יהיו לה' לכהן\"? דבר שסופו\u0004 להינתן \u0003לכהן. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יתכן לומר שבשלב הקודם אף לתנופה הכתוב מדבר, וכוונתו לומר: \u0003דבר שסופו\u0004 להינתן \u0003לכהן.\u0004 ונותרה איפוא המסקנה כי בעיה בלתי פתורה היא האם אף התנופה יוצרת זיקה בין הלחם והכבשים.","למעלה הובאו דבריו של ר' יוחנן כי השחיטה עושה זיקה בין הלחם והכבשים. ושואלים על כך: \u0003ו\u0004האם ה\u0003שחטה עושה זיקה? ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא בדינם של לחמי התודה (הלחמים הבאים עם קרבן התודה), שאם \u0003עד שלא\u0004 (בטרם) \u0003שחטה\u0004 לבהמת קרבן התודה \u0003נפרס\u0004 (נחתך) אחד מ\u0003לחמה\u0004 ונפסלו בכך כל לחמי התודה — \u0003יביא לחם אחר ושוחט\u0004 את בהמת התודה.","ואולם אם \u0003מש\u0004 כבר \u0003שחטה נפרס לחמה,\u0004 ומעתה שוב אין אפשרות להביא לחמים אחרים תחת לחם זה (שהרי כבר נשחט הקרבן, ואין הלחמים מתקדשים אלא בשחיטתו של הקרבן) — \u0003הדם יזרק\u0004 על המזבח, \u0003והבשר יאכל, ו\u0004אולם \u0003ידי נדרו לא יצא, והלחם פסול.\u0004","ואם נפרס הלחם לאחר שכבר \u0003נזרק הדם\u0004 על המזבח, והרי לא נפסלו הלחמים בכך (שכן נפרס הלחם לאחר שכבר התקדש בשחיטה ונזרק הדם כדינו) — הריהו \u0003תורם\u0004 את ארבעת הלחמים הניתנים לכהן \u0003מן\u0004 הלחם \u0003השלם\u0004 ולא מן הלחם הפרוס, ותרומת ארבעת הלחמים הללו היא על כל הלחם, על השלם ו\u0003על הפרוס\u0004 שבהם.","ובדומה לשלושת האופנים הללו בלחם שנפרס, כן הוא בלחם שיצא אל מחוץ לחומת העיר ירושלים: שאם \u0003עד שלא\u0004 \u0003שחטה\u0004 לבהמת הקרבן \u0003יצא לחמה\u0004 אל מחוץ לחומה — לא נפסל בכך הלחם (שהרי טרם התקדש), ולכך \u0003מכניסה\u0004 חזרה פנימה, \u0003ושוחט\u0004 את בהמת הקרבן.","ואם \u0003מששחטה יצא לחמה\u0004 אל מחוץ לחומת ירושלים, ונפסל בכך הלחם — \u0003הדם יזרק\u0004 על המזבח, \u0003והבשר יאכל, ו\u0004אולם \u0003ידי נדרו לא יצא, והלחם פסול.\u0004 ואם יצא חלק מהלחם אל מחוץ לחומת ירושלים רק לאחר שכבר \u0003נזרק הדם\u0004 על המזבח, ונאסר בכך הלחם היוצא לאכילה — \u0003תורם\u0004 את ארבעת הלחמים הניתנים לכהן \u0003ממה\u0004 שנמצא עדיין \u0003בפנים\u0004 ומותר באכילה, ומתייחסת נתינה זו אף \u0003על\u0004 הלחמים \u0003שבחוץ.\u0004","וכמו כן בדומה לשלושת האופנים הללו בפריסת וביציאת הלחם, כן הוא בטומאת הלחם, שאם \u0003עד שלא שחטה נטמא לחמה\u0004 — \u0003מביא לחם אחר, ושוחט\u0004 את בהמת הקרבן. ואם \u0003מששחטה נטמא לחמה\u0004 — \u0003הדם יזרק, והבשר יאכל, ו\u0004אף \u0003ידי נדרו יצא\u0004 בכך, וטעם הדבר: לפי \u0003שהציץ מרצה על הטמא,\u0004 אבל \u0003הלחם\u0004 עצמו שנטמא הריהו \u0003פסול,\u0004 שאמנם הציץ מרצה אבל אינו עושה אותו טהור.","ואם נטמא הלחם לאחר שכבר \u0003נזרק הדם\u0004 — \u0003תורם\u0004 את ארבעת הלחמים הניתנים לכהן \u0003מן\u0004 הלחם \u0003הטהור\u0004 ומתייחסת נתינה זו אף \u0003על\u0004 הלחם \u0003הטמא. ו\u0004מעתה יש לשאול:","\u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר ש\u0003שחיטה עושה זיקה\u0004 בין הזבח והכבשים (ובדומה לכך, בין קרבן התודה ולחמיו), ולכך אם אבד האחד — אף חבירו נפסל, ועובר לבית השריפה. אם כן, נאמר כך גם בדינם של קרבן התודה ולחמיו, ש\u0003כיון\u0004 שכבר \u0003הוזקקו זה לזה\u0004 הקרבן ולחמיו \u0003בשחיטה,\u0004 אם כן כאשר \u0003איפסיל ליה\u0004 \u0005[נפסל לו]\u0006 ה\u0003לחם\u0004 (שנפרס או שיצא או שנטמא) לאחר השחיטה — \u0003תיפסל נמי\u0004 \u0005[גם כן]\u0006 ה\u0003תודה\u0004 עמו, שהרי הוזקקו זה לזה ולא ייזרק דמה ואף בשרה לא ייאכל. ואילו בברייתא שנינו שאין הקרבן נפסל!","ומשיבים: אין להקשות מדין התודה, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 הוא קרבן ה\u0003תודה, דרחמנא קרייה\u0004 \u0005[שהתורה קוראת לו]\u0006 \u0003\"שלמים\"\u0004 (\"זבח תודת שלמיו\". ויקרא ז, יג), לומר שדין התודה כדין השלמים: \u0003מה שלמים קרבים בלא לחם, אף תודה\u0004 יש והיא \u0003קרבה\u0004 גם \u0003בלא לחם,\u0004 שאינה נפסלת להקרבה אם נפסל לחמה.","ועוד באותו ענין, \u0003אמר ר' ירמיה: אם תמצא לומר\u0004 בפתרון הבעיה של חכמי ארץ ישראל, כי אכן ה\u0003תנופה עושה זיקה\u0004 בין הלחם והכבשים, הרי אם כן אם \u0003אבד הלחם,\u0004"],["אחר התנופה — \u0003אבדו\u0004 בכך גם ה\u0003כבשים\u0004 ויוצאים לבית השריפה. וכן אם \u0003אבדו\u0004 ה\u0003כבשים\u0004 אחר התנופה — \u0003אבד\u0004 בכך גם \u0003הלחם,\u0004 שהרי הוקבעו זה עם זה בתנופה.","\u0003ו\u0004אולם \u0003אם תמצא לומר\u0004 בפתרון הבעיה של חכמי ארץ ישראל, כי ה\u0003תנופה אינה עושה זיקה\u0004 בין הלחם והכבשים, יש לדון בשאלה זו: אם \u0003הביא לחם וכבשים, והונפו\u0004 כדינם, \u0003ו\u0004אחר כך \u0003אבד הלחם,\u0004 והלך \u0003והביא לחם אחר\u0004 במקום הלחם שאבד — האם \u0003אותו הלחם\u0004 האחר \u0003טעון תנופה\u0004 עם הכבשים, שהרי לחם זה לא הונף, \u0003או\u0004 שמא \u0003אינו טעון תנופה,\u0004 שהרי הכבשים הבאים עמו כבר הונפו עם לחם, ועיקר דין התנופה נאמר בהם (ככתוב \"והניף אותם הכהן\". ויקרא כג, כ).","ומסביר ר' ירמיה את הבעיה: אם \u0003אבדו\u0004 ה\u0003כבשים\u0004 לאחר התנופה, והביא במקומם כבשים אחרים — \u0003לא תיבעי\u0004 \u0005[לא תישאל]\u0006 \u0003לך\u0004 אם צריכים להניף את הכבשים הללו עם הלחם, ש\u0003ודאי\u0004 שבאופן זה \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003תנופה\u0004 חדשה של הכבשים עם הלחם. כי עיקר תנופה אמורה בכבשים, ובכבשים הללו לא התקיימה התנופה. ואולם \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה, כאמור, במקרה ש\u0003אבד הלחם\u0004 לאחר התנופה.","\u0003ו\u0004עוד מסביר ר' ירמיה את הבעיה: \u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003בן ננס\u0004 הסבור כי הכבשים מעכבים את הלחם ואין הלחם מעכב את הכבשים — \u0003לא תיבעי\u0004 \u0005[לא תישאל]\u0006 \u0003לך\u0004 בעיה זו שהרי לשיטתו \u0003אמר\u0004 כי ה\u0003כבשים\u0004 הם ה\u0003עיקר,\u0004 ולא הלחם, ובמקרה שלפנינו, כיון שהונפו כבר הכבשים — שוב אין צורך להניף את הלחם החדש. ואולם \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה \u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 כי הלחם מעכב את הכבשים ואין הכבשים מעכבים את הלחם, שלדעתו ה\u0003לחם\u0004 הוא ה\u0003עיקר.\u0004 ומעתה יש לשאול \u0003מאי\u0004 \u0005[מה]\u0006 הדין בענין הנפתו של הלחם המובא עתה.","וצדדי הבעיה: מצד אחד יש לומר כי \u0003כיון\u0004 שה\u0003לחם\u0004 הוא ה\u0003עיקר,\u0004 והרי לחם זה לא הונף — \u0003בעי\u0004 \u0005[צריך]\u0006 איפוא להניף \u0003תנופה\u0004 חדשה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003כיון\u0004 שה\u0003מתירין דידיה\u0004 \u0005[שלו,\u0006 של הלחם\u0005]\u0006 ה\u0003כבשים נינהו\u0004 \u0005[הם],\u0006 וכיון שהם כבר הונפו — \u0003לא צריך\u0004 שוב \u0003תנופה\u0004 נוספת בלחם זה? ומסכמים כי בעיה זו לא נפתרה, ולכך \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנתנו דינם של שני כבשי עצרת הבאים לשלמים עם שתי הלחם, שמקדשים את הלחם ומעכבים אותו. ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא\u0004 בשאלה: \u0003מאי שנא\u0004 \u0005[במה שונים]\u0006 \u0003שני\u0004 ה\u0003כבשים\u0004 הבאים בעצרת לשלמים עם הלחם \u0003דמקדשי\u0004 \u0005[שמקדשים]\u0006 את שתי ה\u0003לחם ומעכבי\u0004 \u0005[ומעכבים]\u0006 אותו, שכיון שנשחטו הכבשים (לשיטת ר' יוחנן), אם לא הביאו אותם — אף אין מביאים את הלחם. \u0003ומאי שנא\u0004 \u0005[ובמה שונים]\u0006 \u0003שבעה כבשים ופר\u0004 אחד \u0003ו\u0004שני \u0003אילים\u0004 הבאים בעצרת לעולה למוספים, ש\u0003לא מקדשי\u0004 \u0005[לא מקדשים]\u0006 את ה\u0003לחם ולא מעכבי\u0004 \u0005[ולא מעכבים]\u0006 אותו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא בהסבר הדבר: דווקא שני הכבשים מקדשים את הלחם, ומעכבים את הבאתו בהיעדרם, \u0003הואיל והוזקקו\u0004 (נוצרה זיקה, תלות) בין \u0003זה לזה ב\u0004שעת ה\u0003תנופה\u0004 שלהם. מה שאין כן בקרבנות המוספים, שלא הוזקקו זה לזה. ומקשים על הסבר זה: \u0003והרי\u0004 רואים אנו בדין קרבן \u0003תודה\u0004 ולחמיו, אף ש\u0003לא הוזקקו\u0004 התודה והלחמים \u0003זה לזה בתנופה\u0004 (שאין בהם דין תנופה), \u0003ו\u0004בכל זאת שחיטת התודה \u0003מקדשא\u0004 \u0005[מקדשת]\u0006 את הלחמים, \u0003ומעכבא\u0004 \u0005[ומעכבת]\u0006 את הבאתם. הרי שהטעם לקידוש ועיכוב הלחם דווקא על ידי שני הכבשים, אינו הזיקה הנוצרת בשל ההנפה!","\u0003אלא\u0004 צריך לומר שהטעם שדווקא שני הכבשים מקדשים ומעכבים את שתי הלחם הוא, שדינם של שני הכבשים הריהו \u0003כ\u0004דינו של קרבן ה\u0003תודה, מה\u0004 ה\u0003תודה\u0004 הריהי קרבן \u0003שלמים, אף הכא נמי\u0004 \u0005[כאן,\u0006 שני הכשבים, \u0005גם כן]\u0006 הריהם קרבן \u0003שלמים.\u0004 וכשם שקרבן התודה מקדש ומעכב את לחמיו, כך הוא גם בשני כבשי העצרת, מה שאין כן בשאר קרבנות העצרת.","ודוחים אף הסבר זה: \u0003מי דמי\u0004 \u0005[האם דומים]\u0006 הם שני כבשי העצרת לקרבן התודה? והלא \u0003התם\u0004 \u0005[שם,\u0006 בקרבן תודה\u0005]\u0006 — \u0003ליכא\u0004 \u0005[אין]\u0006 עוד \u0003זבחים אחריני בהדיה\u0004 \u0005[אחרים אתו],\u0006 ולכך הריהו מקדש ומעכב את לחמיו. ואילו \u0003הכא\u0004 \u0005[כאן,\u0006 בקרבנות העצרת\u0005]\u0006 — \u0003דאיכא\u0004 \u0005[שיש]\u0006 מלבד שני הכבשים הבאים לשלמים, גם \u0003זבחים אחריני בהדיה\u0004 \u0005[אחרים אתו],\u0006 יש מקום לומר כי \u0003ליקדשו הני והני\u0004 \u0005[שיקדשו\u0006 את הלחם, קרבנות \u0005אלה ואלה]\u0006 ולא שני הכבשים בלבד!","\u0003אלא\u0004 צריך לומר בטעם הדבר שדווקא שני הכבשים הם המקדשים ומעכבים את שתי הלחם, שכן דינם של הכבשים הריהו \u0003כ\u0004דינו של קרבן \u0003איל נזיר\u0004 המובא בהשלמת ימי נזירותו של הנזיר כקרבן שלמים (בנוסף לכבש אחד לקרבן עולה וכבשה אחת לקרבן חטאת וללחמי נזיר המובאים על ידו באותו יום. במדבר ו, יד— טו). \u0003מה איל נזיר\u0004 — \u0003אף על גב דאיכא\u0004 \u0005[אף על פי שיש]\u0006 \u0003זבחים אחריני\u0004 \u0005[אחרים]\u0006 הבאים אתו, מכל מקום דווקא הוא, קרבן ה\u0003שלמים הוא דמקדשי\u0004 \u0005[שמקדשים]\u0006 את לחמי הנזיר, ואילו \u0003מידי אחרינא\u0004 \u0005[דבר אחר,\u0006 שאר הקרבנות\u0005]\u0006 — \u0003לא\u0004 מקדשים את לחמי הנזיר, \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בלחמי העצרת, \u0005גם כן]\u0006 — \u0003לא שנא\u0004 \u0005[אין\u0006 דינו \u0005שונה],\u0006 והשלמים הם המקדשים את הלחם, ולא שאר הקרבנות.","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם,\u0006 בקרבנות הנזיר, \u0005מנין לנו]\u0006 שדווקא איל השלמים הוא המקדש את לחמי הנזיר, ולא שאר הקרבנות? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בקרבנות הנזיר \u0003\"ואת האיל יעשה זבח שלמים לה' על סל המצות\"\u0004 (שם יז) — הרי לשון זו \"על סל המצות\" \u0003מלמד שהסל\u0004 של לחמי הנזיר הריהו \u0003בא\u0004 כ\u0003חובה ל\u0004קרבן ה\u0003איל\u0004 שהוא קרבן שלמים, \u0003ושחיטת\u0004 ה\u0003איל\u0004 לקרבן שלמים היא ה\u0003מקדשן\u0004 ללחמים אלה. ו\u0003לפיכך\u0004 אם היתה שחיטתו פסולה וכגון ש\u0003שחטו\u0004 לאיל \u0003שלא לשמו\u0004 (לשם שלמים) — \u0003לא קדשו הלחם.\u0004","שנינו במשנתנו כי לדעת ר' עקיבא אין הכבשים מעכבים את הלחם, ולכך אם אין כבשים — באים שתי הלחם כשלעצמם. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שתי הלחם הבאות בפני עצמן\u0004 — \u0003יונפו, ו\u0004אולם לאחר מכן \u0003תעובר צורתן\u0004 (ייפסלו) על ידי המתנת לילה, שייפסלו בלינה, \u0003ויצאו לבית השריפה,\u0004 כקדשים שנפסלו.","ותוהים: \u0003מה נפשך\u0004 \u0005[מה רצונך]?\u0006 כלומר, בכל צד הדבר קשה, שכן \u0003אי\u0004 \u0005[אם]\u0006 שתי הלחם \u0003לאכילה אתיין\u0004 \u0005[באות]\u0006 ומונפות — \u0003ליכלינהו\u0004 \u0005[שיאכלו אותן],\u0006 ולא ישרפן! ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003לשריפה אתיין\u0004 \u0005[הן באות]\u0006 בסופו של דבר — \u0003לשרפינהו לאלתר\u0004 \u0005[שישרוף אותן מיד],\u0006 ו\u0003למה להו\u0004 \u0005[להן]\u0006 להמתין כדי לגרום להן \u0003עיבור צורה?\u0004","\u0003אמר רבה: לעולם לאכילה אתיין\u0004 \u0005[באות],\u0006 ואולם גזרו חכמים \u0003גזירה\u0004 שלא תיאכלנה מתוך החשש \u0003שמא יזדמנו להן כבשים לשנה הבאה, ויאמרו:\u0004 וכי \u0003אשתקד\u0004 (בשנה שעברה), בחג השבועות, \u0003לא אכלנו\u0004 את שתי ה\u0003לחם בלא\u0004 שהובאו עמו שני ה\u0003כבשים? עכשיו נמי ניכול\u0004 \u0005[גם כן נאכל]\u0006 את שתי הלחם בלא שיובאו איתם כבשי העצרת.","\u0003ואינהו לא ידעי\u0004 \u0005[והם לא יודעים]\u0006 כי טעם הדבר שאכלו בשנה שעברה את שתי הלחם אף שלא קרבו כבשי העצרת הוא משום ש\u0003אשתקד לא הוו\u0004 \u0005[לא היו]\u0006 להם \u0003כבשים,\u0004 ולכך \u0003אינהו שריין נפשייהו\u0004 \u0005[הם,\u0006 שתי הלחם, \u0005מתירים\u0006 את \u0005עצמם\u0006 לאכילה\u0005],\u0006 ואולם \u0003השתא דאיכא\u0004 \u0005[עכשיו,\u0006 בשנה זו, \u0005שיש]\u0006 בה \u0003כבשים\u0004 — ה\u0003כבשים הוא דשרו להו\u0004 \u0005[שמתירים אותם,\u0006 את שתי הלחם באכילה\u0005],\u0006 ואין שתי הלחם מתירים את עצמם.","\u0003אמר רבה: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה\u0006 הלכה\u0005]?\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אמר ר' יהודה\u0004 שכך \u0003העיד בן בוכרי ביבנה\u0004 לפני חכמי בית הועד בשם חכמים: אף שאין הכהנים חייבים במחצית השקל, מכל מקום \u0003כל כהן ששוקל\u0004 (שמביא את מחצית השקל) — \u0003אינו חוטא\u0004 בכך.","\u0003אמר לו רבן יוחנן בן זכאי: לא כי\u0004 (כך) הוא, \u0003אלא כל כהן שאינו שוקל\u0004 — \u0003חוטא\u0004 הוא. \u0003אלא שהכהנים דורשין מקרא זה\u0004 המובא להלן \u0003ל\u0004טובת \u0003עצמן,\u0004 כדי להיפטר ממחצית השקל, שכן כלל הוא בתורה שמנחת כהן אינה נאכלת אלא נשרפת, שכן נאמר:","\u0003\"וכל מנחת כהן כליל תהיה לא תאכל\"\u0004 (ויקרא ו, טז). ולכך הם טוענים: \u0003הואיל ו\u0004מנחת ה\u0003עומר ושתי הלחם ולחם הפנים\u0004 גם \u0003שלנו הן,\u0004 שהרי אנו חייבים בשקלים שמהם נקנים כל קרבנות הציבור ובכלל זה גם המנחות הללו, \u0003היאך\u0004 אם כן הם \u0003נאכלין\u0004 על ידינו?!","ודן רבה בדברי המשנה הללו: יש לברר את האמור בדרשתם של הכהנים: \u0003הני\u0004 \u0005[אותם]\u0006 \u0003שתי הלחם היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 הדבר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003ב\u0004זמן שהן \u0003באות עם\u0004 כבשי \u0003הזבח\u0004 — מדוע התפלאו הכהנים על אכילתם של שתי הלחם, \u0003אטו\u0004 \u0005[וכי]\u0006 קרבן \u0003תודה ולחמה מי\u0004 \u0005[האם]\u0006 \u0003לא\u0004 תיתכן אפשרות ש\u0003מנדבי\u0004 \u0005[מנדבים]\u0006 אותם \u0003כהנים, ואכלי להו\u0004 \u0005[ואוכלים אותם]?\u0006 ואם כן, במה שונים שתי הלחם מלחמי תודה!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר פה \u0003ב\u0004שתי הלחם ה\u0003באות בפני עצמן, וקתני\u0004 \u0005[ושנה]\u0006 בהן: \u0003היאך הן נאכלין\u0004 — \u0003אלמא\u0004 \u0005[מכאן]\u0006 נלמד שבעיקרו של דין \u0003לאכילה\u0004 הן \u0003אתיין\u0004 \u0005[באות],\u0006 ואולם חכמים גזרו בהן שלא לאוכלן, ולכך הן צריכות לעיבור צורתן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה בדחייה: \u0003לעולם\u0004 תפרש שמדובר במשנה זו \u0003ב\u0004שתי הלחם ה\u0003באות עם הזבח, ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך מתודה ולחמה\u0004 שנאכלות לכהנים, אף כשכהנים הם שנדבום — אין זו קושיה, שכן \u0003לחמי תודה לא איקרו\u0004 \u0005[לא נקראו]\u0006 \u0003\"מנחה\",\u0004 ולכך יכולים הכהנים לאוכלם, שהרי דין שריפה לא נאמר אלא במנחה של כהנים. בעוד ש\u0003שתי הלחם איקרו\u0004 \u0005[נקראו]\u0006 \u0003\"מנחה\", ש\u0004כן \u0003נאמר\u0004 בהם \"וביום הביכורים \u0003בהקריבכם מנחה חדשה לה'\u0004 בשבועותיכם...\" (במדבר כח, כו).","\u0003רב יוסף אמר\u0004 הסבר אחר: \u0003לעולם\u0004 עיקר דינן הוא ש\u0003לשריפה אתיין\u0004 \u0005[באות],\u0006 \u0003והיינו טעמא\u0004 \u0005[ו\u0006אולם \u0005זהו הטעם]\u0006 ש\u0003לא שרפינן\u0004 \u0005[לא שורפים אנו אותן]\u0006 מייד (וכדרך שהקשו למעלה) — \u0003לפי שאין שורפין קדשים\u0004 שנפסלו (כגון נותר או טמא) \u0003ביום טוב,\u0004 ולכך אי אפשר לשרוף את שתי הלחם הללו ביום הבאתן, בחג השבועות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף בשאלה על דבריו: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 שריפתם של שתי הלחם לשריפתם של שאר קדשים הנפסלים, שאין שורפים מייד את שתי הלחם הבאות לבדן?! והלא \u0003התם\u0004 \u0005[שם,\u0006 בשאר קדשים הנשרפים\u0005]\u0006 — \u0003לאו\u0004 \u0005[אין]\u0006 \u0003מצותן\u0004 מלכתחילה \u0003בכך\u0004 (בשריפה), שהרי מעיקרם באו לאכילה, אלא שאירע בהם פסול, ומשום כך אין הם נשרפים ביום טוב. מה שאין כן \u0003הכא\u0004 \u0005[כאן,\u0006 בשתי הלחם הבאות לבדן\u0005],\u0006 שלדעתך \u0003מצותן\u0004 מעיקרה היא \u0003בכך\u0004 (בשריפה) — \u0003לישרפינהו\u0004 \u0005[שישרוף אותן]\u0006 מיד ביום טוב, ואין צורך להמתין שיעבור עליהם לילה. \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 ב\u0003פר ושעיר של יום הכיפורים\u0004 שמצוותן מלכתחילה היא בשריפה, ולכן הם נשרפים בו ביום!","\u0003אלא אמר רב יוסף\u0004 טעם אחר מדוע אין שתי הלחם הבאות לעצמם נשרפות מייד, אלא למחרת: \u0003גזירה\u0004 היא שגזרו חכמים שלא לשורפן מיד, \u0003שמא יזדמנו להם כבשים לאחר מכאן\u0004 באותו היום, ויונפו איתם הלחמים וייאכלו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף בדחיית דבריו אלה: \u0003תינח\u0004 \u0005[תנוח,\u0006 מיושבת בכך השאלה\u0005]\u0006 מדוע אין הם נשרפים ביום טוב ב\u0003כל\u0004 ה\u0003זמן\u0004 שבו עדיין נוהגת \u0003הקרבתם\u0004 (עד להקרבתו של תמיד של בין הערביים), ואולם \u0003לבתר הכי\u0004 \u0005[אחר כך],\u0006 כשכבר נגמר זמן הקרבתם — \u0003לשרפינהו\u0004 \u0005[שישרוף אותם]\u0006 מיד ולא ימתין למחרת! השיב לו רב יוסף: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003\"תעובר צורתן\" נמי דקתני\u0004 \u0005[גם כן ששנה\u0006 במשנה\u0005]?\u0006 — \u0003צורת הקרבתם,\u0004 ובאמת הריהם נשרפים לאחר שהסתיים זמן הקרבתם.","\u0003רבא אמר\u0004 הסבר אחר בטעם דינן של שתי הלחם הבאות לעצמן: מעיקר הדין \u0003לאכילה אתיין\u0004 \u0005[\u0006הן \u0005באות],\u0006 \u0003ו\u0004אולם גזרו בהן חכמים \u0003גזירה\u0004 שלא תיאכלנה. וטעמה של גזירה זו: \u0003משום\u0004 מה שאמר \u0003רבה\u0004 שחששו שאף בשנה הבאה יבואו לאכול את שתי הלחם הבאות לעצמן, גם כשיימצאו להם כבשים באותה שנה, \u0003ו\u0004אולם מקורו של ההסבר הזה הוא \u0003לאו מטעמיה\u0004 \u0005[אינו מהטעם,\u0006 מהמקור שהביא רבה\u0005],\u0006 \u0003אלא\u0004 \u0003מקרא\u0004 \u0005[מהמקרא].\u0006","\u0003ואמר רבא\u0004 בהסבר שיטתו זו: \u0003מנא אמינא לה\u0004 \u0005[מנין,\u0006 מאיזה כתוב, אני אומר אותה, את מקורה של הלכה זו\u0005]?\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדינם של שתי הלחם: \u0003\"ממושבתיכם תביאו לחם תנופה\u0004 שתים שני עשרונים סולת תהיינה חמץ תאפינה \u0003בכורים לה' \"\u0004(ויקרא כג, יז). וקרא אותם הכתוב \"ביכורים\", ללמדנו: \u0003מה בכורים\u0004 — \u0003בפני עצמן\u0004 הם באים, \u0003אף שתי הלחם\u0004 — יש (כאשר לא נמצאו להם כבשים) והם באים \u0003בפני עצמן. ו\u0004עוד נלמד \u0003מינה\u0004 \u0005[ממנה,\u0006 מהשוואה זו לביכורים\u0005]:\u0006 \u0003מה בכורים\u0004 — באים \u0003לאכילה, אף שתי הלחם נמי\u0004 \u0005[גם כן]\u0006 — באים \u0003לאכילה.\u0004"],["ומביאים עוד מדברי חכמים בדינם של שני כבשי העצרת ושתי הלחם הבאים בחג השבועות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: שני \u0003כבשי\u0004 ה\u0003עצרת אין מקדשין את\u0004 שתי \u0003הלחם אלא בשחיטה\u0004 של הכבשים וזריקת דמם על המזבח.","ומסבירים \u0003כיצד\u0004 — אם \u0003שחטן\u0004 את כבשי העצרת \u0003לשמן,\u0004 ולאחר מכן עמד \u0003וזרק\u0004 את \u0003דמן\u0004 על המזבח \u0003לשמן\u0004 — הרי \u0003קדש\u0004 בכך \u0003הלחם,\u0004 ומותר באכילה. \u0003שחטן שלא לשמן וזרק\u0004 את \u0003דמן שלא לשמן\u0004 — \u0003לא קדש\u0004 בכך \u0003הלחם. שחטן\u0004 \u0003לשמן ו\u0004אולם \u0003זרק\u0004 את \u0003דמן שלא לשמן\u0004 — \u0003הלחם קדוש ואינו קדוש,\u0004 אלו \u0003דברי רבי.\u0004 ואילו \u0003ר' אלעזר בר' שמעון אומר: לעולם\u0004 (בכל מקרה) הלחם \u0003אינו קדוש עד שישחוט\u0004 אותם \u0003לשמן ויזרוק\u0004 את \u0003דמן לשמן.\u0004","ומבררים את שיטותיהם של רבי ור' אלעזר בר' שמעון: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור שיטתו\u0005]\u0006 של \u0003רבי\u0004 הסבור ששחיטת הכבשים בלבד היא המקדשת את הלחם?","— \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 באיל הנזיר המובא ביום מלאת ימי נזירותו \u0003\"ואת האיל יעשה זבח שלמים לה' על סל המצות\"\u0004 (במדבר ו, יז), ומכתוב זה למדים כי עשיית הזבח (שחיטה) מועילה אף ללחמים הבאים עם הקרבן (\"על סל המצות\"), ו\u0003למימרא\u0004 \u0005[\u0006ו\u0005לומר]\u0006 לנו מכאן כי ה\u0003שחיטה מקדשא\u0004 \u0005[\u0006היא ה\u0005מקדשת]\u0006 את הלחם. וכן שחיטת כבשי העצרת מקדשת את שתי הלחם הבא עמם, שכן נלמד דין קדושת שתי הלחם מדין לחמי נזיר.","\u0003ו\u0004אילו \u0003ר' אלעזר בר' שמעון\u0004 הסבור שהשחיטה והזריקה גם יחד הן המקדשות, מאין הוא למד את שיטתו זו? — מן הנאמר בכתוב זה \"ואת האיל \u0003יעשה\"\u0004 — להורות שאין הלחמים מתקדשים אלא \u0003עד שיעשה\u0004 באיל את \u0003כל עשיותיו,\u0004 השחיטה והזריקה.","ושואלים: \u0003ורבי נמי הכתיב\u0004 \u0005[גם כן הרי נאמר]\u0006 \u0003\"יעשה\",\u0004 שמשמע ממנו שאין הלחם מתקדש עד שתיעשנה כל עשיותיו של האיל ובכלל זה הזריקה? והשיב רבי: \u0003אי כתיב\u0004 \u0005[אם היה כתוב]\u0006 \u0003\"זבח יעשה\"\u0004 — הייתי \u0003אומר\u0004 \u0003כדקאמרת\u0004 \u0005[כמו שאתה אומר],\u0006 שמשמעות הכתוב שישחט ויעשה פעולה נוספת, שהיא הזריקה (\"זבח יעשה\") על מנת שיתקדש הלחם. ואולם \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 בכתוב זה \u0003\"יעשה זבח\"\u0004 — משמע הדברים: \u0003במה\u0004 (מה) \u0003יעשה\u0004 כדי שתחול קדושה על הלחם? — \u0003בזביחה.\u0004","ושואלים לצד האחר: \u0003ור' אלעזר בר' שמעון, הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"זבח\"\u0004 שמשמע ממנו כי השחיטה כשלעצמה מקדשת מקדשת את הלחם? והשיב ר' אלעזר בר' שמעון: הפסוק \u0003ההוא\u0004 \u0005[אותו]\u0006 הכתוב \"זבח שלמים לה' על סל המצות\" \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004לימוד אחר, וכמו שאמר \u0003ר' יוחנן,\u0004 שכן \u0003אמר ר' יוחנן: הכל מודים,\u0004 ואף ר' אלעזר בר' שמעון הסבור שאין השחיטה כשלעצמה מקדשת את הלחם, \u0003שצריך שיהא לחם בשעת שחיטה.\u0004","שנינו בברייתא שלשיטת רבי, אם נשחט איל הנזיר לשמו ואולם דמו נזרק שלא לשמו, הרי הלחם \"קדוש ואינו קדוש\". ובענין זה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קדוש ואינו קדוש\"? אביי אמר:\u0004 הלחם אמנם נעשה \u0003קדוש\u0004 קדושה גמורה בשחיטה זו, \u0003ו\u0004אולם \u0003הוא\u0004 \u0003אינו גמור\u0004 בקדושתו. \u0003רבא אמר:\u0004 הלחם אמנם נעשה \u0003קדוש\u0004 קדושה גמורה בשחיטה זו, \u0003ו\u0004אולם הוא \u0003אינו ניתר\u0004 על ידה לאכילה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 הבדל הלכתי יש \u0005ביניהם\u0006\u0005],\u0006 בין אביי ורבא, שהרי הכל מודים שאין הלחם מותר לאכילה בשחיטה זו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל \u0003ל\u0004ענין \u0003מיתפס\u0004 \u0005[התפסה,\u0006 חלות קדושה\u0005]\u0006 על \u0003דמי\u0004 \u0003פדיונו\u0004 של לחם זה, ש\u0003ל\u0004שיטת \u0003אביי\u0004 האומר שאין הלחם קדוש קדושה גמורה — גם \u0003לא תפיס\u0004 \u0005[לא תופס,\u0006 חלה\u0005]\u0006 קדושה על דמי \u0003פדיונו.\u0004 ואילו \u0003ל\u0004שיטת \u0003רבא\u0004 האומר שהלחם קדוש קדושה גמורה (אלא שאינו מותר באכילה) — \u0003תפיס\u0004 \u0005[תופס]\u0006 דין קדושה על דמי \u0003פדיונו.\u0004","ומקשים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 \u0003ל\u0004שיטת \u0003רבא\u0004 האומר בפירוש דברי רבי שהתקדש הלחם בקדושה גמורה, \u0003היינו\u0004 \u0005[זהו]\u0006 ההבדל \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003בין רבי לר' אלעזר בר' שמעון. אלא ל\u0004שיטת \u0003אביי\u0004 האומר שלדברי רבי לא התקדש הלחם קדושה גמורה, \u0003מאי איכא\u0004 \u0005[מה\u0006 ההבדל להלכה ש\u0005יש]\u0006 \u0003בין רבי לר' אלעזר בר' שמעון?\u0004","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל \u0003ל\u0004ענין \u0003איפסולי\u0004 \u0005[שיפסל]\u0006 הלחם \u0003ביוצא\u0004 מן העזרה לאחר שחיטה. שכן לדעת רבי הסבור שהתקדש הלחם — נפסל הלחם ביציאתו. ואילו לדעת ר' אלעזר בר' שמעון הסבור שלא קידשה השחיטה את הלחם — לא נפסל הלחם ביציאתו זו (שהרי עדיין לא התקדש).","ועוד בענין מחלוקתם של רבי ור' אלעזר בר' שמעון בדין קדושת שתי הלחם בשחיטת ובזריקת כבשי העצרת, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' שמואל בר רב יצחק מר' חייא בר אבא: כבשי עצרת ששחטן לשמן, ו\u0004אולם \u0003זרק\u0004 את \u0003דמן שלא לשמן\u0004 — \u0003אותו הלחם מהו\u0004 דינו \u0003באכילה?\u0004","ושואלים: \u0003אליבא דמאן\u0004 \u0005[לפי\u0006 שיטתו \u0005של מי]\u0006 הועלתה בעיה זו? שכן \u0003אי\u0004 \u0005[אם]\u0006 הועלתה הבעיה \u0003אליבא\u0004 \u0005[לפי\u0006 שיטתו\u0005]\u0006 של \u0003ר' אלעזר בר' שמעון\u0004 — אין לבעיה זו מקום, שכן \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' אלעזר בר' שמעון כי \u0003זריקה היא דמקדשא\u0004 \u0005[שמקדשת]\u0006 את הלחם, ואם לא נזרק הדם לשמו, ברור שלא התקדשו הלחמים, ואין היתר לאוכלם. ו\u0003אי\u0004 \u0005[אם]\u0006 הועלתה הבעיה \u0003אליבא\u0004 \u0005[לפי\u0006 שיטתו\u0005]\u0006 של \u0003רבי\u0004 — גם כן אין מקום לבעיה זו, שהרי \u0003בין ל\u0004הסברו של \u0003אביי\u0004 את דברי רבי (האומר שבמקרה זה הלחם הריהו \"קדוש ואינו קדוש\"), ו\u0003בין ל\u0004הסברו של \u0003רבא\u0004 — הלחם הריהו אמנם \u0003קדוש ו\u0004אולם \u0003אינו ניתר\u0004 באכילה \u0003הוא!\u0004","\u0003אלא\u0004 צריך לומר שהבעיה \u0003היא\u0004 \u0003אליבא דהאי תנא\u0004 \u0005[לפי\u0006 שיטתו \u0005של תנא זה],\u0006 \u0003דתני אבוה\u0004 \u0005[ש\u0006כן \u0005שנה אביו]\u0006 של \u0003ר' ירמיה בר אבא\u0004 ברייתא זו: \u0003שתי הלחם שיצאו\u0004 אל מחוץ לעזרה \u0003בין\u0004 ה\u0003שחיטה\u0004 של הכבשים \u0003לזריקה\u0004 של דמם, \u0003וזרק\u0004 הכהן את \u0003דמן של\u0004 ה\u0003כבשים\u0004 במחשבה לאכול את הלחם ואת הכבשים \u0003חוץ\u0004 (מעבר) \u0003לזמנן\u0004 המותר, ובכך נתפגלו הכבשים ואסורים באכילה. ואולם נחלקו חכמים בדינו של הלחם. ש\u0003ר' אליעזר אומר\u0004 כי \u0003אין בלחם משום\u0004 איסור \u0003פיגול,\u0004 ואילו \u0003ר' עקיבא אומר\u0004 כי \u0003יש\u0004 אף \u0003בלחם,\u0004 ולא רק בכבשים, \u0003משום\u0004 איסור \u0003פיגול.\u0004","ובהסבר מחלוקתם זו של ר' אליעזר ור' עקיבא \u0003אמר רב ששת\u0004 כי \u0003הני תנאי\u0004 \u0005[אלה התנאים],\u0006 הן ר' אליעזר והן ר' עקיבא, \u0003כ\u0004שיטתו של \u0003רבי סבירא להו\u0004 \u0005[סבורים הם],\u0006 ש\u0003אמר\u0004 שה\u0003שחיטה\u0004 לעצמה \u0003מקדשא\u0004 \u0005[מקדשת]\u0006 את הלחם. ולדעת הכל התקדש לחם זה עם שחיטת הכבשים, וכשיצא אל מחוץ לעזרה היה כבר קדוש.","\u0003מיהו\u0004 \u0005[ואולם]\u0006 בדבר זה נחלקו: ש\u0003ר' אליעזר\u0004 הולך בהלכה זו \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכך \u0003אמר\u0004 ר' אליעזר ש\u0003אין\u0004 ה\u0003זריקה מועלת\u0004 (פועלת, מחילה דין) אלא לקדשים שבעזרה, ולא \u0003ל\u0004קרבן ה\u0003יוצא\u0004 מהעזרה. ולכך כאשר יצא הלחם אל מחוץ לעזרה לפני הזריקה, אין מחשבת הפיגול של הכהן בשעת זריקת הדם מחילה עליו דין פיגול. \u0003ו\u0004כמו כן אף \u0003ר' עקיבא\u0004 הולך בהלכה זו \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכך \u0003אמר\u0004 ר' עקיבא \u0003כי ה\u0004\u0003זריקה מועלת\u0004 אף \u0003ליוצא,\u0004 ולכך מחשבת הפיגול שחשב הכהן מחילה דין פיגול אף על הלחם שיצא מהעזרה."],["\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 נחלקו \u0003ר' אליעזר ור' עקיבא בדינם של\u0004 \u0003אימורי\u0004 (חלקי הקרבן העולים למזבח) של \u0003קדשים קלים שיצאו\u0004 אל מחוץ לעזרה \u0003לפני זריקת דמים\u0004 וזרק אחר כך את הדם עליהם. \u0003ש\u0004\u0003ר' אליעזר אומר:\u0004 אין זריקה זו נחשבת כלל, ומשום כך \u0003אין\u0004 \u0003מועלין בהן. ואין חייבין עליהן משום פיגול\u0004 אם בשעת אחת העבודות קודם ל\u0003זריקת הדם הראויה חשב על הקרבן לאוכלו מחוץ לזמנו הראוי, שלא נתפגל הקרבן, והאוכל מבשרו במזיד אינו חייב כרת, כיון שאין זו זריקה ראויה. ואינו חייב כרת על אכילת בשרם של אלו אם\u0004 \u0003נותר\u0004 הבשר לאחר זמן אכילתו הראוי, \u0003ו\u0004כן אינו חייב כרת על אכילתם כשהוא \u0003טמא\u0004 טומאת הגוף. שהרי הם כמי שלא נעשתה בהם זריקה כלל.","ואילו \u0003ר' עקיבא אומר:\u0004 זריקה זו נחשבת לענין זה שיהיו \u0003מועלין בהן, וחייבין עליהן משום פיגול ונותר וטמא.\u0004","ובדבר זה הוצעה בעייתו של ר' שמואל בר רב יצחק מר' חייא בר אבא: לשיטתו זו של ר' עקיבא \u0003מאי\u0004 \u0005[מה]\u0006 הוא הדין לענין היתר אכילתו של הלחם בכבשי עצרת שנשחטו לשמם אך נזרק דמם שלא לשמם?","\u0003ומפרט את צדדי הבעיה: האם יש לומר כי\u0004 \u0003מ\u0004אחר שלמדנו כי \u0003זריקת\u0004 דם כבשי העצרת במחשבת \u0003פיגול קבעה\u0004 (מחילה דין) \u0003ל\u0004שתי ה\u0003לחם\u0004 שהריהם \u0003ב\u0004איסור \u0003פיגול,\u0004 שאף שזריקה זו נעשית על קדשים שנפסלו \u0003ב\u0004פסול \u0003יוצא,\u0004 מכל מקום נחשב הלחם היוצא \u0003כבשר\u0004 הקרבן וחל עליו דין פיגול. אף בענייננו נאמר \u0003ש\u0004\u0003זריקה שלא לשמה\u0004 כיון שהיא מתירה את בשרם של כבשי העצרת, כמו כן \u0003נמי\u0004 \u0005[גם כן]\u0006 הריהי \u0003שריא ליה\u0004 \u0005[מתירה אותו]\u0006 את \u0003ה\u0004\u0003לחם.\u0004 ומן הצד האחר: \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי לא נאמרה שיטה זו של ר' עקיבא אלא \u0003לחומרא\u0004 \u0005[להחמרה]\u0006 בדין (וכגון לענין שיחול איסור פיגול על הלחם שיצא אל מחוץ לעזרה בין שחיטה לזריקה), שדווקא בזה \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 שייחשב הדבר היוצא כבשר הקרבן הנמצא בעזרה, ופועלת בו הזריקה. אבל \u0003לקולא\u0004 \u0005[להקלה]\u0006 בדין (וכגון בענייננו, שיותר הלחם באכילה בזריקה זו) — בזה \u0003לא אמרינן\u0004 \u0005[אין אומרים אנו]\u0006 כן.","על דרך העמדה זו של מחלוקת ר' אליעזר ור' עקיבא, \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב פפא: וממאי\u0004 \u0005[וממה,\u0006 ומנין\u0005]\u0006 לנו \u0003דכי איתנהו אבראי פליגי\u0004 \u0005[שכאשר\u0006 הלחמים \u0005נמצאים בחוץ\u0006 הם \u0005חולקים]?\u0006","\u0003דילמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003בדאיתנהו אבראי\u0004 \u0005[ב\u0006מקרה \u0005ש\u0006הם \u0005נמצאים בחוץ]\u0006 — \u0003דכולי עלמא לא פליגי\u0004 \u0005[שהכל\u0006 מודים, ואף ר' עקיבא, \u0005אינם חלוקים]\u0006 שלדעת הכל \u0003אין\u0004 ה\u0003זריקה מועלת\u0004 (מועילה, מחילה דינים) \u0003ליוצא.\u0004 אלא \u0003ב\u0004אופן ש\u0003הדר עיילינהו פליגי\u0004 \u0005[\u0006ש\u0005חזר\u0006 ו\u0005הכניסם\u0006 לעזרה לפני הזריקה, הם \u0005חלוקים],\u0006 ש\u0003ר' אליעזר סבר לה\u0004 \u0005[הריהו סבור]\u0006 \u0003כ\u0004דעת \u0003רבי,\u0004 ש\u0003אמר\u0004 כי ה\u0003שחיטה מקדשא\u0004 \u0005[מקדשת]\u0006 את הלחם, \u0003ו\u0004משום כך \u0003איפסלו להו\u0004 \u0005[נפסלו\u0006 להם\u0005]\u0006 הלחמים \u0003ביוצא\u0004 כאשר יצאו לאחר שחיטת הכבשים, ומעתה אף שהוכנסו חזרה לפני הזריקה שוב לא יחול בהם פסול פיגול.","\u0003ו\u0004אילו \u0003ר' עקיבא\u0004 סבור \u0003כר' אלעזר בר' שמעון\u0004 ש\u0003אמר\u0004 כי ה\u0003שחיטה\u0004 כשלעצמה \u0003לא מקדשא\u0004 \u0005[אינה מקדשת]\u0006 את הלחם, אלא זריקת הדם היא המקדשת אותם, \u0003ו\u0004לכן הלחמים שיצאו אל מחוץ לעזרה לפני זריקת הדם כיון שלא התקדשו עדיין, \u0003לא מיפסלי\u0004 \u0005[אינם נפסלים]\u0006 \u0003ב\u0004פסול \u0003יוצא,\u0004 ולכשיזרוק את הדם, אם תהא הזריקה במחשבת פיגול — תחיל עליהם זריקה זו דין פיגול. ומעתה אין עוד מקום לבעייתו זו של ר' שמואל בר רב יצחק לשיטתו של ר' עקיבא, שהרי אין הזריקה מועילה לדבר שנפסל (כלחמים הללו שנפסלו בשחיטה שלא לשמה)!","ודוחים את קושיית רב פפא: \u0003האי מאי\u0004 \u0005[\u0006פירוש \u0005זה\u0006 של \u0005מחלוקת ר' אליעזר ור' עקיבא,\u0006 \u0005מה\u0006 טיבו\u0005]?\u0006 הלא אין הוא הולם את מחלוקתם. שכן \u0003אי אמרת בשלמא\u0004 \u0005[נניח,\u0006 זה ברור, \u0005אם אתה אומר\u0006\u0005]\u0006 ש\u0003ר' עקיבא כ\u0004שיטת \u0003רבי סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר\u0004 כי ה\u0003שחיטה מקדשא להו\u0004 \u0005[מקדשת אותם,\u0006 את הלחמים\u0005]\u0006 — \u0003היינו דקאמר\u0004 \u0005[זהו שאמר]\u0006 \u0003ר' עקיבא דקדשי להו\u0004 \u0005[שמקדשים אותם,\u0006 את הלחמים\u0005]\u0006 \u0003בשחיטה, ואתיא\u0004 \u0005[ובאה]\u0006 ה\u0003זריקה\u0004 זו שנעשתה במחשבת אכילה חוץ לזמנו, ו\u0003קבעה להו\u0004 \u0005[קובעת אותם]\u0006 \u0003ב\u0004איסור \u0003פיגול.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שר' עקיבא \u0003כ\u0004שיטת \u0003ר' אלעזר בר' שמעון סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר\u0004 כי ה\u0003זביחה\u0004 (שחיטה) כשלעצמה \u0003לא מקדשא\u0004 \u0005[אינה מקדשת]\u0006 את הלחם, אלא הזריקה, וכי \u0003זריקת פיגול מי מקדשא\u0004 \u0005[האם מקדשת]?\u0006","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב גידל, אמר רב\u0004 כי \u0003זריקת\u0004 הדם במחשבת \u0003פיגול\u0004 אמנם מחילה איסור פיגול על בשר הקרבן, ואולם היא \u0003אינה מביאה\u0004 מעתה את הקדשים שלא היו עד כה בכלל דין מעילה \u0003לידי\u0004 דין \u0003מעילה, ו\u0004כמו כן היא \u0003אינה מוציאה\u0004 מעתה את הקדשים שהיו בכלל דין מעילה \u0003מידי\u0004 דין \u0003מעילה.\u0004","ומפרש רב את דבריו: זריקה ש\u0003אינה מביאה\u0004 קדשים \u0003לידי מעילה\u0004 — \u0003באימורי\u0004 (בחלק הקרב על המזבח) \u0003קדשים קלים\u0004 שבשרם ממון בעליהם, ואף האימורים אינם נכללים בהגדרת \"קדשי ה' \" (\"נפש כי תמעול מעל וחטאה בשגגה מקדשי ה' \". ויקרא ה, טו) שבהם אמור דין מעילה, שכיון שאינם קרבים על המזבח, מפני שנפסלו בזריקה זו.","\u0003ו\u0004זריקה זו \u0003אינה מוציאה מידי מעילה\u0004 — \u0003בבשר קדשי קדשים\u0004 כגון החטאת והאשם ושלמי ציבור שהוא נאכל לכהנים, שעדיין יש בו דין מעילה, שהרי לא פסק מלהיקרא \"קדשי ה' \", שמאחר והיתה זו זריקת פיגול — לא הועילה","\u0003!\u0004 ודוחים: כיצד מביאים מדברי רב גידל שאמר בשם רב, ו\u0003לאו איתותב\u0004 \u0005[האם לא הוקשו]\u0006 דברים אלה של \u0003רב גידל אמר רב\u0004 במסכת מעילה (דף ג,ב) ונדחו?","ועוד בעיה שעניינה הוא כבשי ולחמי העצרת \u0003בעא מיניה\u0004 \u0005[שאל\u0006 \u0005ממנו]\u0006 \u0003ר' ירמיה מר' זירא:\u0004 שני \u0003כבשי\u0004 ה\u0003עצרת ששחטן לשמן,\u0004 והוקבעו בשחיטה זו עם שתי הלחם הבא איתם, \u0003ו\u0004אחר כן \u0003אבד הלחם.\u0004 אם יזרק דם הכבשים לשמם — ודאי שלא תתיר זריקה זו את הכבשים, שהרי הוקבעו עם הלחם וזה הלא אבד. ואולם יש לשאול: \u0003מהו\u0004 הדין \u0003שיזרוק\u0004 הכהן \u0003את\u0004 \u0003דמן\u0004 של הכבשים על המזבח \u0003שלא לשמן\u0004 אלא לשם שלמים, כדי \u0003להתיר\u0004 בכך את \u0003בשר\u0004 הכבשים \u0003באכילה?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא בתמיהה על עצם העלאת אפשרות שכזו: וכי \u0003יש לך דבר\u0004 כיוצא בזה, \u0003ש\u0004הוא \u0003אינו כשר\u0004 אם נעשה \u0003לשמו,\u0004 \u0003ו\u0004אולם הוא \u0003כשר\u0004 אם נעשה \u0003שלא לשמו?!\u0004 הקשה ר' ירמיה על תמיהתו זו של ר' זירא: \u0003ו\u0004כי \u0003לא\u0004 מצאנו כדבר הזה?! \u0003והרי\u0004 קרבן \u0003פסח\u0004 ביום ארבעה עשר בניסן (ערב פסח) \u0003קודם חצות\u0004 היום (שהוא תחילת זמן הקרבתו) — \u0003אינו כשר\u0004 אם נשחט \u0003לשמו,\u0004 לשם פסח, שהרי נשחט קודם זמנו, \u0003ו\u0004הריהו \u0003כשר\u0004 אם נשחט \u0003שלא לשמו\u0004 אלא לשם קרבן שלמים\u0003! אמר לו ר' זירא לר' ירמיה בהסבר תמיהתו:\u0004","\u0003הכי קאמינא\u0004 \u0005[כך אני אמרתי,\u0006 זאת התכוונתי לומר\u0005]:\u0006 האם \u0003יש לך דבר\u0004 כיוצא בזה, \u0003ש\u0004כבר \u0003נראה\u0004 (היה ראוי) להקריבו \u0003לשמו\u0004 (כדוגמת כבשי עצרת אלה, שנשחטו לשמם כשהיה לחם אתם), \u0003ו\u0004לאחר מכן \u0003נדחה\u0004 (חדל להיות ראוי) \u0003מ\u0004להקריבו \u0003לשמו\u0004 (שכבשים אלה, שמשעה שאבד לחמם, אף הם נדחו מהקרבה), \u0003ואינו כשר\u0004 אם יוקרב \u0003לשמו, ו\u0004אולם הריהו \u0003כשר\u0004 אם יוקרב \u0003שלא לשמו?!\u0004","הקשה ר' ירמיה גם על הסבר זה: \u0003ו\u0004כי \u0003לא\u0004 מצאנו אף כדבר הזה?! \u0003והרי\u0004 קרבן \u0003פסח,\u0004 כשמגיע זמנו בין הערביים שבי\"ד בניסן — הריהו ראוי להקריבו לשמו, \u0003ומ\u0004\u0003אחר זמנו\u0004 — אף שהוא נדחה מהקרבה לשמו, בכל זאת \u0003בשאר ימות השנה\u0004 אף \u0003קודם חצות\u0004 היום — הרי הוא כשר אם יוקרב שלא לשמו, אלא לשם שלמים!","חזר ר' זירא והסביר את תמיהתו: \u0003הכי קאמינא\u0004 \u0005[כך אמרתי,\u0006 זאת התכוונתי לומר\u0005]:\u0006 האם \u0003יש לך דבר\u0004 כיוצא בזה, \u0003ש\u0004כבר \u0003נראה\u0004 (היה ראוי) להקריבו \u0003לשמו\u0004 (כדוגמת כבשי עצרת אלה, שהובאו להקרבתם עם הלחם, כדין), \u0003ו\u0004גם \u0003נשחט\u0004 קרבן זה \u0003לשמו\u0004 \u0003ו\u0004לאחר מכן \u0003נדחה\u0004 (חדל להיות ראוי) \u0003מ\u0004להקריבו \u0003לשמו\u0004 (וכגון כבשים אלה, שמשעה שאבד לחמם, נדחו מהקרבה), \u0003ואינו כשר\u0004 אם יוקרב \u0003לשמו, ו\u0004אולם הריהו \u0003כשר\u0004 אם הוא יוקרב \u0003שלא לשמו?!\u0004","חזר והקשה ר' ירמיה גם על הסבר זה: \u0003ו\u0004כי \u0003לא\u0004 מצאנו אף כדבר הזה?! \u0003והרי\u0004 קרבן \u0003תודה\u0004 ולחמיו, שלמדנו את דינו למעלה (מו,א) שאם לאחר שנשחט קרבן התודה נפרס הלחם, ונפסל בכך — יזרק דם התודה לשם שלמים ובשר הקרבן ייאכל, ואילו היה נזרק דם התודה לשמו — לא היה הבשר מותר באכילה, ואילו משנזרק שלא לשמו — הריהו מותר באכילה.","ודחה ר' זירא ראיה זו: אין להביא ראיה מקרבן תודה שכן \u0003שאני\u0004 \u0005[שונה,\u0006 נבדל\u0005]\u0006 דין ה\u0003תודה\u0004 משאר דיני הקרבנות, \u0003דרחמנא קרייה\u0004 \u0005[ש\u0006כן \u0005התורה קראה אותו]\u0006 \u0003\"שלמים\"\u0004 (\"זבח תודת שלמיו\". ויקרא ז, יג), וכשם שהשלמים הריהם קרבנות הבאים בלא לחם, כן יש והתודה באה בלא לחם. ולכך אין אובדנו של הלחם מחשיב את הקרבן כנדחה. מה שאין כן בבעיית ר' ירמיה, שנדחו הכבשים באובדנו של הלחם.","ומביאים עוד בדינם של כבשי ולחמי העצרת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שחט\u0004 את \u0003שני\u0004 ה\u0003כבשים\u0004 כדין, ואולם שחטם \u0003על ארבע חלות\u0004 ולא על שתים כדינם — מה יעשה? \u0003הריהו\u0004 \u0003מושך שתים מהן\u0004 מן החלות הללו, שהן תהיינה לחמי \u0003העצרת,\u0004 \u0003ומניפן\u0004 עם שני הכבשים שנשחטו,"],["\u0003והשאר\u0004 (שתי החלות האחרות) \u0003נאכלות בפדיון,\u0004 \u0003אמרוה רבנן\u0004 \u0005[חכמים]\u0006 את ההלכה הבאה \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא: הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 הריהי ש\u0003לא כ\u0004שיטת \u0003רבי\u0004 הסבור כי שחיטת כבשי העצרת מקדשת את הלחמים, ולפיכך כבר התקדשו הלחמים הללו בקדושת הגוף. אלא כר' אלעזר בר' שמעון הסבור כי השחיטה אינה מקדשת את הלחמים, ולא התקדשו עדיין הלחמים בקדושת הגוף, ומשום כך יכול למשוך שני לחמים שירצה מתוך הארבעה, ולזרוק עליהם את הדם ולקדשם בכך, ושני הלחמים האחרים נפדים.","\u0003דאי\u0004 \u0005[ש\u0006כן \u0005אם]\u0006 היא כשיטת \u0003רבי\u0004 — יש לשאול: \u0003כיון\u0004 שרבי \u0003אמר\u0004 כי ה\u0003שחיטה מקדשא\u0004 \u0005[מקדשת]\u0006 את שני הלחמים, זה שאמרה הברייתא \u0003דפריק להו\u0004 \u0005[שפודה אותם,\u0006 את שאר החלות\u0005],\u0006 \u0003היכא\u0004 \u0005[היכן]\u0006 הוא פודה אותן? שלשיטתו לשם פדיונם צריך שיהיו ארבעת הלחמים לפניו בשעת הפדיון (שהרי אינו יודע מי מהם הלחמים המקודשים בקדושת הגוף, ומי מהם הלחמים הקדושים בקדושת דמים)?","ומעתה, \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן \u0003דפריק להו מאבראי\u0004 \u0005[שפודה אותם,\u0006 את הלחמים \u0005מחוץ\u0006 לעזרה\u0005],\u0006 שמוציא את ארבעת הלחמים אל מחוץ לעזרה ופודה שנים מתוכם — \u0003כיון דכתיב\u0004 \u0005[שנאמר]\u0006 במצוות התנופה בשתי הלחם \"והניף הכהן אותם על לחם הביכורים תנופה \u0003לפני ה'\u0004 על שני כבשים...\" (ויקרא כג, כ), הרי אותם שני הלחמים שהתקדשו בתנופה זו, \u0003איפסיל להו\u0004 \u0005[נפסלו]\u0006 בכך \u0003ביוצא!\u0004 ו\u0003אי\u0004 \u0005[אם]\u0006 הוא מביא את כל ארבעת הלחמים ופודה שנים מהם ב\u0003גוואי\u0004 \u0005[בפנים\u0006 העזרה\u0005]\u0006 — \u0003הא\u0004 \u0005[הרי]\u0006 נמצא שבכך הוא \u0003מעייל\u0004 \u0005[מכניס]\u0006 \u0003חולין לעזרה,\u0004 את שני הלחמים שיצאו לחולין!","\u0003אמר להו\u0004 \u0005[להם,\u0006 לחכמים\u0005]\u0006 \u0003רב חסדא: לעולם\u0004 דעת ברייתא זו היא \u0003כ\u0004שיטת \u0003רבי, ופריק להו גוואי\u0004 \u0005[ופודה אותם בפנים],\u0006 אבל אין זה נחשב כמכניס חולין לעזרה, שכן בכגון זה עצם היותם \u0003חולין\u0004 בעזרה \u0003ממילא\u0004 (מאליהם, מעצמם) \u0003קא הוויין\u0004 \u0005[הם נעשים],\u0006 ברגע פדיונם, שאין זה דומה לאדם המכניס מלכתחילה חולין אל תוך העזרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי\u0004 בשאלה על דברי רב חסדא אלה: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 הדנה במקרה זה של השוחט שני כבשי עצרת על ארבעה לחמים, ובמפורש אומרת הברייתא כי \u0003כשהוא פודן\u0004 את שאר החלות, \u0003אין\u0004 הוא \u0003פודן\u0004 בעזרה \u0003אלא בחוץ\u0004 לעזרה, ולדברי רב חסדא יכול הוא לשיטת רבי לפדותן בפנים כיון שנעשות הן חולין מאליהן!","ומשיבים: מברייתא זו אין להקשות על דברי רב חסדא שכן לא אמר רב חסדא את הסברו אלא לשיטת הברייתא הקודמת, ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו],\u0006 ב\u0003ודאי\u0004 כשיטת \u0003ר' אלעזר בר' שמעון היא.\u0004 וראיה לדבר, \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003רבי\u0004 האומר שהשחיטה מקדשת את הלחמים — כיצד מוציאים את ארבעת הלחמים אל מחוץ לעזרה, ו\u0003הא איפסלו להו\u0004 \u0005[הרי נפסלו להם]\u0006 הלחמים שהתקדשו משום \u0003יוצא!\u0004 אלא ודאי כיון שאמר שיכול לפדות אותן משמע שעדיין לא התקדשו לגמרי.","למעלה הובאו דברי הברייתא בדין השוחט את כבשי עצרת על ארבעה לחמים, ששנינו בה שהתקדשו שני לחמים מתוכם. ובענין זה מביאים מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: לימא תיהוי תיובתיה\u0004 \u0005[האם נאמר\u0006 כי \u0005תהא\u0006 ברייתא זו \u0005קושיה]\u0006 על שיטת \u0003ר' יוחנן, מיהא דאיתמר\u0004 \u0005[מזו שנאמר]\u0006 בדינה של \u0003תודה ששחטה על שמונים חלות\u0004 ולא על ארבעים חלות כדינה, \u0003חזקיה אמר\u0004 כי \u0003קדשו ארבעים\u0004 חלות \u0003מתוך\u0004 ה\u0003שמונים\u0004 הללו. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 ש\u0003לא קדשו ארבעים מתוך שמונים.\u0004 והרי מברייתא זו רואים כי כאשר שחט את הקרבן על מספר לחמים יותר מכפי הראוי לו, שמתקדש רק חלק מהם כמספר הראוי!","ודוחים את הקושיה: \u0003ולאו מי איתמר עלה\u0004 \u0005[והאם לא נאמר עליה]\u0006 בהסבר מחלוקת זו שבין חזקיה ור' יוחנן, ש\u0003אמר ר' זירא: הכל מודים,\u0004 ואף ר' יוחנן, כי \u0003היכא\u0004 \u0005[היכן,\u0006 במקום\u0005]\u0006 ש\u0003אמר\u0004 המקדיש את התודה בשעת הקדשתו אותה עם לחמיה \u0003\"ליקדשו\u0004 \u0005[שיתקדשו]\u0006 \u0003ארבעים\u0004 חלות \u0003מתוך\u0004 ה\u0003שמונים\"\u0004 — \u0003דקדשה\u0004 \u0005[שהתקדשו]\u0006 אכן ארבעים, אף שהיו בשעת השחיטה שמונים חלות. ואף \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בדברי הברייתא, \u0005גם כן]\u0006 צריך לומר שמדובר בה באופן ש\u0003אמר \"ליקדשו תרתי\u0004 \u0005[שיתקדשו שתים]\u0006 \u0003מתוך ארבע\u0004 החלות\", ובאופן זה אף ר' יוחנן מודה שהתקדשו רק שנים.","ומביאים עוד בעניינם של כבשי ולחמי העצרת ממה ש\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חנינא טירתא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא זו: אם \u0003שחט ארבעה כבשים\u0004 לכבשי העצרת (ולא שנים, כדין) \u0003על שתי חלות,\u0004 מה יעשה בשני הכבשים הנוספים? הריהו \u0003מושך שנים מהן\u0004 (מתוך הארבעה הללו) \u0003וזורק\u0004 את \u0003דמן\u0004 על המזבח \u0003שלא לשמן\u0004 (שלא לשם כבשי העצרת), ולאחר מכן הריהו זורק את דמם של הכבשים האחרים לשם כבשי העצרת.","\u0003שאם אי\u0004 (אין) \u0003אתה אומר\u0004 לנהוג \u0003כך,\u0004 אלא שיזרוק בתחילה את דמם של שני כבשים לשם כבשי העצרת, ורק לאחר מכן יזרוק את דמם של השנים האחרים שלא לשם כבשי העצרת — \u0003הפסדת\u0004 בכך \u0003את\u0004 שני הכבשים \u0003האחרונים,\u0004 שכיון שכבשים אלו כבר היו ראויים להיזרק דמם על המזבח לשמם, ונדחו בזריקת דמם של השנים הראשונים — שוב אין הם כשרים להיזרק שלא לשמם.","\u0003אמר לו ר' יוחנן\u0004 בתמיהה על הדברים הללו: \u0003וכי\u0004 הנהגה נכונה היא זו, שיהא בית דין \u0003אומר לו לאדם \"עמוד וחטא\u0004 בדבר אחד (כגון זה שיזרוק דמם של שני הכבשים הראשונים שלא לשמם) \u0003בשביל שתזכה\u0004 בדבר אחר (הכבשים האחרונים)\"?!","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שנחלקו תנאים בדינם של \u0003אברי\u0004 קרבן \u0003חטאת\u0004 (הנאכלים לכהנים) \u0003שנתערבו באברי עולה\u0004 (העולים כליל על המזבח), ואין אנו יודעים איזה מן האיברים הללו הם לאכילה ואיזה להקטרה על המזבח. ש\u0003ר' אליעזר אומר\u0004 כי \u0003יתנו\u0004 את האיברים האלה כולם \u0003למעלה\u0004 על המזבח, ובכללם גם אברי החטאת. \u0003ו\u0004אין בדבר משום הקרבה של דבר שאינו ראוי למזבח, משום ש\u0003רואה אני את בשר\u0004 ה\u0003חטאת\u0004 הנמצא עתה \u0003למעלה\u0004 על המזבח \u0003כאילו היא עצים\u0004 הנשרפים, ולא כקרבן. \u0003וחכמים אומרים\u0004 כי \u0003תעובר צורתן\u0004 של כל האיברים הללו (שימתינו עד שיפסלו בלינת לילה), \u0003ויצאו\u0004 כולם \u0003לבית השריפה.\u0004","ולשיטתך יש מקום לשאול על דעת חכמים \u0003אמאי\u0004 \u0005[מדוע]\u0006 שורפים את כל תערובת האיברים הזו? \u0003לימא\u0004 \u0005[יאמר]\u0006 לו בית דין לכהן \u0003\"עמוד וחטא\u0004 בהקרבת איברי החטאת על המזבח, \u0003בשביל שתזכה\u0004 בהקרבתם של איברי העולה\"!","השיב ר' חנינא טירתא לר' יוחנן על שאלתו זו: אין להקשות ממשנה זו שכן \u0003\"עמוד וחטא ב\u0004קרבן \u0003חטאת\u0004 זה, \u0003בשביל שתזכה ב\u0004קרבן \u0003חטאת\u0004 זה\", שקרבן אחד הוא זה — \u0003אמרינן\u0004 \u0005[אומרים אנו],\u0006 ובענייננו, אומרים לו לחטוא בשני כבשי העצרת הראשונים, כדי שיזכה בשני כבשי העצרת האחרים. אבל \u0003\"עמוד וחטא ב\u0004קרבן \u0003חטאת\u0004 זה, \u0003בשביל שתזכה ב\u0004קרבן \u0003עולה\u0004 זה\" — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 ולכך לשיטת חכמים גם אין מעלים את איברי החטאת על המזבח כדי לאפשר את הקרבתם של איברי העולה.","הקשה על כך ר' יוחנן: \u0003ו\u0004כי \u0003בחדא מילתא מי אמר\u0004 \u0005[בדבר אחד האם\u0006 אכן \u0005אומרים,\u0006 מורים\u0005]\u0006 לו לאדם לחטוא בדבר אחד כדי לזכותו בדבר השני?! \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כבשי עצרת ששחטן שלא לשמן, או ששחטן בין לפני זמנן\u0004 (לפני חג השבועות), \u0003בין לאחר זמנן\u0004 (לאחר חג השבועות), מה יעשה בהם? — \u0003הדם יזרק\u0004 שלא לשם כבשי עצרת אלא לשם שלמים, \u0003והבשר יאכל\u0004 כשלמים.","אבל \u0003אם היתה\u0004 חג העצרת ביום ה\u0003שבת,\u0004 מאחר שלא הותרה בשבת זריקת דמם של קרבנות יחיד, אלא של ציבור בלבד, כבשים אלה שנדחו מכלל קרבנות ציבור כשנשחטו שלא לשמם או שלא בזמנם — \u0003לא יזרוק\u0004 את דמם, ולא יוקרבו על המזבח, וייאסר בשרם להיאכל. \u0003ו\u0004אולם \u0003אם\u0004 עבר ו\u0003זרק\u0004 בשבת את דמם של הכבשים הללו — \u0003הורצה\u0004 (התקבל) הקרבן לענין זה שיהא מותר \u0003להקטיר\u0004 את ה\u0003אימורין\u0004 (חלק הקרבן הקרב על המזבח) \u0003לערב\u0004 (במוצאי שבת), והבשר ייאכל.","\u0003ו\u0004אם כדבריך, שבדבר אחד אומרים לאדם לחטוא בזה על מנת שיזכה בזה, \u0003אמאי\u0004 \u0005[מדוע]\u0006 אינו מותר בזריקת הדם בעצרת שחלה בשבת? \u0003לימא\u0004 \u0005[יאמר,\u0006 יורה לו בית דין\u0005]\u0006 \u0003\"עמוד\u0004 ו\u0003חטא\u0004 בזריקת הדם של קרבן זה, \u0003בשביל שתזכה\u0004 בהקטרת איבריו ובאכילת בשרו של קרבן זה לערב\".","ומשיבים: \u0003\"עמוד חטא בשבת, כדי שתזכה בשבת\"\u0004 — \u0003אמרינן\u0004 \u0005[אומרים אנו],\u0006 אבל \u0003\"עמוד חטא בשבת, כדי שתזכה בחול\"\u0004 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006","וחזר ושאל ר' יוחנן: \u0003ובתרתי מילי\u0004 \u0005[ובשני דברים\u0006 נבדלים\u0005]\u0006 \u0003לא אמר\u0004 \u0005[אין אומרים]\u0006 הוראה זו לחטוא בדבר אחד כדי לזכות בדבר אחר?! \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003חבית של\u0004 משקה \u0003תרומה שנשברה\u0004 ביום השבת. ונמצאת החבית \u0003בגת העליונה,\u0004 ומשם נוזל המשקה הנמצא בה למטה אל הגת התחתונה. \u0003וב\u0004גת ה\u0003תחתונה\u0004 היו מצויים באותה עת משקים של \u0003חולין טמאין,\u0004 מה יעשה? \u0003מודה ר' אליעזר ור' יהושע\u0004 (שנחלקו, להלן במקרה האחר) \u0003שאם\u0004 הוא \u0003יכול\u0004 להספיק ו\u0003להציל ממנה\u0004 מן המשקה הנמצא בחבית התרומה אפילו \u0003רביעית\u0004 לוג אחת \u0003בטהרה\u0004 על ידי כלי טהור — \u0003יציל\u0004 את משקה התרומה הטהור, אף ששאר המשקה שבחבית ישפך לגת התחתונה אל החולין הטמאים, ונטמא משקה התרומה, וכן נפסדו החולין (כיון שהתערב בתוכם משקה של תרומה ואינם ראויים אלא לכהנים).","\u0003ואם לאו\u0004 \u0005[לא],\u0006 שאין לו כלי טהור, ועתיד כל משקה התרומה בחבית שבגת העליונה להישפך אל החולין הטמאים שבגת התחתונה — נחלקו בכך, ש\u0003ר' אליעזר אומר:\u0004"],["\u0003תרד\u0004 כל התרומה שבגת העליונה, \u0003ותטמא\u0004 על ידי החולין הטמאים שבגת התחתונה, ונמצאת מפסידה את משקה החולין, \u0003ואל יטמאנה\u0004 את הנמצא בחבית \u0003ביד\u0004 (במעשה הנעשה על ידו), לשאוב בכלים טמאים, וכדי להציל את משקה החולין. \u0003ו\u0004אילו \u0003ר' יהושע אומר\u0004 כי יכול הוא (אם רצונו בכך) \u0003אף\u0004 ש\u0003יטמאנה ביד.\u0004 הרי מכאן שמורים לו לאדם לחטוא בדבר אחד כדי לזכות באחר!","השיב לו ר' חנינא טירתא לר' יוחנן: אין להקשות מהלכה זו, שכן \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 המצב, שהרי אף אם לא יעשה כל מעשה שהוא, תכולת החבית \u0003לטומאה קא אזלא\u0004 \u0005[היא הולכת]\u0006 כאשר תיפול אל משקה החולין שבגת התחתונה. לכך אין מעשה זה שהוא קולט את הנמצא בחבית העליונה בכלים טמאים ונטמאת היא בכך, נחשב לחטא.","ועוד בדיני כבשי העצרת. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב יצחק\u0004 מארץ ישראל לבבל, והביא עמו מסורות שונות, \u0003תני\u0004 \u0005[שנה]\u0006 ברייתא זו: \u0003כבשי עצרת ששחטן שלא כמצותן,\u0004 וכגון ששחטם שלא לשם כבשי עצרת — הריהם \u0003פסולין\u0004 בכך, \u0003ותעובר צורתן\u0004 (בלינת לילה), \u0003ויצאו לבית השריפה.\u0004","\u0003אמר רב נחמן\u0004 לרב יצחק: שנה \u0003מר\u0004 \u0005[אדוני]\u0006 את דברי הברייתא הזו באופן זה, משום שהריהו \u0003מקיש\u0004 (משווה) \u0003להו\u0004 \u0005[אותם,\u0006 את דין כבשי העצרת\u0005]\u0006 \u0003ל\u0004דין קרבן \u0003חטאת,\u0004 ולכך הריהו \u0003תני\u0004 \u0005[שונה]\u0006 בדינם של הכבשים הללו שנשחטו שלא לשמם שהם \u0003פסולין,\u0004 כדין קרבן חטאת שנשחט שלא לשמו. ואילו ה\u0003תנא דבי\u0004 [של בית מדרשו\u0003]\u0004 של \u0003לוי דגמר\u0004 \u0005[שלמד]\u0006 את דין \u0003שלמי חובה מ\u0004דינם של \u0003שלמי נדבה,\u0004 לכך \u0003תני\u0004 \u0005[שונה]\u0006 בדינם של הכבשים הללו שהם \u0003כשרים,\u0004 כדין שאר הקרבנות (מלבד חטאת ופסח),","\u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003לוי\u0004 בברייתא העוסקת בקרבנות שצריך הנזיר להביא: \u0003ושאר שלמי נזיר ששחטן שלא כמצותן\u0004 (שלא לשמם) — הריהם \u0003כשרין\u0004 ודינם כשלמי נדבה, \u0003ו\u0004אף ש\u0003לא עלו\u0004 (אין הם נחשבים) \u0003לבעלים לשם\u0004 שלמי ה\u0003חובה\u0004 (שחייב להביא בנזירותו). \u0003ו\u0004אולם הם \u0003נאכלין ליום ולילה\u0004 בלבד, כשלמי נזיר (ולא כשלמי נדבה הנאכלים לשני ימים ולילה אחד). \u0003ואין\u0004 הם \u0003טעונין\u0004 (חייבים) בהבאה \u0003לא\u0004 של \u0003לחם ולא זרוע\u0004 (כחובתו של הנזיר).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב יצחק מהברייתא הבאה: מי שהיה צריך להביא \u0003לקרבן ה\u0004\u0003אשם\u0004 בן צאן שהוא \u0003בן\u0004 (בתוך) \u0003שנה\u0004 ראשונה לחייו, והוא הנקרא \"כבש\", \u0003והביא\u0004 בן צאן שהוא \u0003בן שתים\u0004 (והוא הנקרא \"איל\"). או מי שהיה צריך להביא לקרבן אשמו \u0003בן שתים\u0004 \u0003והביא\u0004 \u0003בן שנה\u0004 — קרבנות אלה הריהם \u0003פסולין, ותעובר צורתן\u0004 (בלינת לילה) \u0003ויצאו לבית השרפה.\u0004","\u0003אבל עולת\u0004 ה\u0003נזיר,\u0004 שמביא הנזיר במלאת ימי נזירותו, שדינה הוא כבש בן שנתו. \u0003ועולת יולדת,\u0004 שמביאה היולדת ביום ארבעים ואחד להולדת זכר וביום שמונים ואחד להולדת נקבה כבש בן שנתו לעולה. \u0003ועולת\u0004 ה\u0003מצורע,\u0004 שמביא המצורע לאחר שנטהר מצרעתו כבש בן שנתו לעולתו, \u0003שהיו\u0004 קרבנותיהם מ\u0003בני שתי שנים, ושחטן\u0004 — הריהם \u0003כשרין.\u0004","\u0003כללו של דבר: כל\u0004 דבר \u0003הכשר בעולת נדבה\u0004 — הריהו \u0003כשר\u0004 גם \u0003בעולת חובה.\u0004 \u0003וכל\u0004 דבר \u0003הפסול ב\u0004קרבן \u0003חטאת\u0004 — הריהו \u0003פסול\u0004 גם \u0003ב\u0004קרבן \u0003אשם, חוץ מ\u0004זה שעשאו \u0003שלא לשמו\u0004 שפסול רק בקרבן חטאת ולא באשם. הרי שלמדים דינם של קרבנות חובה (כעולות נזיר ומצורע) מדינם של קרבנות הנדבה (כעולות נדבה) להכשיר את עולות החובה, על אף שבכלל קרבנותיהם של הנזיר והמצורע בא גם קרבן חטאת, והיה מקום לומר שיילמד דינם מחטאת, ויפסל האיל שבא במקום כבש לעולה. ומכאן נסיק שכך הוא גם בכבשי עצרת שיילמד דינם משלמי נדבה, אף שבא עם כבשי העצרת גם קרבן חטאת, ויהא דינם של כבשי העצרת שנשחטו שלא לשמם להכשר, ושלא כדברי רב יצחק!","ומשיבים: אין להקשות מדברי ברייתא זו, שכן \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 ששנה אותה — ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003לוי הוא,\u0004 הסבור כי כבשי עצרת שנשחטו שלא לשמם כשרים, וכמובא למעלה.","ודנים בדברי רב נחמן שהסביר כי התנא של בית מדרשו של לוי מכשיר את כבשי העצרת שנשחטו שלא לשמם, משום שלמד את דין כבשי העצרת מדינם של שלמי נדבה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003לוי,\u0004 שלא כדבריך, שכן אמר לוי: \u0003אשם נזיר\u0004 (כבש בן שנתו המובא על ידי הנזיר שנטמא במת, ביום השמיני להטמאו) \u0003ו\u0004כן \u0003אשם מצורע\u0004 (כבש בן שנתו המובא על ידי המצורע לגמר טהרתו), \u0003ששחטן שלא לשמן\u0004 — הריהם \u0003כשרים, ו\u0004אולם \u0003לא עלו לבעלים לשום\u0004 (לשם) \u0003חובה.\u0004","ואם \u0003שחטן\u0004 לקרבנות אלה כשהיה \u0003מחוסר זמן בבעלים,\u0004 שעדיין לא הגיע זמנם של הבעלים להקרבה זו, \u0003או שהיו\u0004 הקרבנות הללו לא כבשים בני שנתם, אלא אילים \u0003בני שתי שנים, ושחטן\u0004 — הריהם \u0003פסולין. ו\u0004יש לדון:","\u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לדבריך, שלומד לוי את דינם של קרבנות החובה מדינם של קרבנות הנדבה, אם כן \u0003ליגמר\u0004 \u0005[שילמד]\u0006 אף את דינם של קרבנות האשם \u0003מ\u0004דין \u0003שלמים,\u0004 ויהיו אלה כשרים! ומשיבים: אין זו ראיה, שכן דינם של \u0003שלמים\u0004 חובה \u0003מ\u0004דינם של \u0003שלמים\u0004 רשות — אכן \u0003גמר\u0004 \u0005[לומד]\u0006 לוי, ואולם דינו של \u0003אשם מ\u0004דינו של \u0003שלמים\u0004 — \u0003לא גמר\u0004 \u0005[אין\u0006 לוי \u0005לומד].\u0006","ומקשים עוד על דברי רב נחמן: \u0003ואי\u0004 \u0005[אם]\u0006 אכן הוא כדבריך שלוי \u0003גמר\u0004 \u0005[לומד]\u0006 דינם של \u0003שלמים\u0004 חובה \u0003מ\u0004דינם של \u0003שלמים\u0004 נדבה — באותו אופן \u0003ליגמר נמי\u0004 \u0005[שילמד גם כן]\u0006 דינו של \u0003אשם מ\u0004דינו של \u0003אשם.\u0004 ומעתה נלמד שיהא דינם של \u0003אשם נזיר ואשם מצורע\u0004 שיהא כשר אף אם הביא איל ולא כבש בן שנה, \u0003מ\u0004דינם של \u0003אשם גזילות ואשם מעילות\u0004 שדינם הוא באיל בן שנתים. \u0003או\u0004 מצד אחר נלמד שיהא דינם של \u0003אשם גזילות ואשם מעילות\u0004 שהובא בהם כבש בן שנתו, שהוא כשר, \u0003מ\u0004דינם של \u0003אשם נזיר ואשם מצורע\u0004 שדינם הוא בכבש בן שנתו!","\u0003אמר רב שימי בר אשי:\u0004 אין זו שאלה, שכן \u0003דנין\u0004 דינו של \u0003דבר\u0004 שנעשה \u0003שלא בהכשירו\u0004 הראוי לכתחילה (ככבשי העצרת שנשחטו שלא לשמם) \u0003מדבר\u0004 שנעשה \u0003שלא בהכשירו\u0004 הראוי (כשלמי נדבה שקרבו שלא לשמם). \u0003ו\u0004אולם \u0003אין דנין דבר\u0004 שנעשה \u0003שלא בהכשירו\u0004 (כאשמם של נזיר ומצורע שבא כאיל בן שנתים ולא ככבש בן שנתו) \u0003מדבר שבהכשירו\u0004 (כאשם גזילות וכאשם מעילות, שדינם הוא לבוא כקרבן איל בן שנתים).","ושואלים על כך: \u0003ולא?\u0004 וכי אין למדים דבר שנעשה שלא כהכשירו מדבר שנעשה כהכשירו?! \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 \u0003מנין ל\u0004קרבן ש\u0003יוצא\u0004 אל מחוץ למקומו, ונפסל בכך, \u0003שאם\u0004 בכל זאת \u0003עלה\u0004 על גבי המזבח ש\u0003לא ירד\u0004 משם, ויוקרב? \u0003שהרי\u0004 הקרבן ה\u0003יוצא כשר\u0004 כאשר נעשה \u0003בבמה\u0004 (בהקרבה שלא במקדש, בזמן שהותרה הקרבה שכזו). שאין בבמה דין \"יוצא\". הרי שלמדים אנו דבר שנעשה שלא כהכשרו (היוצא שנפסל, והועלה על המזבח) מדבר שנעשה כהכשרו (הקרבה בבמה, בזמן שהותרה הקרבה שכזו)!"],["ומשיבים: אין זו קושיה על כללו של רב שימי בר אשי, ואכן אין למדים דבר הנעשה שלא בהכשרו מדבר הנעשה בהכשרו, והטעם שהיוצא שעלה למזבח לא ירד אינו משום שנלמד הדבר מדין במה, אלא ה\u0003תנא\u0004 על הפסוק האמור בקרבן העולה \u0003\"זאת תורת העלה\u0004 היא העולה על מוקדה...\" (ויקרא ו, ב), שבכך \u0003ריבה\u0004 הכתוב את כל העולים למזבח ובכלל זה אף הקדשים שיצאו אל מחוץ לעזרה, הוא ש\u0003סמיך ליה\u0004 \u0005[סמך עליו]\u0006 את דינו. ומה שהביא כראיה מבמה, אינו אלא כתוספת, אך לא ממנה נלמדו הדברים.","ומביאים עוד בדיני כבשי העצרת, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רבה בר בר חנה קמיה\u0004 \u0005[לפני]\u0006 \u0003רב:\u0004 שני \u0003כבשי\u0004 ה\u0003עצרת\u0004 (הבאים עם שתי הלחם, לקרבן השלמים) \u0003ששחטן\u0004 לא לשמם אלא \u0003לשום\u0004 (לשם) \u0003אילים\u0004 — הריהם \u0003כשרין\u0004 וייאכלו כשלמי נדבה, אבל \u0003לא עלו\u0004 (אין הם נחשבים) \u0003לבעלים,\u0004 הם כלל ישראל, \u0003לשום\u0004 (לשם) \u0003חובה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב\u0004 לרבה בר בר חנה: לא כך היא ההלכה, אלא \u0003עלו\u0004 \u0003ועלו\u0004 הכבשים כשלמי חובה, שיצא בכך הציבור ידי חובתו.","\u0003אמר רב חסדא: מסתברא מילתיה\u0004 \u0005[מסתברים הדברים]\u0006 של \u0003רב\u0004 שעלו הכבשים לשם חובת כבשי עצרת, \u0003ב\u0004מקרה ש\u0003כסבור\u0004 היה בשעה ששחט את הכבשים ש\u0003אילים\u0004 הם ולא כבשים, \u0003ו\u0004אף על פי כן \u0003שחטן לשום\u0004 \u0003כבשים,\u0004 ובמקרה זה אכן עלו הכבשים לשם חובה, \u0003שהרי\u0004 בסופו של דבר, ה\u0003כבשים\u0004 הללו \u0003לשום כבשים נשחטו.\u0004","\u0003אבל\u0004 \u0003ב\u0004מקרה ש\u0003כסבור\u0004 היה בשעה ששחט את הכבשים ש\u0003אילים\u0004 הם, \u0003ו\u0004בדעת זו \u0003שחטן לשום אילים\u0004 — \u0003לא\u0004 עלו הכבשים הללו לשם חובה, אף שבפועל נשחטו שני כבשים. וטעם הדבר: \u0003עקירה\u0004 של שם הקרבן (כבמקרה זה, שעקר במחשבתו את הכבשים והעמידם כאילים), אף שהיתה \u0003בטעות\u0004 — \u0003הויא\u0004 \u0005[הריהי]\u0006 נחשבת כ\u0003עקירה\u0004 של הדבר. \u0003ו\u0004אילו \u0003רבה אמר: עקירה בטעות\u0004 — \u0003לא הויא\u0004 \u0005[איננה]\u0006 נחשבת \u0003עקירה.\u0004","ובענין זה \u0003אמר רבא\u0004 (רבה. וראה \"גרסות\"): \u0003ומותבינן אשמעתין\u0004 \u0005[ואנו מקשים על שמועתנו,\u0006 על ההלכה שלנו עצמנו\u0005]\u0006 ממה ששנינו במשנה בדינם של \u0003הכהנים שפיגלו\u0004 (שחשבו בשעת אחת מעבודות הקרבן לאוכלו מעבר לזמנו הראוי לאכילה. ונעשה בכך הקרבן פיגול, ונאסר לאכילה) בשעת עבודתם \u0003במקדש,\u0004 אם היו \u0003מזידין\u0004 בפיגול זה — הריהם \u0003חייבין\u0004 לשלם לבעלים את דמי הקרבן, שהרי הפסידוהו ממון בפוסלם את קרבנו. ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו הכהנים \u0003שוגגין\u0004 בדבר — הריהם \u0003פטורין\u0004 מתשלום. \u0003ותני עלה\u0004 \u0005[ושנינו\u0006 בברייתא, \u0005עליה,\u0006 על משנה זו\u0005]\u0006 שאף אם פיגלו הכהנים בשוגג — מעשה \u0003פיגולן\u0004 מחיל איסור \u0003פיגול\u0004 על הקרבן, אף על פי שאינם חייבים בתשלום.","ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]\u0006 בהלכה זו? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שמדובר ש\u0003ידע\u0004 הכהן בקרבן ש\u0003חטאת היא,\u0004 שזמן אכילתו יום ולילה, \u0003וקא\u0004 \u0005[והוא]\u0006 \u0003מחשב בה\u0004 בשעת עבודתו שתהא \u0003לשום שלמים\u0004 שזמן אכילתם הוא שני ימים ולילה, ונמצא שחשב לאכול את הקרבן מעבר לזמנו הראוי — וכי \u0003האי\u0004 \u0005[זה]\u0006 ייחשב לכהנים כ\u0003שוגגין?!\u0004 והרי \u0003מזידין הוו\u0004 \u0005[הם]\u0006 בדבר!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן שהיתה זו בהמת קרבן חטאת (שזמן אכילתה הוא כאמור יום ולילה), ו\u0003כסבור\u0004 הכהן בטעות ש\u0003שלמים הוא, וקא\u0004 \u0005[והוא]\u0006 \u0003מחשב\u0004 בשעת עבודתו \u0003בה\u0004 שתהא \u0003לשום שלמים\u0004 (שזמן אכילתם הוא לשני ימים ולילה), ונמצא איפוא שחשב בקרבן זה מחשבת אכילה מעבר לזמנו הראוי, \u0003וקתני\u0004 \u0005[והוא\u0006 התנא \u0005שונה]\u0006 במקרה זה כי \u0003פיגולן\u0004 זה נחשב ל\u0003פיגול\u0004 — \u0003אלמא\u0004 \u0005[מכאן]\u0006 ראיה ש\u0003עקירה בטעות הויא\u0004 \u0005[הריהי]\u0006 נחשבת \u0003עקירה\u0004 ממש, ושלא כדבריי שאין עקירה בטעות נחשבת עקירה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: אין מברייתא זו ראיה שלא כשיטתך, שכן \u0003לעולם\u0004 תפרש שמדובר בה באופן ש\u0003ידע\u0004 הכהן ש\u0003חטאת היא, וקא\u0004 \u0005[והוא]\u0006 \u0003מחשב\u0004 בשעת עבודתו \u0003בה\u0004 שתהא \u0003לשום\u0004 \u0003שלמים,\u0004 ועקירתו הריהי עקירה מדעת ולא מטעות. \u0003ו\u0004באשר לשאלה מדוע כהנים אלה נקראים בברייתא \"שוגגים\"? — שכן מדובר \u0003ב\u0004שגגת הכהן בהלכה, ש\u0003אומר\u0004 (סבור) הוא כי \u0003מותר\u0004 לעשות כן.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' זירא\u0004 על שיטתו של רבא הסבור שעקירה בטעות אינה נחשבת עקירה, ממה ששנינו בברייתא (המובאת בתחילת מסכתנו, ב,ב) כי \u0003ר' שמעון אומר\u0004 ש\u0003כל\u0004 ה\u0003מנחות שנקמצו שלא לשמן\u0004 — הריהן \u0003כשרות\u0004 לגמרי, \u0003ו\u0004אף \u0003עלו לבעלים לשום חובה.\u0004","וטעם הדבר, לפי \u0003שאין המנחות דומות לזבחים\u0004 (קרבנות) לענין זה (שאם נשחטו הזבחים שלא לשמם — לא יצאו הבעלים ידי חובתם), ומדוע? \u0003שהקומץ\u0004 מנחה הנעשית ב\u0003מחבת\u0004 (שהיא כלי שטוח, והדבר הנעשה בה יוצא קשה) \u0003לשום\u0004 מנחת \u0003מרחשת\u0004 (שהיא כלי עמוק, והדבר הנעשה בו יוצא רך) — הלא \u0003מעשיה\u0004 של מנחה זו \u0003מוכיחין עליה\u0004 שהיא \u0003לשום מחבת\u0004 ולא לשם מרחשת. וכן הקומץ את המנחה ה\u0003חרבה\u0004 (מנחת חוטא, שאין בה שמן) \u0003לשום\u0004 מנחה ה\u0003בלולה\u0004 בשמן — הלא \u0003מעשיה מוכיחין עליה\u0004 שהיא באה \u0003לשום\u0004 מנחה \u0003חרבה.\u0004","\u0003אבל בזבחים אינו כן,\u0004 שהרי \u0003שחיטה אחת\u0004 (שווה) היא \u0003לכולן, קבלה אחת\u0004 (שווה) היא \u0003לכולן, זריקה אחת\u0004 (שווה) היא \u0003לכולן,\u0004 וכיון שההבדל בעבודת הקרבן הוא במחשבה, לכך מחשבתו משנה בהם.","ויש לברר את דברי ר' שמעון אלה: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]\u0006 בקמיצה זו של המנחות שנעשתה שלא לשמן\u0005?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003ידע\u0004 הכהן שמנחת \u0003מחבת היא\u0004 זו, \u0003וקא קמיץ לה\u0004 \u0005[והוא קומץ אותה]\u0006 \u0003לשום\u0004 מנחת \u0003מרחשת\u0004 — \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מעשיה\u0004 של מנחה זו אמנם \u0003מוכיחין\u0004 שהיא מנחת מחבת \u0003מאי הוי\u0004 \u0005[מה הוא,\u0006 מה בכך\u0005]?\u0006 \u0003הא מיעקר קא עקיר לה\u0004 \u0005[הרי הוא עוקר אותה]\u0006 במחשבתו בשעת קמיצתו ממנחת מחבת למנחת מרחשת!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן ש\u0003כסבור\u0004 הוא כי מנחת \u0003מרחשת היא\u0004 מנחה זו, \u0003וקא קמיץ לה\u0004 \u0005[והוא קומץ אותה]\u0006 אכן \u0003לשום\u0004 מנחת \u0003מרחשת, וטעה\u0004 בדבר — הרי נלמד מכאן כי במקרה \u0003דהכא\u0004 \u0005[שכאן,\u0006 שכזה\u0005],\u0006 \u0003הוא\u0004 שמכשיר ר' שמעון את המנחה ואינו מחשיב את עקירתו בטעות לעקירה, מפני ש\u0003מעשיה מוכיחין עליה. הא בעלמא\u0004 \u0005[הרי בכלל]\u0006 — \u0003עקירה בטעות הויא\u0004 \u0005[הריהי]\u0006 \u0003עקירה,\u0004 ושלא כשיטת רבא!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לר' זירא בדחיית ראייתו זו: אין להוכיח מכאן, שכן אפשר לומר כי \u0003לעולם\u0004 מדובר בברייתא זו באופן ש\u0003ידע\u0004 שמנחת \u0003מחבת היא\u0004 זו, \u0003וקא קמיץ לה\u0004 \u0005[והוא קומץ אותה]\u0006 \u0003לשום\u0004 מנחת \u0003מרחשת,\u0004","\u0003ודקא\u0004 \u0005[ומה]\u0006 ש\u0003אמרת\u0004 בתוך שאלתך שאף \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מעשיה מוכיחין עליה מאי הוי\u0004 \u0005[מה הוא,\u0006 מה בכך\u0005],\u0006 ומדוע אין המנחה נפסלת במחשבתו זו — בענין זה \u0003רבא\u0004 הולך \u0003לטעמיה\u0004 \u0005[לשיטתו],\u0006 שכך \u0003אמר רבא\u0004 בפירוש דברי ר' שמעון: דווקא \u0003מחשבה\u0004 של פסול ש\u0003לא מינכרא\u0004 \u0005[לא ניכרת]\u0006 לכל, שלא ניכר ממעשיו שהמחשבה אינה נכונה — אותה \u0003פסל רחמנא\u0004 \u0005[פסלה התורה],\u0006 כגון מחשבת שינוי בעלים (שהביאה ראובן וקמצה הכהן לשם שמעון). אבל \u0003מחשבה דמינכרא\u0004 \u0005[שניכרת],\u0006 וכגון שקומץ ממנחת מחבת לשם מנחת מרחשת, שמחשבתו מוכחת שאינה נכונה — \u0003לא פסל רחמנא\u0004 \u0005[לא פסלה התורה].\u0006","קרבנות \u0003התמידין אין מעכבין את\u0004 קרבנות \u0003המוספין,\u0004 שאין הקרבתם של המוספים מותנית בהקרבתם של התמידים. ולכך אף אם לא הוקרבו התמידים, קרבים המוספים. \u0003ו\u0004בדומה לכך \u0003לא המוספין מעכבין את התמידין,\u0004 שאם לא הקריב את קרבן המוסף יכול להקריב את התמיד של בין הערביים וכיוצא בדבר, ביום שקרבים בו שני מוספים, וכגון בראש חודש החל ביום השבת, שקרבים בו מוסף שבת ומוסף ראש חודש, \u0003לא המוספין מעכבין זה את זה,\u0004 שגם אם לא הקריבו מוסף אחד, הריהם מקריבים את המוסף האחר. ובדין שני כבשי התמיד: אף אם \u0003לא הקריבו\u0004 את ה\u0003כבש בבוקר\u0004 לקרבן תמיד של שחר — \u0003יקריבו\u0004 כבש לקרבן התמיד של \u0003בין הערבים,\u0004 שאין זה מעכב את זה.","\u0003אמר ר' שמעון: אימתי\u0004 (באיזה אופן) אמור דין זה שמקריבים את התמיד של בין הערביים, כאשר התמיד של שחר לא הוקרב? \u0003בזמן ש\u0004הכהנים \u0003היו אנוסין\u0004 בדבר, שמחמת אונס לא הוקרב התמיד של שחר, \u0003או\u0004 שהיו הכהנים \u0003שוגגין\u0004 בדבר. \u0003אבל אם היו\u0004 הכהנים \u0003מזידין\u0004 בדבר \u0003ו\u0004בשל כך \u0003לא הקריבו\u0004 את \u0003כבש\u0004 התמיד \u0003בבוקר\u0004 — \u0003לא יקריבו את\u0004 כבש התמיד של \u0003בין הערבים.\u0004 הקטורת היתה מוקטרת פעמיים בכל יום, מחציתה בבוקר ומחציתה בין הערביים.","אם \u0003לא הקטירו\u0004 את המחצית של ה\u0003קטורת בבוקר\u0004 — \u0003יקטירו בין הערבים.\u0004","\u0003אמר ר' שמעון: ו\u0004כאשר לא הוקטרה מחצית הקטורת בבוקר, כדין, \u0003כולה היתה קריבה בין הערבים,\u0004 שהיו מקריבים אז אף את מחצית הקטורת של הבוקר. וטעם ההבדל בין התמיד לבין הקטורת: \u0003שאין מחנכין\u0004 (חונכים, מתחילים בעבודה בפעם הראשונה) \u0003את מזבח הזהב\u0004 שעליו מקטירים את הקטורת \u0003אלא ב\u0004הקטרה של \u0003קטורת הסמים\u0004 בין הערביים, ואז היו מקטירים מנה שלם, \u0003ולא\u0004 את \u0003מזבח העולה\u0004 (עליו קרבים התמידים) \u0003אלא ב\u0004הקרבת ה\u0003תמיד של שחר. ו\u0004עוד בדיני חנוכתם של כלי המקדש: \u0003לא\u0004 היו חונכים \u0003את השולחן\u0004 (שולחן הפנים) \u0003אלא ב\u0004עריכתו של \u0003לחם הפנים ב\u0004יום ה\u0003שבת, ולא\u0004 היו חונכים \u0003את המנורה\u0004 לעבודתה \u0003אלא ב\u0004הדלקתם של \u0003שבעה נרותיה בין הערבים.\u0004","שנינו במשנתנו שהתמידים והמוספים אינם מעכבים אלה את אלה, ובענין זה \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' חייא בר אבין מרב חסדא: ציבור שאין להן\u0004 די בהמות להקרבתם של ה\u0003תמידין ו\u0004ה\u0003מוספין, אי זה מהן קודם\u0004 בהקרבה?","ומבררים בתחילה את הבעיה: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה שאין די בהמות כדי הקרבת קרבנות ה\u0003תמידין דיומיה\u0004 \u0005[של אותו יום]\u0006 \u0003ו\u0004קרבנות ה\u0003מוספין דיומיה\u0004 \u0005[של אותו יום]\u0006 — אין מקום להסתפק בדבר, שהרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שה\u0003תמידין עדיפי\u0004 \u0005[עדיפים]\u0006 על פני המוספים, ויוקרבו הקרבנות הללו לתמידים ולא למוספים. \u0003דהוו להו\u0004 \u0005[שהרי הם]\u0006 לעומת המוספים \u0003תדיר\u0004 (המצוי) יותר, שהרי התמידים קרבים בכל יום ואילו המוספים אינם קרבים אלא לעתים רחוקות, בשבתות ובמועדים שונים, \u0003ו\u0004נוסף לזה יש בהם גם מעלת ה\u0003מקודש\u0004 יותר!","\u0003אלא\u0004 צריכים לומר שמדובר שיש להם קרבנות כדי הקרבת שני התמידים של היום, ושנים נוספים כדי הקרבת קרבנות ה\u0003תמידין\u0004 ש\u0003למחר, ו\u0004לא יותר, כך שאין להם גם כדי הקרבתם של ה\u0003מוספין דהאידנא\u0004 \u0005[של עכשיו,\u0006 של יום זה\u0005],\u0006 והשאלה היא: אלו קרבנות הם העדיפים, האם קרבנות ה\u0003תמידין\u0004 (של מחר) \u0003עדיפי\u0004 \u0005[עדיפים],\u0006 \u0003שכן\u0004 קרבן זה הריהו \u0003תדיר\u0004 לעומת המוספים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי קרבנות ה\u0003מוספין\u0004 (של היום) הם \u0003עדיפי\u0004 \u0005[עדיפים],\u0006 \u0003דהוו להו\u0004 \u0005[שהרי הם,\u0006 יש להם\u0005]\u0006 מעלת \u0003מקודש,\u0004 ומעלה זו אינה קיימת אצל התמידים של מחר, כיון שעדיין לא הגיע זמנם?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לר' חייא בר אבין: אין זו בעיה, שהרי כבר \u0003תניתוה\u0004 \u0005[שנינו אותה,\u0006 את פתרונה, במשנתנו\u0005].\u0006 ששנינו בה: \u0003התמידין אין מעכבין את המוספין, ולא המוספין מעכבין את התמידין, ולא המוספין מעכבין זה את זה.\u0004","ויש לברר את דברי המשנה: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דאית ליה\u0004 \u0005[אם תאמר\u0006 שמדובר באופן \u0005שיש לו]\u0006 את כל הקרבנות הנצרכים לאלה ולאלה, \u0003ו\u0004כל עיקרה של ההלכה היא רק לענין \u0003לקדם\u0004 \u0005[הקדמה]\u0006 בהקרבה תחילה, אין לומר כן, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין שלא יהא דבר קודם ל\u0004הקרבת \u0003תמיד של שחר? תלמוד לומר\u0004 \"...ובער עליה הכהן עצים בבקר בבקר \u0003וערך עליה העלה\",\u0004","\u0003ואמר רבא:\u0004 מה שנאמר \u0003\"העלה\"\u0004 בה\"א הידיעה — כוונתו לעולה מיוחדת, ה\u0003עולה\u0004 ה\u0003ראשונה,\u0004 וללמד שעולת התמיד היא הקרבן הקרב בראשונה בכל יום במקדש. הרי איפוא שמעכבים התמידים את המוספים שלא יוקרבו לפניהם!"],["\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הוא שמדובר במשנתנו באופן \u0003דלית ליה\u0004 \u0005[שאין לו,\u0006 לגזבר ההקדש\u0005]\u0006 מספר בהמות כדי הקרבתם גם לתמידים וגם למוספים. \u0003ו\u0004מעתה יש להוסיף ולברר באיזה אופן עוסקת משנתנו: \u0003אי\u0004 \u0005[אם]\u0006 כשאין די בהמות גם לתמידים וגם למוספים \u0003דיומיה\u0004 \u0005[של אותו יום]\u0006 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 אין הם מעכבים זה את זה, ויכול הוא להקריב זה או זה? והלא כלל הוא כי הדבר שיש בו מעלת \u0003תדיר\u0004 ומעלת מקודש (כקרבן התמיד) \u0003ו\u0004כנגדו דבר שיש בו רק מעלת \u0003מקודש\u0004 (כקרבן המוסף) — זה שהוא \u0003תדיר\u0004 ומקודש \u0003עדיף,\u0004 וראוי היה איפוא במקרה שכזה שהתמידים יעכבו את המוספים!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר במשנתנו באופן שיש להם מספיק בהמות לצורך התמידים של היום, אלא שאין להם גם כדי הקרבת תמידים של \u0003מחר, וקתני\u0004 \u0005[ושנה]\u0006 התנא של משנתנו כי \u0003אין\u0004 הם \u0003מעכבין זה את זה\u0004 — \u0003אלמא\u0004 \u0005[\u0006נסיק \u0005מכאן],\u0006 \u0003כי הדדי נינהו\u0004 \u0005[כמו שווים הם,\u0006 שזה כמו זה\u0005],\u0006 ויכול הוא להקריב מהם לאיזה קרבן שירצה. ונפתרה איפוא בעייתך!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב חסדא בדחיית דבריו: אינך יכול להביא ממשנתנו ראיה זו, שכן יש מקום לומר כי \u0003לעולם\u0004 מדובר בה באופן \u0003דאית להו\u0004 \u0005[שיש להם]\u0006 בהמות כדי הצורך גם לתמידים וגם למוספים של היום, \u0003ו\u0004השאלה היתה באמת לענין \u0003לקדם,\u0004 אם מעכבים התמידים את המוספים, שלא יוקרבו לפניהם. \u0003ודקא קשיא\u0004 \u0005[ומה שהיה קשה]\u0006 \u0003לך\u0004 ממה שאמרנו \u0003שלא יהא דבר קודם\u0004 לתמיד של שחר — דבר זה אינו אלא ל\u0003מצוה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 שכך ראוי לכתחילה לעשות, ואולם אין הוא בא לעכב.","ובענין בעייתו זו של ר' חייא בר אבין כיצד יש לנהוג כאשר אין להם מספיק בהמות גם למוספים של היום וגם לתמידים של מחר, מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנה בערכין כי \u0003אין פוחתין מששה טלאים המבוקרין\u0004 (הבדוקים מכל מום) שיהיו \u0003בלשכת הטלאים\u0004 שבמקדש, \u0003כדי\u0004 (שיש בהם די) \u0003ל\u0004קרבנות הציבור של \u0003שבת\u0004 (שקרבים בה שני טלאים לתמיד) \u0003ולשני ימים טובים של ראש השנה\u0004 הסמוכים ליום השבת, שבכל יום מהם קרבים שני טלאים, ונמצא מנין כולם ששה טלאים.","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]\u0006 במשנה זו\u0005?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר בה במקרה \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 לגזבר ההקדש\u0005]\u0006 די טלאים כדי הקרבת \u0003תמידין ומוספין\u0004 הבאים בימים הללו — הלא אין די בששה טלאים, שכן \u0003טובא הוו\u0004 \u0005[הרבה הם]\u0006 הקרבנות הנצרכים לימים הללו (ועולה מספרם לעשרים ושנים קרבנות: שבעה כבשים ליום הראשון של ראש השנה, ושבעה נוספים ליום השני של ראש השנה, ושני כבשים הבאים למוספי השבת, וששה כבשים הבאים לתמידים של שבת ושני ימי ראש השנה)!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נלמד מכאן שמדובר במשנה זו במקרה \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 מספיק קרבנות, ובאה המשנה להשמיענו כי הכבשים הנמצאים באים לקרבנות התמיד של שלושת הימים, ובכללם אף לראש השנה (החל מחר ומחרתיים), ואין הם קרבים כמוספי השבת, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 ראיה כי ה\u0003תמידין\u0004 של מחר \u0003עדיפי\u0004 \u0005[עדיפים]\u0006 על פני המוספים של היום!","ודוחים: \u0003לא,\u0004 אין מכאן ראיה, שיש לומר כי \u0003לעולם\u0004 מדברת המשנה במקרה \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 מספיק בהמות לצורך כל קרבנות השבת וראש השנה. וזה שאמרה המשנה שאין פוחתים מששה טלאים בלשכת הטלאים, ולא הזכירה מספר רב יותר, הוא מפני שרק בקרבן התמיד צריך לבדוק את הטלאים ארבעה ימים מראש, \u0003ו\u0004לפי זה \u0003הכי קא אמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונת התנא\u0005]:\u0006 \u0003אין פוחתין מששה טלאים המבוקרין בלשכת הטלאים,\u0004 לצורך קרבן התמיד, \u0003ארבעה ימים קודם\u0004 ה\u0003שחיטה.\u0004 וכשנוטלים שני טלאים בכל יום להקריבם לתמיד, ומביאים שנים חדשים ומבקרים אותם — יש תמיד ששה טלאים בלשכה, כמספר התמידים של שבת ושני ימים טובים של ראש השנה. \u0003ו\u0004כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006 — כשיטת \u0003בן בג בג היא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003בן בג בג אומר: מנין לתמיד שטעון ביקור\u0004 (בדיקה ממומים) \u0003ארבעה ימים קודם\u0004 ה\u0003שחיטה? תלמוד לומר\u0004 בקרבן התמיד: \u0003\"תשמרו להקריב לי במועדו\"\u0004 (במדבר כח, ב), ומאחר \u0003ולהלן\u0004 בקרבן הפסח, \u0003הוא\u0004 הכתוב \u0003אומר:\u0004 \"ובעשור לחודש הזה ויקחו להם איש שה לבית אבות... \u0003והיה לכם למשמרת עד ארבעה עשר יום\u0004 לחודש הראשון\" (שמות יב, ג—ו), למדים זה מזה,","\u0003מה להלן\u0004 בקרבן הפסח — הריהו \u0003טעון ביקור ארבעה ימים קודם שחיטה,\u0004 מעשור לחודש עד ארבעה עשר בו — \u0003אף כאן\u0004 בקרבן תמיד, הריהו \u0003טעון ביקור ארבעה ימים קודם שחיטה.\u0004 ואם כן, דין מיוחד הוא בתמיד ולא בקרבנות אחרים.","לעיל הוזכרו דברי המשנה שאין פוחתים מששה טלאים המבוקרים בלשכת הטלאים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי\u0004 בשאלה: מספר \u0003הני\u0004 \u0005[אלה]\u0006 הטלאים שצריכים שיהיו בלשכת הטלאים הוא \u0003ששה\u0004 בלבד? והלא לפחות \u0003שבעה הוו\u0004 \u0005[היו]\u0006 צריכים להיות בלשכת הטלאים, \u0003דהא איכא\u0004 \u0005[שהרי יש]\u0006 עוד טלה נוסף לצורך קרבן התמיד \u0003דצפרא דתלתא בשבתא\u0004 \u0005[של בוקר של\u0006 היום \u0005השלישי בשבת],\u0006 שאף הוא היה צריך להיות מוכן להקרבה (אחרי ביקור ממום). שכן אם חלו שני ימי ראש השנה בימים ראשון ושני בשבוע, נמצא שלא יספיקו לבקר את הטלה העומד להקרבה בבוקרו של יום שלישי!","השיב רב אשי לרבינא: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 מדוע אתה שואל שהיו צריכים להיות שבעה טלאים בלשכת הטלאים, והרי \u0003תמניא הוו\u0004 \u0005[שמונה היו]\u0006 צריכים להיות שם, \u0003דהאיכא\u0004 \u0005[ש\u0006כן \u0005יש]\u0006 טלה הקרב כתמיד \u0003דפניא דמעלי שבתא\u0004 \u0005[של בין הערביים בערב שבת]!\u0006","ודחה רבינא: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]\u0006 על המשנה, שכן \u0003דלבתר דאקריב\u0004 \u0005[שאחרי שהקריב]\u0006 את קרבן התמיד של בין הערביים שביום ששי, צריכים להיות עוד שישה טלאים, \u0003קאמר\u0004 \u0005[הוא,\u0006 התנא במשנה התכוון \u0005לומר],\u0006"]]};
